insert into medical_terms (id, term_en, term_fr, term_ar, definition_en, definition_fr, definition_ar, etymology, clinical_pearl, mnemonic, module, chapter, example_en, example_fr, example_ar, ipa_phonetic) values
(1, 'Heart', 'Cœur', 'القلب', 'The muscular organ that pumps blood through the circulatory system.', 'L''organe musculaire qui propulse le sang à travers la circulation.', 'العضو العضلي الذي يضخ الدم في جهاز الدوران.', 'Greek: kardia — ''heart''', 'The apex lies at the 5th intercostal space midclavicular line; base directed superiorly and to the right.', '', 'Anatomie', 'Angiologie', 'The heart is located in the middle mediastinum.', 'Le cœur est situé dans le médiastin moyen.', 'يقع القلب في المنصف الأوسط.', '/hɑːrt/'),
(2, 'Atrium', 'Oreillette', 'الأذين', 'Upper chamber of the heart that receives blood returning to the heart.', 'Cavité supérieure du cœur recevant le sang qui revient au cœur.', 'تجويف علوي للقلب يستقبل الدم العائد إليه.', 'Latin: atrium — ''inner room / courtyard''', 'Right atrium receives deoxygenated blood; left atrium receives oxygenated blood from the four pulmonary veins.', '', 'Anatomie', 'Angiologie', 'The right atrium receives blood from the venae cavae.', 'L''oreillette droite reçoit le sang des veines caves.', 'يستقبل الأذين الأيمن الدم من الأوردة الأجواف.', '/ˈeɪ.tri.əm/'),
(3, 'Ventricle', 'Ventricule', 'البطين', 'Lower chamber of the heart that pumps blood out of the heart.', 'Cavité inférieure du cœur qui expulse le sang hors du cœur.', 'تجويف سفلي للقلب يطرد الدم خارج القلب.', 'Latin: ventriculus — ''little belly''', 'The left ventricular wall is about three times thicker than the right, to overcome systemic vascular resistance.', '', 'Anatomie', 'Angiologie', 'The left ventricle pumps blood into the aorta.', 'Le ventricule gauche propulse le sang dans l''aorte.', 'يضخ البطين الأيسر الدم إلى الأبهر.', '/ˈven.trɪ.kəl/'),
(4, 'Heart valve', 'Valve cardiaque', 'صمام قلبي', 'Structure that ensures one-way blood flow within the heart.', 'Structure assurant un flux sanguin unidirectionnel dans le cœur.', 'بنية تضمن تدفق الدم في اتجاه واحد داخل القلب.', '', 'Two atrioventricular valves (mitral, tricuspid) and two semilunar valves (aortic, pulmonary).', '', 'Anatomie', 'Angiologie', 'The heart has four valves.', 'Le cœur possède quatre valves.', 'يحتوي القلب على أربعة صمامات.', '/hɑːrt vælv/'),
(5, 'Tricuspid valve', 'Valve tricuspide', 'الصمام ثلاثي الشرفات', 'Valve between the right atrium and right ventricle, with three leaflets.', 'Valve entre l''oreillette droite et le ventricule droit, à trois feuillets.', 'صمام بين الأذين الأيمن والبطين الأيمن، ذو ثلاث شرفات.', 'Latin: tri- (''three'') + cuspis (''point'')', 'Tricuspid regurgitation is common in intravenous drug users (Staphylococcus aureus endocarditis) and in cor pulmonale.', '', 'Anatomie', 'Angiologie', 'The tricuspid valve prevents backflow into the right atrium.', 'La valve tricuspide empêche le reflux vers l''oreillette droite.', 'يمنع الصمام ثلاثي الشرفات ارتداد الدم إلى الأذين الأيمن.', '/traɪˈkʌs.pɪd vælv/'),
(6, 'Mitral valve', 'Valve mitrale', 'الصمام التاجي', 'Valve between the left atrium and left ventricle, with two leaflets.', 'Valve entre l''oreillette gauche et le ventricule gauche, à deux feuillets.', 'صمام بين الأذين الأيسر والبطين الأيسر، ذو شرفتين.', 'Named after the mitre, a bishop''s hat it resembles in shape', 'Mitral stenosis is almost always rheumatic in origin; mitral valve prolapse is the most common valvular anomaly.', '', 'Anatomie', 'Angiologie', 'The mitral valve is located between the left atrium and left ventricle.', 'La valve mitrale se trouve entre l''oreillette gauche et le ventricule gauche.', 'يقع الصمام التاجي بين الأذين الأيسر والبطين الأيسر.', '/ˈmaɪ.trəl vælv/'),
(7, 'Pulmonary valve', 'Valve pulmonaire', 'الصمام الرئوي', 'Valve at the exit of the right ventricle opening into the pulmonary artery.', 'Valve à la sortie du ventricule droit s''ouvrant dans l''artère pulmonaire.', 'صمام عند مخرج البطين الأيمن يفتح في الشريان الرئوي.', '', 'Pulmonary stenosis is a feature of Noonan syndrome and of tetralogy of Fallot.', '', 'Anatomie', 'Angiologie', 'The pulmonary valve opens during right ventricular systole.', 'La valve pulmonaire s''ouvre pendant la systole ventriculaire droite.', 'يفتح الصمام الرئوي أثناء انقباض البطين الأيمن.', '/ˈpʌl.mə.ner.i vælv/'),
(8, 'Aortic valve', 'Valve aortique', 'الصمام الأبهري', 'Valve at the exit of the left ventricle opening into the aorta.', 'Valve à la sortie du ventricule gauche s''ouvrant dans l''aorte.', 'صمام عند مخرج البطين الأيسر يفتح في الأبهر.', '', 'A bicuspid aortic valve is the most common congenital heart defect (1–2% of births), predisposing to early stenosis.', '', 'Anatomie', 'Angiologie', 'The aortic valve has three semilunar cusps.', 'La valve aortique possède trois sigmoïdes.', 'يحتوي الصمام الأبهري على ثلاث شرفات هلالية.', '/eɪˈɔːr.tɪk vælv/'),
(9, 'Myocardium', 'Myocarde', 'عضل القلب', 'The muscular middle layer of the heart wall.', 'La couche musculaire moyenne de la paroi cardiaque.', 'الطبقة العضلية الوسطى لجدار القلب.', 'Greek: mys (''muscle'') + kardia (''heart'')', 'Myocardial infarction is ischemic necrosis of this layer, typically with elevated serum troponin.', '', 'Anatomie', 'Angiologie', 'The myocardium is the thickest layer of the heart wall.', 'Le myocarde est la couche la plus épaisse de la paroi cardiaque.', 'عضل القلب هو أثخن طبقات جدار القلب.', '/ˌmaɪ.əˈkɑːr.di.əm/'),
(10, 'Endocardium', 'Endocarde', 'الشغاف القلبي', 'The thin inner lining of the heart chambers and valves.', 'La fine paroi interne tapissant les cavités cardiaques et les valves.', 'البطانة الرقيقة الداخلية للتجاويف القلبية والصمامات.', 'Greek: endon (''within'') + kardia (''heart'')', 'Infective endocarditis produces vegetations on this lining; Roth spots and Osler nodes are classic signs.', '', 'Anatomie', 'Angiologie', 'The endocardium lines the interior of the heart.', 'L''endocarde tapisse l''intérieur du cœur.', 'يبطن الشغاف القلبي تجويف القلب.', '/ˌen.doʊˈkɑːr.di.əm/'),
(11, 'Pericardium', 'Péricarde', 'التامور', 'Double-walled sac enclosing and protecting the heart.', 'Sac à double paroi enveloppant et protégeant le cœur.', 'كيس ذو جدارين يحيط بالقلب ويحميه.', 'Greek: peri (''around'') + kardia (''heart'')', 'Pericarditis produces a friction rub and diffuse ST elevation; a large effusion may cause cardiac tamponade.', '', 'Anatomie', 'Angiologie', 'The pericardium anchors the heart in the mediastinum.', 'Le péricarde fixe le cœur dans le médiastin.', 'يثبّت التامور القلب في المنصف.', '/ˌper.ɪˈkɑːr.di.əm/'),
(12, 'Aorta', 'Aorte', 'الشريان الأبهر', 'The largest artery in the body, carrying blood from the left ventricle.', 'La plus grande artère du corps, transportant le sang du ventricule gauche.', 'أكبر شريان في الجسم، ينقل الدم من البطين الأيسر.', 'Greek: aortē — ''to lift / to carry''', 'Divided into ascending, arch, thoracic and abdominal segments; coarctation causes radio-femoral pulse delay.', '', 'Anatomie', 'Angiologie', 'The aorta distributes blood to the whole body.', 'L''aorte distribue le sang à tout le corps.', 'يوزّع الأبهر الدم على كامل الجسم.', '/eɪˈɔːr.tə/'),
(13, 'Artery', 'Artère', 'شريان', 'Blood vessel carrying blood away from the heart.', 'Vaisseau sanguin transportant le sang du cœur vers les organes.', 'وعاء دموي ينقل الدم من القلب إلى الأعضاء.', 'Greek: arteria — ''windpipe / air vessel''', 'A prominent tunica media of smooth muscle lets arteries withstand and dampen pulsatile pressure.', '', 'Anatomie', 'Angiologie', 'Arteries have thicker walls than veins.', 'Les artères ont des parois plus épaisses que les veines.', 'للشرايين جدران أسمك من الأوردة.', '/ˈɑːr.tər.i/'),
(14, 'Vein', 'Veine', 'وريد', 'Blood vessel carrying blood back to the heart.', 'Vaisseau sanguin ramenant le sang vers le cœur.', 'وعاء دموي يعيد الدم إلى القلب.', 'Latin: vena — ''blood vessel / vein''', 'Valve incompetence causes varicose veins, typically in the lower-limb saphenous system.', '', 'Anatomie', 'Angiologie', 'Veins contain valves that prevent backflow.', 'Les veines contiennent des valves empêchant le reflux.', 'تحتوي الأوردة على صمامات تمنع ارتداد الدم.', '/veɪn/'),
(15, 'Capillary', 'Capillaire', 'شعيرة دموية', 'The smallest blood vessels, where gas and nutrient exchange occurs.', 'Les plus petits vaisseaux, lieu des échanges gazeux et nutritifs.', 'أصغر الأوعية الدموية، حيث يتم التبادل الغازي والمغذي.', 'Latin: capillaris — ''of hair / hair-like''', 'Starling forces govern filtration across the capillary wall; total capillary surface area is about 600 m².', '', 'Anatomie', 'Angiologie', 'Capillaries connect the arterial and venous systems.', 'Les capillaires relient les systèmes artériel et veineux.', 'تربط الشعيرات الدموية بين النظامين الشرياني والوريدي.', '/ˈkæp.ə.ler.i/'),
(16, 'Blood', 'Sang', 'دم', 'Fluid connective tissue circulating through the cardiovascular system.', 'Tissu conjonctif liquide circulant dans le système cardiovasculaire.', 'نسيج ضام سائل يجري في الجهاز القلبي الوعائي.', '', 'Adult blood volume is about 5 L: roughly 55% plasma and 45% formed elements.', '', 'Anatomie', 'Angiologie', 'Blood transports oxygen, nutrients and waste products.', 'Le sang transporte l''oxygène, les nutriments et les déchets.', 'ينقل الدم الأكسجين والمغذيات والفضلات.', '/blʌd/'),
(17, 'Erythrocyte', 'Érythrocyte (globule rouge)', 'كرية الدم الحمراء', 'Oxygen-carrying cell of the blood, biconcave and anucleate.', 'Cellule sanguine transportant l''oxygène, biconcave et sans noyau.', 'خلية دموية تحمل الأكسجين، مقعّرة الوجهين وعديمة النواة.', 'Greek: erythros (''red'') + kytos (''cell'')', 'Lifespan of about 120 days; each gram of hemoglobin binds roughly 1.34 mL of oxygen.', '', 'Anatomie', 'Angiologie', 'Erythrocytes give blood its red color.', 'Les érythrocytes donnent au sang sa couleur rouge.', 'تمنح كريات الدم الحمراء الدم لونه الأحمر.', '/ɪˈrɪθ.rə.saɪt/'),
(18, 'Leukocyte', 'Leucocyte (globule blanc)', 'كرية الدم البيضاء', 'Cell of the immune system defending the body against infection.', 'Cellule du système immunitaire défendant l''organisme contre l''infection.', 'خلية مناعية تدافع الجسم ضد العدوى.', 'Greek: leukos (''white'') + kytos (''cell'')', 'Divided into granulocytes (neutrophils, eosinophils, basophils) and agranulocytes (lymphocytes, monocytes).', '', 'Anatomie', 'Angiologie', 'Leukocyte counts rise during infection.', 'Le nombre de leucocytes augmente pendant une infection.', 'يرتفع عدد كريات الدم البيضاء أثناء العدوى.', '/ˈluː.kə.saɪt/'),
(19, 'Platelet', 'Plaquette (thrombocyte)', 'صفيحة دموية', 'Small cell fragment essential for blood clotting.', 'Petit fragment cellulaire essentiel à la coagulation du sang.', 'جزء خلوي صغير أساسي لتخثر الدم.', '', 'Produced by megakaryocytes; counts above 1,000 × 10⁹/L carry a high thrombotic risk.', '', 'Anatomie', 'Angiologie', 'Platelets aggregate at sites of vascular injury.', 'Les plaquettes s''agrègent aux sites de lésion vasculaire.', 'تتجمع الصفيحات الدموية في مواضع إصابة الأوعية.', '/ˈpleɪt.lət/'),
(20, 'Plasma', 'Plasma', 'بلازما الدم', 'The liquid component of blood, mostly water with dissolved proteins.', 'La composante liquide du sang, surtout de l''eau et des protéines dissoutes.', 'المكوّن السائل للدم، يتكون أساساً من الماء وبروتينات مذابة.', '', 'Main proteins: albumin (oncotic pressure), globulins (immunity), and fibrinogen (coagulation).', '', 'Anatomie', 'Angiologie', 'Plasma carries blood cells and platelets.', 'Le plasma transporte les cellules sanguines et les plaquettes.', 'تحمل البلازما خلايا الدم والصفيحات.', '/ˈplæz.mə/'),
(21, 'Pulse', 'Pouls', 'النبض', 'Rhythmic expansion of an artery felt as the heart beats.', 'Expansion rythmique d''une artère perçue à chaque battement cardiaque.', 'تمدد إيقاعي للشريان يُحس مع كل نبضة قلب.', 'Latin: pulsus — ''a beating / stroke''', 'Assessed for rate, rhythm and character; bounding pulses occur in carbon dioxide retention.', '', 'Anatomie', 'Angiologie', 'The radial pulse is felt at the wrist.', 'Le pouls radial se perçoit au poignet.', 'يُحس النبض الكعبري عند الرسغ.', '/pʌls/'),
(22, 'Blood pressure', 'Pression artérielle', 'ضغط الدم الشرياني', 'The force exerted by blood against the walls of the arteries.', 'La force exercée par le sang sur la paroi des artères.', 'القوة التي يمارسها الدم على جدران الشرايين.', '', 'Hypertension is defined as a persistent reading at or above 140/90 mmHg.', '', 'Anatomie', 'Angiologie', 'Blood pressure is measured in millimeters of mercury.', 'La pression artérielle se mesure en millimètres de mercure.', 'يُقاس ضغط الدم بمليمترات الزئبق.', '/blʌd ˈpreʃ.ər/'),
(23, 'Pulmonary circulation', 'Circulation pulmonaire', 'الدورة الرئوية', 'Circulation between the heart and lungs, where blood is oxygenated.', 'Circulation entre le cœur et les poumons, où le sang s''oxygène.', 'الدورة بين القلب والرئتين، حيث يتأكسد الدم.', '', 'The only circulation in which arteries carry deoxygenated blood and veins carry oxygenated blood.', '', 'Anatomie', 'Angiologie', 'Pulmonary circulation is a low-pressure system.', 'La circulation pulmonaire est un système à basse pression.', 'الدورة الرئوية نظام منخفض الضغط.', '/ˈpʌl.mə.ner.i ˌsɜːr.kjəˈleɪ.ʃən/'),
(24, 'Systemic circulation', 'Circulation systémique', 'الدورة الجهازية', 'Circulation between the heart and the rest of the body.', 'Circulation entre le cœur et le reste de l''organisme.', 'الدورة بين القلب وباقي الجسم.', '', 'Supplies all tissues except the pulmonary alveoli, which are served by pulmonary circulation.', '', 'Anatomie', 'Angiologie', 'Systemic circulation delivers oxygen to all tissues.', 'La circulation systémique apporte l''oxygène à tous les tissus.', 'تورد الدورة الجهازية الأكسجين لجميع الأنسجة.', '/sɪˈstem.ɪk ˌsɜːr.kjəˈleɪ.ʃən/'),
(25, 'Coronary artery', 'Artère coronaire', 'الشريان التاجي', 'Artery supplying the heart muscle itself.', 'Artère vascularisant le muscle cardiaque lui-même.', 'شريان يغذي عضلة القلب نفسها.', 'Latin: corona (''crown''), from its encircling course around the heart', 'Occlusion of the left anterior descending artery is the classic ''widow-maker'' infarct.', '', 'Anatomie', 'Angiologie', 'The left coronary artery divides into two branches.', 'L''artère coronaire gauche se divise en deux branches.', 'ينقسم الشريان التاجي الأيسر إلى فرعين.', '/ˈkɔːr.ə.ner.i ˈɑːr.tər.i/'),
(26, 'Vena cava', 'Veine cave', 'الوريد الأجوف', 'Large vein returning deoxygenated blood to the right atrium.', 'Grande veine ramenant le sang désaturé vers l''oreillette droite.', 'وريد كبير يعيد الدم غير المؤكسج إلى الأذين الأيمن.', 'Latin: vena (''vein'') + cavus (''hollow'')', 'Superior vena cava syndrome causes facial and upper-limb congestion, usually from a mediastinal malignancy.', '', 'Anatomie', 'Angiologie', 'The superior and inferior venae cavae drain into the right atrium.', 'Les veines caves supérieure et inférieure se jettent dans l''oreillette droite.', 'يصب الوريدان الأجوفان العلوي والسفلي في الأذين الأيمن.', '/ˈviː.nə ˈkeɪ.və/'),
(27, 'Femoral artery', 'Artère fémorale', 'الشريان الفخذي', 'Large artery supplying the lower limb, continuation of the external iliac artery.', 'Artère importante vascularisant le membre inférieur, prolongement de l''iliaque externe.', 'شريان كبير يغذي الطرف السفلي، امتداد للشريان الحرقفي الخارجي.', 'Latin: femur — ''Femur / Thigh''', 'Its pulse is palpable at the mid-inguinal point; it is the standard route for cardiac catheterization.', '', 'Anatomie', 'Angiologie', 'The femoral artery runs below the inguinal ligament.', 'L''artère fémorale passe sous le ligament inguinal.', 'يمر الشريان الفخذي تحت الرباط الأربي.', '/ˈfem.ər.əl ˈɑːr.tər.i/'),
(28, 'Jugular vein', 'Veine jugulaire', 'الوريد الوداجي', 'Vein of the neck returning blood from the head and brain.', 'Veine du cou ramenant le sang de la tête et du cerveau.', 'وريد في الرقبة يعيد الدم من الرأس والدماغ.', 'Latin: jugulum — ''neck / collarbone''', 'The internal jugular vein is the preferred route for central venous catheterization.', '', 'Anatomie', 'Angiologie', 'The internal jugular vein drains the brain.', 'La veine jugulaire interne draine le cerveau.', 'يصرف الوريد الوداجي الباطن الدم من الدماغ.', '/ˈdʒʌɡ.jə.lər veɪn/'),
(29, 'Heart rate', 'Fréquence cardiaque', 'معدل ضربات القلب', 'The number of heart beats per minute.', 'Le nombre de battements cardiaques par minute.', 'عدد نبضات القلب في الدقيقة.', '', 'Set by the sinoatrial node; bradycardia is below 60 bpm and tachycardia above 100 bpm.', '', 'Anatomie', 'Angiologie', 'The normal resting heart rate is 60 to 100 beats per minute.', 'La fréquence cardiaque normale au repos est de 60 à 100 battements par minute.', 'معدل ضربات القلب الطبيعي في الراحة يتراوح بين 60 و100 نبضة في الدقيقة.', '/hɑːrt reɪt/'),
(30, 'Cardiac cycle', 'Cycle cardiaque', 'الدورة القلبية', 'The sequence of events in one complete heartbeat.', 'L''enchaînement des événements d''un battement cardiaque complet.', 'تسلسل أحداث نبضة قلبية كاملة.', 'Greek: καρδία (kardía) — ''Heart''', 'The first heart sound (S1) marks mitral and tricuspid valve closure; the second (S2) the semilunar valves.', '', 'Anatomie', 'Angiologie', 'The cardiac cycle consists of systole and diastole.', 'Le cycle cardiaque comprend la systole et la diastole.', 'تتكون الدورة القلبية من الانقباض والانبساط.', '/ˈkɑːr.di.æk ˈsaɪ.kəl/'),
(31, 'Pulmonary artery', 'Artère pulmonaire', 'الشريان الرئوي', 'The artery carrying deoxygenated blood from the heart to the lungs', 'Artère transportant le sang désoxygéné du cœur vers les poumons', 'الشريان الذي ينقل الدم غير المؤكسج من القلب إلى الرئتين', '', '', '', 'Anatomie', 'Angiologie', 'The pulmonary artery is the artery carrying deoxygenated blood from the heart to the lungs.', 'L''artère pulmonaire est artère transportant le sang désoxygéné du cœur vers les poumons.', 'الشريان الرئوي هو الشريان الذي ينقل الدم غير المؤكسج من القلب إلى الرئتين.', '/ˈpʌlmənɛri ˈɑːrtəri/'),
(32, 'Carotid artery', 'Artère carotide', 'الشريان السباتي', 'The major artery supplying blood to the head and neck', 'Artère principale alimentant la tête et le cou en sang', 'الشريان الرئيسي الذي يزود الرأس والعنق بالدم', '', '', '', 'Anatomie', 'Angiologie', 'The carotid artery is the major artery supplying blood to the head and neck.', 'L''artère carotide est artère principale alimentant la tête et le cou en sang.', 'الشريان السباتي هو الشريان الرئيسي الذي يزود الرأس والعنق بالدم.', '/kəˈrɒtɪd ˈɑːrtəri/'),
(33, 'Subclavian artery', 'Artère sous-clavière', 'الشريان تحت الترقوة', 'The artery supplying blood to the upper limb', 'Artère alimentant le membre supérieur en sang', 'الشريان الذي يزود الطرف العلوي بالدم', '', '', '', 'Anatomie', 'Angiologie', 'The subclavian artery is the artery supplying blood to the upper limb.', 'L''artère sous-clavière est artère alimentant le membre supérieur en sang.', 'الشريان تحت الترقوة هو الشريان الذي يزود الطرف العلوي بالدم.', '/sʌbˈkleɪviən ˈɑːrtəri/'),
(34, 'Brachial artery', 'Artère brachiale (humérale)', 'الشريان العضدي', 'The major artery of the upper arm', 'Artère principale du bras', 'الشريان الرئيسي في الذراع', '', '', '', 'Anatomie', 'Angiologie', 'The brachial artery is the major artery of the upper arm.', 'L''artère brachiale (humérale) est artère principale du bras.', 'الشريان العضدي هو الشريان الرئيسي في الذراع.', '/ˈbreɪkiəl ˈɑːrtəri/'),
(35, 'Radial artery', 'Artère radiale', 'الشريان الكعبري', 'The artery of the forearm used to take the pulse at the wrist', 'Artère de l''avant-bras utilisée pour prendre le pouls au poignet', 'شريان الساعد المستخدم لقياس النبض عند الرسغ', '', '', '', 'Anatomie', 'Angiologie', 'The radial artery is the artery of the forearm used to take the pulse at the wrist.', 'L''artère radiale est artère de l''avant-bras utilisée pour prendre le pouls au poignet.', 'الشريان الكعبري هو شريان الساعد المستخدم لقياس النبض عند الرسغ.', '/ˈreɪdiəl ˈɑːrtəri/'),
(36, 'Popliteal artery', 'Artère poplitée', 'الشريان المأبضي', 'The artery behind the knee', 'Artère derrière le genou', 'الشريان خلف الركبة', '', '', '', 'Anatomie', 'Angiologie', 'The popliteal artery is the artery behind the knee.', 'L''artère poplitée est artère derrière le genou.', 'الشريان المأبضي هو الشريان خلف الركبة.', '/pɒpˈlɪtiəl ˈɑːrtəri/'),
(37, 'Portal vein', 'Veine porte', 'الوريد البابي', 'The vein carrying blood from the digestive organs to the liver', 'Veine transportant le sang des organes digestifs vers le foie', 'الوريد الذي ينقل الدم من الأعضاء الهضمية إلى الكبد', '', '', '', 'Anatomie', 'Angiologie', 'The portal vein is the vein carrying blood from the digestive organs to the liver.', 'La veine porte est veine transportant le sang des organes digestifs vers le foie.', 'الوريد البابي هو الوريد الذي ينقل الدم من الأعضاء الهضمية إلى الكبد.', '/ˈpɔːrtəl veɪn/'),
(38, 'Saphenous vein', 'Veine saphène', 'الوريد الصافن', 'The longest vein in the body, running along the leg', 'La veine la plus longue du corps, s''étendant le long de la jambe', 'أطول وريد في الجسم، يمتد على طول الساق', '', '', '', 'Anatomie', 'Angiologie', 'The saphenous vein is the longest vein in the body, running along the leg.', 'La veine saphène est la veine la plus longue du corps, s''étendant le long de la jambe.', 'الوريد الصافن هو أطول وريد في الجسم، يمتد على طول الساق.', '/səˈfiːnəs veɪn/'),
(39, 'Joint', 'Articulation', 'المفصل', 'The junction between two or more bones.', 'La jonction entre deux ou plusieurs os.', 'نقطة التقاء عظمتين أو أكثر.', 'Latin: articulatio — from articulus (''small connecting part'')', 'Classified structurally into fibrous (synarthrosis), cartilaginous (amphiarthrosis), and synovial (diarthrosis) joints.', '', 'Anatomie', 'Arthrologie', 'The human body has over 360 joints.', 'Le corps humain possède plus de 360 articulations.', 'يحتوي جسم الإنسان على أكثر من 360 مفصلاً.', '/dʒɔɪnt/'),
(40, 'Synovial joint', 'Articulation synoviale', 'المفصل الزليلي', 'Freely movable joint containing synovial fluid.', 'Articulation librement mobile contenant du liquide synovial.', 'مفصل قابل للحركة بحرية يحتوي على سائل زليلي.', 'Greek: syn (''together'') + Latin ovum (''egg'', from resemblance of fluid to egg white)', 'Features a joint capsule, synovial membrane, synovial cavity, and hyaline articular cartilage.', '', 'Anatomie', 'Arthrologie', 'The knee is a synovial joint.', 'Le genou est une articulation synoviale.', 'الركبة مفصل زليلي.', '/sɪˈnoʊ.vi.əl dʒɔɪnt/'),
(41, 'Cartilaginous joint', 'Articulation cartilagineuse', 'المفصل الغضروفي', 'Joint connected by cartilage, allowing little movement.', 'Articulation reliée par du cartilage, permettant peu de mouvement.', 'مفصل متصل بالغضروف يسمح بحركة محدودة.', '', 'Divided into primary (synchondroses, hyaline cartilage) and secondary (symphyses, fibrocartilage) joints.', '', 'Anatomie', 'Arthrologie', 'The pubic symphysis is a cartilaginous joint.', 'La symphyse pubienne est une articulation cartilagineuse.', 'ارتفاق العانة مفصل غضروفي.', '/ˌkɑː.tɪˈlædʒ.ɪ.nəs dʒɔɪnt/'),
(42, 'Fibrous joint', 'Articulation fibreuse', 'المفصل الليفي', 'Immovable joint connected by fibrous tissue.', 'Articulation immobile reliée par du tissu fibreux.', 'مفصل غير متحرك متصل بنسيج ليفي.', 'Latin: fibra — ''Fiber / Fibrous tissue''', 'Includes sutures (cranial), syndesmoses (interosseous membrane), and gomphoses (dentoalveolar).', '', 'Anatomie', 'Arthrologie', 'Skull sutures are fibrous joints.', 'Les sutures du crâne sont des articulations fibreuses.', 'درزات الجمجمة مفاصل ليفية.', '/ˈfaɪ.brəs dʒɔɪnt/'),
(43, 'Synovial fluid', 'Liquide synovial', 'السائل الزليلي', 'Viscous fluid that lubricates synovial joints.', 'Liquide visqueux qui lubrifie les articulations synoviales.', 'سائل لزج يزلق المفاصل الزليلية.', '', 'Rich in hyaluronic acid and lubricin secreted by synoviocytes; provides nutrition to avascular articular cartilage.', '', 'Anatomie', 'Arthrologie', 'Synovial fluid reduces friction between joint surfaces.', 'Le liquide synovial réduit la friction entre les surfaces articulaires.', 'يقلل السائل الزليلي من الاحتكاك بين أسطح المفاصل.', '/sɪˈnoʊ.vi.əl ˈfluː.ɪd/'),
(44, 'Articular cartilage', 'Cartilage articulaire', 'الغضروف المفصلي', 'Smooth white tissue covering the ends of bones in a joint.', 'Tissu blanc lisse recouvrant les extrémités des os dans une articulation.', 'نسيج أبيض ناعم يغطي أطراف العظام في المفصل.', '', 'Hyaline cartilage that lacks blood vessels, lymphatics, and nerves; limited regenerative capacity.', '', 'Anatomie', 'Arthrologie', 'Articular cartilage can be damaged in osteoarthritis.', 'Le cartilage articulaire peut être endommagé dans l''arthrose.', 'يمكن أن يتلف الغضروف المفصلي في هشاشة العظام.', '/ɑːˈtɪk.jə.lər ˈkɑː.tɪ.lɪdʒ/'),
(45, 'Ligament', 'Ligament', 'الرباط', 'Fibrous connective tissue connecting bone to bone.', 'Tissu conjonctif fibreux reliant os à os.', 'نسيج ضام ليفي يربط العظم بالعظم.', 'Latin: ligamentum — from ligare (''to bind'')', 'Rich in type I collagen fibers arranged parallel to withstand tensile forces during joint movement.', '', 'Anatomie', 'Arthrologie', 'Ligaments stabilize joints and prevent dislocation.', 'Les ligaments stabilisent les articulations.', 'تعمل الأربطة على استقرار المفاصل ومنع الخلع.', '/ˈlɪɡ.ə.mənt/'),
(46, 'Tendon', 'Tendon', 'الوتر', 'Fibrous connective tissue connecting muscle to bone.', 'Tissu conjonctif fibreux reliant muscle à os.', 'نسيج ضام ليفي يربط العضلة بالعظم.', 'Latin: tendo — ''to stretch''', 'Contains Golgi tendon organs which detect muscle tension and trigger autogenic inhibition to prevent tearing.', '', 'Anatomie', 'Arthrologie', 'The Achilles tendon connects the calf muscles to the heel bone.', 'Le tendon d''Achille relie les muscles du mollet à l''os du talon.', 'يربط وتر أخيل عضلات الساق بعظمة الكعب.', '/ˈten.dən/'),
(47, 'Bursa', 'Bourse synoviale', 'الجراب الزليلي', 'Small fluid-filled sac that reduces friction near joints.', 'Petite poche remplie de liquide réduisant les frictions.', 'كيس صغير مليء بالسائل يقلل الاحتكاك بالقرب من المفاصل.', 'Medieval Latin: bursa — ''purse'' / ''bag''', 'Situated between bones and tendons/skin; subacromial and prepatellar bursitis are common overuse injuries.', '', 'Anatomie', 'Arthrologie', 'Bursitis is the inflammation of a bursa.', 'La bursite est l''inflammation d''une bourse synoviale.', 'التهاب الجراب هو التهاب الجراب الزليلي.', '/ˈbɜː.sə/'),
(48, 'Meniscus', 'Ménisque', 'الغضروف الهلالي', 'C-shaped fibrocartilage disc in the knee joint.', 'Disque de fibrocartilage en forme de C dans le genou.', 'قرص غضروفي ليفي على شكل C في مفصل الركبة.', 'Greek: meniskos — ''crescent'' (diminutive of mene, moon)', 'The medial meniscus is firmly attached to the tibial collateral ligament (MCL), making it more prone to injury (O''Donoghue unhappy triad).', '', 'Anatomie', 'Arthrologie', 'There are medial and lateral menisci in the knee.', 'Il y a un ménisque médial et un ménisque latéral dans le genou.', 'يوجد غضروف هلالي إنسي وجانبي في الركبة.', '/məˈnɪs.kəs/'),
(49, 'Flexion', 'Flexion', 'الثني', 'Movement that decreases the angle between two body parts.', 'Mouvement qui diminue l''angle entre deux parties du corps.', 'حركة تقلل الزاوية بين جزأين من الجسم.', 'Latin: flectere — ''to bend''', 'Occurs in the sagittal plane around a coronal (transverse) axis in most joints.', '', 'Anatomie', 'Arthrologie', 'Bending the elbow is an example of flexion.', 'Plier le coude est un exemple de flexion.', 'ثني المرفق مثال على الثني.', '/ˈflek.ʃən/'),
(50, 'Extension', 'Extension', 'البسط', 'Movement that increases the angle between two body parts.', 'Mouvement qui augmente l''angle entre deux parties du corps.', 'حركة تزيد الزاوية بين جزأين من الجسم.', 'Latin: extendere — ''to stretch out''', 'Returns a body segment from flexion back to the anatomical position; hyperextension extends beyond anatomical limits.', '', 'Anatomie', 'Arthrologie', 'Straightening the knee is an example of extension.', 'Redresser le genou est un exemple d''extension.', 'تمديد الركبة مثال على البسط.', '/ɪkˈsten.ʃən/'),
(51, 'Abduction', 'Abduction', 'الابتعاد', 'Movement away from the midline of the body.', 'Mouvement éloignant du plan médian du corps.', 'حركة بعيداً عن خط الجسم الأوسط.', 'Latin: ab (''away from'') + ducere (''to lead'')', 'Occurs in the coronal (frontal) plane; in the hand, abduction refers to spreading digits away from the middle finger.', '', 'Anatomie', 'Arthrologie', 'Raising the arm sideways is abduction.', 'Lever le bras sur le côté est une abduction.', 'رفع الذراع جانباً هو حركة الابتعاد.', '/æbˈdʌk.ʃən/'),
(52, 'Adduction', 'Adduction', 'التقريب', 'Movement toward the midline of the body.', 'Mouvement vers le plan médian du corps.', 'حركة نحو خط الجسم الأوسط.', 'Latin: ad (''toward'') + ducere (''to lead'')', 'Coronal plane movement moving limbs closer to the sagittal midline.', '', 'Anatomie', 'Arthrologie', 'Lowering the raised arm is adduction.', 'Abaisser le bras levé est une adduction.', 'خفض الذراع المرفوع حركة تقريب.', '/əˈdʌk.ʃən/'),
(53, 'Rotation', 'Rotation', 'الدوران', 'Movement of a bone around its own longitudinal axis.', 'Mouvement d''un os autour de son propre axe longitudinal.', 'حركة العظمة حول محورها الطولي.', 'Latin: rotare — ''to turn around a wheel''', 'Subdivided into medial (internal) rotation toward the anterior midline and lateral (external) rotation away from it.', '', 'Anatomie', 'Arthrologie', 'Turning the head left and right is rotation.', 'Tourner la tête à gauche et à droite est une rotation.', 'تحريك الرأس يميناً ويساراً هو دوران.', '/roʊˈteɪ.ʃən/'),
(54, 'Circumduction', 'Circumduction', 'الحركة الدائرية', 'Circular movement combining flexion, extension, abduction, and adduction.', 'Mouvement circulaire combinant flexion, extension, abduction et adduction.', 'حركة دائرية تجمع بين الثني والبسط والابتعاد والتقريب.', 'Latin: circum (''around'') + ducere (''to lead'')', 'Traces a cone in space; characteristic of ball-and-socket joints (shoulder, hip) and condyloid joints.', '', 'Anatomie', 'Arthrologie', 'Moving the arm in a full circle is circumduction.', 'Faire un cercle complet avec le bras est une circumduction.', 'تحريك الذراع في دائرة كاملة هو الحركة الدائرية.', '/ˌsɜː.kəmˈdʌk.ʃən/'),
(55, 'Ball and socket joint', 'Articulation sphéroïde', 'المفصل الكروي المحقي', 'Joint allowing movement in all directions (e.g., hip, shoulder).', 'Articulation permettant le mouvement dans toutes les directions.', 'مفصل يسمح بالحركة في جميع الاتجاهات (مثل الورك والكتف).', '', 'Multiaxial (triaxial) synovial joint with 3 degrees of freedom; shoulder is most mobile, hip is most stable.', '', 'Anatomie', 'Arthrologie', 'The hip is a ball and socket joint.', 'La hanche est une articulation sphéroïde.', 'الورك مفصل كروي محقي.', '/bɔːl ænd ˈsɒk.ɪt dʒɔɪnt/'),
(56, 'Hinge joint', 'Articulation ginglyme', 'المفصل المفصلي (الرزي)', 'Joint allowing movement in one plane only (e.g., knee, elbow).', 'Articulation permettant le mouvement dans un seul plan.', 'مفصل يسمح بالحركة في مستوى واحد فقط (مثل الركبة والمرفق).', 'Greek: ginglymos — ''hinge''', 'Uniaxial joint permitting only flexion and extension; examples include humeroulnar and interphalangeal joints.', '', 'Anatomie', 'Arthrologie', 'The elbow is a hinge joint.', 'Le coude est une articulation ginglyme.', 'المرفق مفصل رزي.', '/hɪndʒ dʒɔɪnt/'),
(57, 'Pivot joint', 'Articulation trochoïde', 'المفصل المحوري', 'Joint allowing only rotational movement (e.g., atlas-axis).', 'Articulation permettant uniquement la rotation.', 'مفصل يسمح بالحركة الدورانية فقط (مثل الأطلس والمحور).', 'Greek: trochos — ''wheel'' / ''pulley''', 'Uniaxial joint where a rounded bone rotates within a fibro-osseous ring (e.g., atlantoaxial joint, proximal radioulnar joint).', '', 'Anatomie', 'Arthrologie', 'The atlas-axis is a pivot joint allowing head rotation.', 'L''articulation atlas-axis est trochoïde permettant la rotation de la tête.', 'مفصل الأطلس-المحور محوري يسمح بدوران الرأس.', '/ˈpɪv.ət dʒɔɪnt/'),
(58, 'Suture', 'Suture', 'الدرز', 'Immovable fibrous joint between skull bones.', 'Articulation fibreuse immobile entre les os du crâne.', 'مفصل ليفي غير متحرك بين عظام الجمجمة.', 'Latin: sutura — ''seam'' / ''sewing''', 'Premature closure of cranial sutures results in craniosynostosis (e.g., scaphocephaly from sagittal suture fusion).', '', 'Anatomie', 'Arthrologie', 'The coronal suture connects the frontal and parietal bones.', 'La suture coronale relie l''os frontal aux os pariétaux.', 'يربط الدرز الإكليلي العظم الجبهي بالعظمين الجداريين.', '/ˈsuː.tʃər/'),
(59, 'Shoulder joint', 'Articulation de l''épaule', 'مفصل الكتف', 'Ball and socket joint between the humerus and glenoid cavity of scapula.', 'Articulation sphéroïde entre l''humérus et la cavité glénoïde.', 'مفصل كروي بين عظمة العضد والتجويف الحقاني للكتف.', '', 'Glenohumeral joint depth is augmented by the fibrocartilaginous glenoid labrum; vulnerable to anterior dislocation.', '', 'Anatomie', 'Arthrologie', 'The shoulder joint has the greatest range of motion.', 'L''articulation de l''épaule a la plus grande amplitude de mouvement.', 'يمتلك مفصل الكتف أوسع نطاق من الحركة.', '/ˈʃoʊl.dər dʒɔɪnt/'),
(60, 'Elbow joint', 'Articulation du coude', 'مفصل المرفق', 'Compound joint between humerus, radius, and ulna.', 'Articulation complexe entre l''humérus, le radius et l''ulna.', 'مفصل مركب بين عظمة العضد والكعبرة والزند.', '', 'Comprises three articulations within a single synovial capsule: humeroulnar, humeroradial, and proximal radioulnar.', '', 'Anatomie', 'Arthrologie', 'The elbow joint allows flexion and extension of the forearm.', 'L''articulation du coude permet la flexion et l''extension de l''avant-bras.', 'يسمح مفصل المرفق بثني وبسط الساعد.', '/ˈel.boʊ dʒɔɪnt/'),
(61, 'Hip joint', 'Articulation coxofémorale', 'مفصل الورك', 'Ball and socket joint between the femur head and acetabulum.', 'Articulation sphéroïde entre la tête du fémur et l''acétabulum.', 'مفصل كروي بين رأس عظمة الفخذ والحق.', '', 'The iliofemoral ligament (Y-ligament of Bigelow) is the strongest ligament in the human body, preventing hyperextension during standing.', '', 'Anatomie', 'Arthrologie', 'The hip joint bears the body''s weight during standing.', 'L''articulation coxofémorale supporte le poids du corps en position debout.', 'يتحمل مفصل الورك وزن الجسم أثناء الوقوف.', '/hɪp dʒɔɪnt/'),
(62, 'Knee joint', 'Articulation du genou', 'مفصل الركبة', 'The largest and most complex joint in the body.', 'La plus grande et la plus complexe articulation du corps.', 'أكبر وأكثر المفاصل تعقيداً في الجسم.', '', 'A modified hinge joint featuring the cruciate ligaments (ACL, PCL) providing anteroposterior stability and menisci for shock absorption.', '', 'Anatomie', 'Arthrologie', 'The knee joint is formed by the femur, tibia, and patella.', 'Le genou est formé par le fémur, le tibia et la rotule.', 'يتكون مفصل الركبة من عظمة الفخذ والظنبوب والرضفة.', '/niː dʒɔɪnt/'),
(63, 'Ankle joint', 'Articulation de la cheville', 'مفصل الكاحل', 'Hinge joint between the tibia, fibula, and talus bone.', 'Articulation ginglyme entre le tibia, la fibula et l''astragale.', 'مفصل رزي بين الظنبوب والشظية وعظمة الكاحل.', '', 'Talocrural joint is reinforced medially by the deltoid ligament and laterally by anterior talofibular, calcaneofibular, and posterior talofibular ligaments.', '', 'Anatomie', 'Arthrologie', 'The ankle joint allows dorsiflexion and plantarflexion.', 'La cheville permet la dorsiflexion et la flexion plantaire.', 'يسمح مفصل الكاحل بالثني الظهري والثني الأخمصي.', '/ˈæŋ.kəl dʒɔɪnt/'),
(64, 'Dislocation', 'Luxation', 'الخلع', 'Displacement of a bone from its normal position in a joint.', 'Déplacement d''un os hors de sa position normale dans une articulation.', 'إزاحة عظمة من موضعها الطبيعي في المفصل.', '', 'Requires urgent neurovascular assessment (e.g., axillary nerve in anterior shoulder dislocation; popliteal artery in knee dislocation).', '', 'Anatomie', 'Arthrologie', 'Shoulder dislocation is the most common joint dislocation.', 'La luxation de l''épaule est la plus fréquente.', 'خلع الكتف هو الأكثر شيوعاً بين خلوع المفاصل.', '/ˌdɪs.loʊˈkeɪ.ʃən/'),
(65, 'Sprain', 'Entorse', 'الالتواء (وثي)', 'Stretching or tearing of a ligament.', 'Étirement ou déchirure d''un ligament.', 'تمدد أو تمزق في الرباط.', '', 'Graded from I (micro-tear, no laxity), II (partial tear with mild laxity), to III (complete rupture with gross instability).', '', 'Anatomie', 'Arthrologie', 'Ankle sprains are very common in sports.', 'Les entorses de la cheville sont très fréquentes dans le sport.', 'التواء الكاحل شائع جداً في الرياضة.', '/spreɪn/'),
(66, 'Pronation', 'Pronation', 'الكب', 'Rotation of the forearm so the palm faces downward.', 'Rotation de l''avant-bras de sorte que la paume regarde vers le bas.', 'دوران الساعد بحيث تواجه الراحة للأسفل.', 'Latin: pronare — ''to bend forward'' / pronus (''face down'')', 'Executed by pronator teres and pronator quadratus; radius crosses anteriorly over the ulna.', '', 'Anatomie', 'Arthrologie', 'Turning the forearm so the palm faces down is pronation.', 'Tourner l''avant-bras paume vers le bas est la pronation.', 'تدوير الساعد بحيث تواجه الراحة للأسفل هو الكب.', '/proʊˈneɪ.ʃən/'),
(67, 'Supination', 'Supination', 'البسط الأمامي', 'Rotation of the forearm so the palm faces upward.', 'Rotation de l''avant-bras de sorte que la paume regarde vers le haut.', 'دوران الساعد بحيث تواجه الراحة للأعلى.', 'Latin: supinus — ''lying on the back'' / ''face upward''', 'Biceps brachii is the strongest supinator when the elbow is flexed at 90°; assisted by the supinator muscle.', '', 'Anatomie', 'Arthrologie', 'Turning the forearm so the palm faces up is supination.', 'Tourner l''avant-bras paume vers le haut est la supination.', 'تدوير الساعد بحيث تواجه الراحة للأعلى هو البسط الأمامي.', '/ˌsuː.pɪˈneɪ.ʃən/'),
(68, 'Dorsiflexion', 'Dorsiflexion', 'الثني الظهري', 'Upward bending of the foot at the ankle.', 'Flexion du pied vers le haut au niveau de la cheville.', 'ثني القدم لأعلى عند مفصل الكاحل.', '', 'Powered by the tibialis anterior, extensor digitorum longus, and extensor hallucis longus (deep peroneal nerve, L4-L5).', '', 'Anatomie', 'Arthrologie', 'Standing on your heels involves dorsiflexion.', 'Se tenir sur les talons implique une dorsiflexion.', 'الوقوف على الكعبين ينطوي على الثني الظهري.', '/ˌdɔː.sɪˈflek.ʃən/'),
(69, 'Synovial membrane', 'Membrane synoviale', 'الغشاء الزليلي', 'The inner membrane of the joint capsule secreting synovial fluid', 'Membrane interne de la capsule articulaire sécrétant le liquide synovial', 'الغشاء الداخلي للمحفظة المفصلية الذي يفرز السائل الزليلي', '', '', '', 'Anatomie', 'Arthrologie', 'The synovial membrane is the inner membrane of the joint capsule secreting synovial fluid.', 'La membrane synoviale est membrane interne de la capsule articulaire sécrétant le liquide synovial.', 'الغشاء الزليلي هو الغشاء الداخلي للمحفظة المفصلية الذي يفرز السائل الزليلي.', '/sɪˈnoʊviəl ˈmɛmbreɪn/'),
(70, 'Joint capsule', 'Capsule articulaire', 'المحفظة المفصلية', 'The fibrous envelope surrounding a synovial joint', 'Enveloppe fibreuse entourant une articulation synoviale', 'الغلاف الليفي المحيط بالمفصل الزليلي', '', '', '', 'Anatomie', 'Arthrologie', 'The joint capsule is the fibrous envelope surrounding a synovial joint.', 'La capsule articulaire est enveloppe fibreuse entourant une articulation synoviale.', 'المحفظة المفصلية هو الغلاف الليفي المحيط بالمفصل الزليلي.', '/dʒɔɪnt ˈkæpsjuːl/'),
(71, 'Plantar flexion', 'Flexion plantaire', 'العطف الأخمصي', 'Bending the foot downward at the ankle', 'Flexion du pied vers le bas au niveau de la cheville', 'ثني القدم للأسفل عند الكاحل', '', '', '', 'Anatomie', 'Arthrologie', 'Plantar flexion refers to bending the foot downward at the ankle.', 'Le flexion plantaire est flexion du pied vers le bas au niveau de la cheville.', 'العطف الأخمصي هو ثني القدم للأسفل عند الكاحل.', '/ˈplæntər ˈflɛkʃən/'),
(72, 'Inversion', 'Inversion', 'الانقلاب للداخل', 'Turning the sole of the foot medially (inward)', 'Tourner la plante du pied vers l''intérieur', 'تحويل أخمص القدم نحو الداخل', '', '', '', 'Anatomie', 'Arthrologie', 'Inversion refers to turning the sole of the foot medially (inward).', 'L''inversion est tourner la plante du pied vers l''intérieur.', 'الانقلاب للداخل هو تحويل أخمص القدم نحو الداخل.', '/ɪnˈvɜːrʒən/'),
(73, 'Eversion', 'Éversion', 'الانقلاب للخارج', 'Turning the sole of the foot laterally (outward)', 'Tourner la plante du pied vers l''extérieur', 'تحويل أخمص القدم نحو الخارج', '', '', '', 'Anatomie', 'Arthrologie', 'Eversion refers to turning the sole of the foot laterally (outward).', 'L''éversion est tourner la plante du pied vers l''extérieur.', 'الانقلاب للخارج هو تحويل أخمص القدم نحو الخارج.', '/ɪˈvɜːrʒən/'),
(74, 'Protraction', 'Protraction (Antépulsion)', 'الدفع للأمام', 'Forward movement of a body part in the horizontal plane', 'Mouvement vers l''avant d''une partie du corps dans le plan horizontal', 'حركة جزء من الجسم للأمام في المستوى الأفقي', '', '', '', 'Anatomie', 'Arthrologie', 'The Protraction pumps blood through the circulatory system.', 'Le Protraction (Antépulsion) fait le sang dans le système circulatoire.', 'يُساعد الدفع للأمام على الدم عبر الجهاز الوعائي الدوراني.', '/proʊˈtrækʃən/'),
(75, 'Retraction', 'Rétraction (Rétropulsion)', 'السحب للخلف', 'Backward movement of a body part in the horizontal plane', 'Mouvement vers l''arrière d''une partie du corps dans le plan horizontal', 'حركة جزء من الجسم للخلف في المستوى الأفقي', '', '', '', 'Anatomie', 'Arthrologie', 'The Retraction pumps blood through the circulatory system.', 'Le Rétraction (Rétropulsion) fait le sang dans le système circulatoire.', 'يُساعد السحب للخلف على الدم عبر الجهاز الوعائي الدوراني.', '/rɪˈtrækʃən/'),
(76, 'Elevation', 'Élévation', 'الرفع', 'Upward movement of a body part', 'Mouvement vers le haut d''une partie du corps', 'حركة جزء من الجسم للأعلى', '', '', '', 'Anatomie', 'Arthrologie', 'The Elevation pumps blood through the circulatory system.', 'Le Élévation fait le sang dans le système circulatoire.', 'يُساعد الرفع على الدم عبر الجهاز الوعائي الدوراني.', '/ˌɛlɪˈveɪʃən/'),
(77, 'Depression', 'Abaissement', 'الخفض', 'Downward movement of a body part', 'Mouvement vers le bas d''une partie du corps', 'حركة جزء من الجسم للأسفل', '', '', '', 'Anatomie', 'Arthrologie', 'The Depression pumps blood through the circulatory system.', 'Le Abaissement fait le sang dans le système circulatoire.', 'يُساعد الخفض على الدم عبر الجهاز الوعائي الدوراني.', '/dɪˈprɛʃən/'),
(78, 'Digestive system', 'Système digestif', 'الجهاز الهضمي', 'The group of organs that break down food and absorb nutrients.', 'L''ensemble des organes qui dégradent les aliments et absorbent les nutriments.', 'مجموعة الأعضاء التي تُحلّل الطعام وتمتص المغذيات.', '', 'About 9 m long in total; the tract plus accessory glands (salivary, liver, pancreas) constitute the system.', '', 'Anatomie', 'Appareil digestif', 'The digestive system runs from the mouth to the anus.', 'Le système digestif va de la bouche à l''anus.', 'يمتد الجهاز الهضمي من الفم إلى الشرج.', '/daɪˈdʒes.tɪv ˈsɪs.təm/'),
(79, 'Mouth', 'Bouche', 'الفم', 'The first part of the digestive tract, also called the oral cavity.', 'La première partie du tube digestif, appelée cavité buccale.', 'الجزء الأول من القناة الهضمية، ويُسمى التجويف الفموي.', 'Old English: mūth — ''mouth''', 'The oral mucosa heals quickly; examination of the mouth is part of the head and neck exam.', '', 'Anatomie', 'Appareil digestif', 'Digestion begins in the mouth.', 'La digestion commence dans la bouche.', 'يبدأ الهضم في الفم.', '/maʊθ/'),
(80, 'Tooth', 'Dent', 'السن', 'Hard calcified structure used for biting and chewing food.', 'Structure calcifiée dure servant à mordre et mâcher les aliments.', 'بنية متكلسة صلبة تُستخدم للعض والمضغ.', '', 'The dental formula for permanent teeth is 2-1-2-3 per quadrant: incisors, canine, premolars, molars.', '', 'Anatomie', 'Appareil digestif', 'Adults have 32 permanent teeth.', 'L''adulte possède 32 dents définitives.', 'للبالغ 32 سناً دائمة.', '/tuːθ/'),
(81, 'Esophagus', 'Œsophage', 'المريء', 'The muscular tube carrying food from the mouth to the stomach.', 'Le tube musculaire transportant les aliments de la bouche à l''estomac.', 'الأنبوب العضلي الذي يحمل الطعام من الفم إلى المعدة.', 'Greek: oisophagos — ''carrying food''', 'Gastroesophageal reflux damages the esophageal mucosa; the lower sphincter prevents reflux.', '', 'Anatomie', 'Appareil digestif', 'The esophagus passes through the diaphragm.', 'L''œsophage traverse le diaphragme.', 'يعبر المريء الحجاب الحاجز.', '/ɪˈsɒf.ə.ɡəs/'),
(82, 'Stomach', 'Estomac', 'المعدة', 'The dilated part of the digestive tract that stores and churns food.', 'La partie dilatée du tube digestif qui stocke et malax les aliments.', 'الجزء المتمدد من القناة الهضمية الذي يخزن الطعام ويخلطه.', 'Greek: stomachos — ''throat / gullet''', 'Gastric pH is 1.5–3.5; the rugae allow distension, and the pylorus controls gastric emptying.', '', 'Anatomie', 'Appareil digestif', 'The stomach secretes acid and pepsin.', 'L''estomac sécrète de l''acide et de la pepsine.', 'تفرز المعدة الحمض والبيبسين.', '/ˈstʌm.ək/'),
(83, 'Small intestine', 'Intestin grêle', 'الأمعاء الدقيقة', 'The narrow part of the intestine where most digestion and absorption occur.', 'La partie étroite de l''intestin où s''effectuent l''essentiel de la digestion et de l''absorption.', 'الجزء الضيق من الأمعاء حيث يحدث معظم الهضم والامتصاص.', '', 'Divided into duodenum, jejunum and ileum; its villi and microvilli amplify the absorptive surface.', '', 'Anatomie', 'Appareil digestif', 'The small intestine is about six meters long.', 'L''intestin grêle mesure environ six mètres de long.', 'يبلغ طول الأمعاء الدقيقة نحو ستة أمتار.', '/smɔːl ˈɪn.tes.tɪn/'),
(84, 'Duodenum', 'Duodénum', 'الاثني عشر', 'The first part of the small intestine, receiving chyme from the stomach.', 'La première partie de l''intestin grêle, recevant le chyme de l''estomac.', 'الجزء الأول من الأمعاء الدقيقة، يستقبل الكيموس من المعدة.', 'Latin: duodeni — ''twelve each'' (about twelve finger-breadths long)', 'The ampulla of Vater (major papilla) is where the bile and pancreatic ducts empty; blocked by a stone or tumor it causes jaundice.', '', 'Anatomie', 'Appareil digestif', 'The duodenum receives bile and pancreatic juice.', 'Le duodénum reçoit la bile et le suc pancréatique.', 'يستقبل الاثني عشر الصفراء والعصارة البنكرياسية.', '/ˌduː.əˈdiː.nəm/'),
(85, 'Jejunum', 'Jéjunum', 'الصائم', 'The middle part of the small intestine, mainly absorptive.', 'La partie moyenne de l''intestin grêle, surtout absorbante.', 'الجزء الأوسط من الأمعاء الدقيقة، مسؤول أساساً عن الامتصاص.', 'Latin: jejunus — ''empty / fasting''', 'Typically about 2.5 m long; preferred site for nutrient (iron, folate) absorption.', '', 'Anatomie', 'Appareil digestif', 'The jejunum has prominent villi.', 'Le jéjunum présente des villosités proéminentes.', 'للصائم زغابات بارزة.', '/dʒɪˈdʒuː.nəm/'),
(86, 'Ileum', 'Iléon', 'اللفائفي', 'The last part of the small intestine, joining the large intestine.', 'La dernière partie de l''intestin grêle, rejoignant le gros intestin.', 'الجزء الأخير من الأمعاء الدقيقة، يتصل بالأمعاء الغليظة.', 'Greek: eileos — ''twisted (intestine)''', 'Terminal ileum resection causes B12 deficiency and bile-salt malabsorption with diarrhea.', '', 'Anatomie', 'Appareil digestif', 'The ileum absorbs vitamin B12 and bile salts.', 'L''iléon absorbe la vitamine B12 et les sels biliaires.', 'يمتص اللفائفي فيتامين B12 وأملاح الصفراء.', '/ˈɪl.i.əm/'),
(87, 'Large intestine', 'Gros intestin', 'الأمعاء الغليظة', 'The final part of the intestine, absorbing water and forming feces.', 'La dernière partie de l''intestin, absorbant l''eau et formant les selles.', 'الجزء الأخير من الأمعاء، يمتص الماء ويكوّن البراز.', '', 'Distinguished from the small bowel by its taeniae coli, haustra and appendices epiploicae.', '', 'Anatomie', 'Appareil digestif', 'The large intestine is about 1.5 meters long.', 'Le gros intestin mesure environ 1,5 mètre.', 'يبلغ طول الأمعاء الغليظة نحو 1.5 متر.', '/lɑːrdʒ ˈɪn.tes.tɪn/'),
(88, 'Cecum', 'Cæcum', 'الأعور', 'The blind pouch at the beginning of the large intestine.', 'La poche aveugle au début du gros intestin.', 'الكيس الأعمى في بداية الأمعاء الغليظة.', 'Latin: caecus — ''blind''', 'The ileocecal valve guards its entrance; cecal volvulus is a rare cause of large-bowel obstruction.', '', 'Anatomie', 'Appareil digestif', 'The appendix attaches to the cecum.', 'L''appendice s''attache au cæcum.', 'يتصل الزائدة الدودية بالأعور.', '/ˈsiː.kəm/'),
(89, 'Colon', 'Côlon', 'القولون', 'The main part of the large intestine, framing the abdominal cavity.', 'La partie principale du gros intestin, encadrant la cavité abdominale.', 'الجزء الرئيسي من الأمعاء الغليظة، يحيط بالتجويف البطني.', 'Greek: kolon — ''large intestine''', 'Colonoscopy reaches the cecum; the hepatic and splenic flexures are the sharpest turns.', '', 'Anatomie', 'Appareil digestif', 'The colon has ascending, transverse, descending and sigmoid parts.', 'Le côlon comprend les segments ascendant, transverse, descendant et sigmoïde.', 'يضم القولون الأجزاء الصاعد والمستعرض والنازل والسيني.', '/ˈkoʊ.lən/'),
(90, 'Rectum', 'Rectum', 'المستقيم', 'The terminal straight part of the large intestine storing feces.', 'La partie terminale rectiligne du gros intestin stockant les selles.', 'الجزء المستقيم النهائي من الأمعاء الغليظة يخزن البراز.', 'Latin: rectus — ''straight''', 'The rectal veins form portocaval anastomoses; their dilation produces hemorrhoids.', '', 'Anatomie', 'Appareil digestif', 'The rectum lies just above the anal canal.', 'Le rectum se situe juste au-dessus du canal anal.', 'يقع المستقيم فوق قناة الشرج مباشرة.', '/ˈrek.təm/'),
(91, 'Anus', 'Anus', 'الشرج', 'The terminal opening of the digestive tract, closed by sphincters.', 'L''orifice terminal du tube digestif, fermé par des sphincters.', 'الفتحة النهائية للقناة الهضمية، تُغلقها العاصرات.', 'Latin: anus — ''ring / anus''', 'The dentate line marks the transition from rectal (columnar) to anal (squamous) mucosa and the embryological boundary.', '', 'Anatomie', 'Appareil digestif', 'The anus is surrounded by internal and external sphincters.', 'L''anus est entouré des sphincters interne et externe.', 'يحيط بالشرج العاصرة الداخلية والخارجية.', '/ˈeɪ.nəs/'),
(92, 'Salivary gland', 'Glande salivaire', 'الغدة اللعابية', 'A gland producing saliva, with three major pairs.', 'Une glande produisant la salive, au nombre de trois paires principales.', 'غدة تنتج اللعاب، يوجد ثلاثة أزواج رئيسية منها.', '', 'The parotid, submandibular and sublingual glands; the facial nerve runs through the parotid.', '', 'Anatomie', 'Appareil digestif', 'The parotid is the largest salivary gland.', 'La parotide est la plus grande des glandes salivaires.', 'الغدة النكفية أكبر الغدد اللعابية.', '/ˈsæl.ə.ver.i ɡlænd/'),
(93, 'Liver', 'Foie', 'الكبد', 'The largest abdominal organ, performing metabolism, detoxification and bile production.', 'Le plus grand organe abdominal, assurant métabolisme, détoxification et production de bile.', 'أكبر أعضاء البطن، مسؤول عن الاستقلاب وإزالة السمية وإنتاج الصفراء.', 'Old English: lifer — ''liver''', 'About 1.5 kg and divided into eight functional Couinaud segments, resectable independently.', '', 'Anatomie', 'Appareil digestif', 'The liver is located in the right upper abdomen.', 'Le foie est situé dans l''hypochondre droit.', 'يقع الكبد في أعلى البطن أيمن الجهة.', '/ˈlɪv.ər/'),
(94, 'Gallbladder', 'Vésicule biliaire', 'المرارة', 'The sac beneath the liver that stores and concentrates bile.', 'La poche sous le foie qui stocke et concentre la bile.', 'الكيس أسفل الكبد يخزن الصفراء ويركزها.', '', 'Gallstones (cholelithiasis) can obstruct the cystic duct, causing biliary colic and cholecystitis.', '', 'Anatomie', 'Appareil digestif', 'The gallbladder contracts after a fatty meal.', 'La vésicule se contracte après un repas gras.', 'تنقبض المرارة بعد وجبة دسمة.', '/ˈɡɔːlˌblæd.ər/'),
(95, 'Bile', 'Bile', 'الصفراء', 'The fluid produced by the liver that emulsifies fats.', 'Le liquide produit par le foie qui émulsionne les graisses.', 'السائل الذي ينتجه الكبد ويستحلب الدهون.', 'Latin: bilis — ''bile / gall''', 'Main pigments are bilirubin and biliverdin; obstruction of bile flow causes jaundice and pale stools.', '', 'Anatomie', 'Appareil digestif', 'Bile is stored in the gallbladder between meals.', 'La bile est stockée dans la vésicule entre les repas.', 'تُخزن الصفراء في المرارة بين الوجبات.', '/baɪl/'),
(96, 'Pancreas', 'Pancréas', 'البنكرياس', 'The organ behind the stomach with digestive and hormonal functions.', 'L''organe derrière l''estomac aux fonctions digestives et hormonales.', 'العضو خلف المعدة ذو الوظائف الهضمية والهرمونية.', 'Greek: pan (''all'') + kreas (''flesh'')', 'Acute pancreatitis is typically caused by gallstones or alcohol; raised lipase is more specific than amylase.', '', 'Anatomie', 'Appareil digestif', 'The pancreas secretes insulin and digestive enzymes.', 'Le pancréas sécrète l''insuline et des enzymes digestives.', 'يفرز البنكرياس الأنسولين وإنزيمات هاضمة.', '/ˈpæn.kri.əs/'),
(97, 'Digestion', 'Digestion', 'الهضم', 'The process of breaking food into absorbable molecules.', 'Le processus de dégradation des aliments en molécules absorbables.', 'عملية تكسير الطعام إلى جزيئات قابلة للامتصاص.', 'Latin: digerere — ''to distribute / dissolve''', 'Mechanical and chemical digestion combine; most chemical digestion is completed in the small intestine.', '', 'Anatomie', 'Appareil digestif', 'Digestion begins in the mouth with chewing.', 'La digestion commence dans la bouche par la mastication.', 'يبدأ الهضم في الفم بالمضغ.', '/daɪˈdʒes.tʃən/'),
(98, 'Peristalsis', 'Péristaltisme', 'التمعج', 'Wave-like muscle contractions that move food through the digestive tract.', 'Contractions musculaires ondulaires propulsant les aliments dans le tube digestif.', 'تقلصات عضلية موجية تدفع الطعام عبر القناة الهضمية.', 'Greek: peri (''around'') + stalsis (''contraction'')', 'Coordinated by enteric plexuses; absent bowel sounds on auscultation suggest ileus or peritonitis.', '', 'Anatomie', 'Appareil digestif', 'Peristalsis pushes food toward the stomach.', 'Le péristaltisme pousse les aliments vers l''estomac.', 'يدفع التمعج الطعام نحو المعدة.', '/ˌper.ɪˈstæl.sɪs/'),
(99, 'Chyme', 'Chyme', 'الكيموس', 'The semi-fluid mass of partially digested food leaving the stomach.', 'La masse semi-liquide d''aliments partiellement digérés quittant l''estomac.', 'الكتلة شبه السائلة من الطعام المهضوم جزئياً التي تغادر المعدة.', 'Greek: chymos — ''juice''', 'Its acidity triggers secretin and cholecystokinin release from the duodenal mucosa.', '', 'Anatomie', 'Appareil digestif', 'Chyme enters the duodenum in small spurts.', 'Le chyme pénètre dans le duodénum par petites fractions.', 'يدخل الكيموس الاثني عشر على دفعات صغيرة.', '/kaɪm/'),
(100, 'Villi', 'Villosités', 'الزغابات', 'Tiny finger-like projections that increase the intestinal absorptive surface.', 'Minuscules saillies en forme de doigts augmentant la surface absorbante.', 'بروزات صغيرة تشبه الأصابع تزيد سطح الامتصاص المعوي.', 'Latin: villus — ''tuft of hair''', 'Flattened in celiac disease, causing malabsorption; each villus contains a central lacteal.', '', 'Anatomie', 'Appareil digestif', 'Villi line the small intestine.', 'Les villosités tapissent l''intestin grêle.', 'تبطن الزغابات الأمعاء الدقيقة.', '/ˈvɪl.aɪ/'),
(101, 'Enzyme', 'Enzyme', 'الإنزيم', 'A protein that speeds up chemical reactions such as digestion.', 'Une protéine accélérant les réactions chimiques telles que la digestion.', 'بروتين يسرّع التفاعلات الكيميائية كالهضم.', 'Greek: en (''in'') + zyme (''leaven / ferment'')', 'Digestive enzymes are hydrolases: amylases, proteases, lipases and nucleases act on specific bonds.', '', 'Anatomie', 'Appareil digestif', 'Amylase is a digestive enzyme.', 'L''amylase est une enzyme digestive.', 'الأميلاز إنزيم هاضم.', '/ˈen.zaɪm/'),
(102, 'Saliva', 'Salive', 'اللعاب', 'The fluid secreted by salivary glands that moistens food and starts digestion.', 'Le liquide sécrété par les glandes salivaires humectant les aliments et débutant la digestion.', 'السائل الذي تفرزه الغدد اللعابية يرطب الطعام ويبدأ الهضم.', 'Latin: saliva — ''spittle''', 'About 1 to 1.5 L per day; reduced flow (xerostomia) predisposes to dental caries and dysphagia.', '', 'Anatomie', 'Appareil digestif', 'Saliva contains salivary amylase.', 'La salive contient de l''amylase salivaire.', 'يحتوي اللعاب على الأميلاز اللعابية.', '/səˈlaɪ.və/'),
(103, 'Appendix', 'Appendice (vermiforme)', 'الزائدة الدودية', 'The narrow worm-shaped tube attached to the cecum.', 'Le tube étroit en forme de ver attaché au cæcum.', 'الأنبوب الضيق الدودي الشكل المتصل بالأعور.', '', 'Appendicitis pain typically starts periumbilically then localizes to the right iliac fossa (McBurney''s point).', '', 'Anatomie', 'Appareil digestif', 'The appendix has no essential digestive function.', 'L''appendice n''a pas de fonction digestive essentielle.', 'لا تملك الزائدة الدودية وظيفة هضمية أساسية.', '/əˈpen.dɪks/'),
(104, 'Sphincter', 'Sphincter', 'العاصرة', 'A ring of muscle controlling the opening of a tube or orifice.', 'Un anneau musculaire contrôlant l''ouverture d''un conduit ou d''un orifice.', 'حلقة عضلية تتحكم في فتح قناة أو فوهة.', 'Greek: sphinkter — ''that which binds tight''', 'Key examples: lower esophageal, pyloric, ileocecal and anal sphincters.', '', 'Anatomie', 'Appareil digestif', 'Sphincters regulate the passage of food.', 'Les sphincters règlent le passage des aliments.', 'تنظم العاصرات مرور الطعام.', '/ˈsfɪŋk.tər/'),
(105, 'Abdomen', 'Abdomen', 'البطن', 'The region of the body between the thorax and the pelvis.', 'La région du corps entre le thorax et le bassin.', 'منطقة الجسم بين الصدر والحوض.', 'Latin: abdomen — ''belly''', 'Divided by clinicians into four quadrants or nine regions to localize organ pathology.', '', 'Anatomie', 'Appareil digestif', 'The abdomen contains most of the digestive organs.', 'L''abdomen contient la plupart des organes digestifs.', 'يحتوي البطن معظم الأعضاء الهضمية.', '/ˈæb.də.mən/'),
(106, 'Anatomy', 'Anatomie', 'علم التشريح', 'The science of body structures and the relationships among them', 'Science des structures du corps et de leurs relations', 'علم دراسة بنية الجسم والعلاقات بين أجزائه', '', '', '', 'Anatomie', 'Termes généraux', 'Anatomy is the science of body structures and the relationships among them.', 'L''anatomie est science des structures du corps et de leurs relations.', 'علم التشريح هو علم دراسة بنية الجسم والعلاقات بين أجزائه.', '/əˈnætəmi/'),
(107, 'Sagittal plane', 'Plan sagittal', 'المستوى السهمي', 'A vertical plane that divides the body into right and left parts', 'Plan vertical divisant le corps en parties droite et gauche', 'مستوى عمودي يقسم الجسم إلى جزأين أيمن وأيسر', '', '', '', 'Anatomie', 'Termes généraux', 'The sagittal plane is the vertical plane that divides the body into right and left parts.', 'La plan sagittal est plan vertical divisant le corps en parties droite et gauche.', 'المستوى السهمي هو مستوى عمودي يقسم الجسم إلى جزأين أيمن وأيسر.', '/ˈsædʒɪtəl pleɪn/'),
(108, 'Coronal plane', 'Plan coronal (frontal)', 'المستوى الإكليلي', 'A vertical plane that divides the body into anterior and posterior parts', 'Plan vertical divisant le corps en parties antérieure et postérieure', 'مستوى عمودي يقسم الجسم إلى جزء أمامي وجزء خلفي', '', '', '', 'Anatomie', 'Termes généraux', 'The coronal plane is the vertical plane that divides the body into anterior and posterior parts.', 'La plan coronal (frontal) est plan vertical divisant le corps en parties antérieure et postérieure.', 'المستوى الإكليلي هو مستوى عمودي يقسم الجسم إلى جزء أمامي وجزء خلفي.', '/ˈkɒrənəl pleɪn/'),
(109, 'Transverse plane', 'Plan transversal (axial)', 'المستوى المستعرض', 'A horizontal plane dividing the body into superior and inferior parts', 'Plan horizontal divisant le corps en parties supérieure et inférieure', 'مستوى أفقي يقسم الجسم إلى جزء علوي وجزء سفلي', '', '', '', 'Anatomie', 'Termes généraux', 'The transverse plane is the horizontal plane dividing the body into superior and inferior parts.', 'La plan transversal (axial) est plan horizontal divisant le corps en parties supérieure et inférieure.', 'المستوى المستعرض هو مستوى أفقي يقسم الجسم إلى جزء علوي وجزء سفلي.', '/trænsˈvɜːrs pleɪn/'),
(110, 'Median plane', 'Plan médian', 'المستوى الناصف', 'A sagittal plane that passes through the midline of the body', 'Plan sagittal passant par la ligne médiane du corps', 'مستوى سهمي يمر عبر الخط الأوسط للجسم', '', '', '', 'Anatomie', 'Termes généraux', 'The median plane is the sagittal plane that passes through the midline of the body.', 'La plan médian est plan sagittal passant par la ligne médiane du corps.', 'المستوى الناصف هو مستوى سهمي يمر عبر الخط الأوسط للجسم.', '/ˈmiːdiən pleɪn/'),
(111, 'Anterior (Ventral)', 'Antérieur (Ventral)', 'أمامي (بطني)', 'Situated at or toward the front of the body', 'Situé à l''avant du corps', 'يقع في الجهة الأمامية من الجسم', '', '', '', 'Anatomie', 'Termes généraux', 'Anterior (Ventral) refers to situated at or toward the front of the body.', 'L''antérieur (Ventral) est situé à l''avant du corps.', 'أمامي (بطني) هو يقع في الجهة الأمامية من الجسم.', '/ænˈtɪəriər/'),
(112, 'Posterior (Dorsal)', 'Postérieur (Dorsal)', 'خلفي (ظهري)', 'Situated at or toward the back of the body', 'Situé à l''arrière du corps', 'يقع في الجهة الخلفية من الجسم', '', '', '', 'Anatomie', 'Termes généraux', 'Posterior (Dorsal) refers to situated at or toward the back of the body.', 'La postérieur (Dorsal) est situé à l''arrière du corps.', 'خلفي (ظهري) هو يقع في الجهة الخلفية من الجسم.', '/pɒˈstɪəriər/'),
(113, 'Superior (Cranial)', 'Supérieur (Crânial)', 'علوي (قحفي)', 'Situated above or toward the head', 'Situé au-dessus ou vers la tête', 'يقع أعلى أو باتجاه الرأس', '', '', '', 'Anatomie', 'Termes généraux', 'Superior (Cranial) refers to situated above or toward the head.', 'La supérieur (Crânial) est situé au-dessus ou vers la tête.', 'علوي (قحفي) هو يقع أعلى أو باتجاه الرأس.', '/suːˈpɪəriər/'),
(114, 'Inferior (Caudal)', 'Inférieur (Caudal)', 'سفلي (ذنبي)', 'Situated below or toward the feet', 'Situé en dessous ou vers les pieds', 'يقع أسفل أو باتجاه القدمين', '', '', '', 'Anatomie', 'Termes généraux', 'Inferior (Caudal) refers to situated below or toward the feet.', 'L''inférieur (Caudal) est situé en dessous ou vers les pieds.', 'سفلي (ذنبي) هو يقع أسفل أو باتجاه القدمين.', '/ɪnˈfɪəriər/'),
(115, 'Medial', 'Médial', 'إنسي', 'Situated closer to the midline of the body', 'Situé plus proche de la ligne médiane', 'يقع أقرب إلى الخط الأوسط للجسم', '', '', '', 'Anatomie', 'Termes généraux', 'Medial refers to situated closer to the midline of the body.', 'Le médial est situé plus proche de la ligne médiane.', 'إنسي هو يقع أقرب إلى الخط الأوسط للجسم.', '/ˈmiːdiəl/'),
(116, 'Lateral', 'Latéral', 'وحشي', 'Situated farther from the midline of the body', 'Situé plus loin de la ligne médiane', 'يقع أبعد عن الخط الأوسط للجسم', '', '', '', 'Anatomie', 'Termes généraux', 'Lateral refers to situated farther from the midline of the body.', 'Le latéral est situé plus loin de la ligne médiane.', 'وحشي هو يقع أبعد عن الخط الأوسط للجسم.', '/ˈlætərəl/'),
(117, 'Proximal', 'Proximal', 'داني (قريب)', 'Situated closer to the point of attachment or origin', 'Situé plus proche du point d''attache', 'يقع أقرب إلى نقطة الارتباط أو الأصل', '', '', '', 'Anatomie', 'Termes généraux', 'Proximal refers to situated closer to the point of attachment or origin.', 'Le proximal est situé plus proche du point d''attache.', 'داني (قريب) هو يقع أقرب إلى نقطة الارتباط أو الأصل.', '/ˈprɒksɪməl/'),
(118, 'Distal', 'Distal', 'قاصي (بعيد)', 'Situated farther from the point of attachment or origin', 'Situé plus loin du point d''attache', 'يقع أبعد عن نقطة الارتباط أو الأصل', '', '', '', 'Anatomie', 'Termes généraux', 'Distal refers to situated farther from the point of attachment or origin.', 'Le distal est situé plus loin du point d''attache.', 'قاصي (بعيد) هو يقع أبعد عن نقطة الارتباط أو الأصل.', '/ˈdɪstəl/'),
(119, 'Superficial', 'Superficiel', 'سطحي', 'Situated closer to the surface of the body', 'Situé plus près de la surface du corps', 'يقع أقرب إلى سطح الجسم', '', '', '', 'Anatomie', 'Termes généraux', 'Superficial refers to situated closer to the surface of the body.', 'La superficiel est situé plus près de la surface du corps.', 'سطحي هو يقع أقرب إلى سطح الجسم.', '/ˌsuːpərˈfɪʃəl/'),
(120, 'Deep', 'Profond', 'عميق', 'Situated farther from the surface of the body', 'Situé plus loin de la surface du corps', 'يقع أبعد عن سطح الجسم', '', '', '', 'Anatomie', 'Termes généraux', 'Deep refers to situated farther from the surface of the body.', 'La profond est situé plus loin de la surface du corps.', 'عميق هو يقع أبعد عن سطح الجسم.', '/diːp/'),
(121, 'Prone', 'Décubitus ventral (Pronation)', 'الانبطاح', 'Lying face down', 'Couché face vers le bas', 'الاستلقاء على الوجه', '', '', '', 'Anatomie', 'Termes généraux', 'Prone refers to lying face down.', 'La décubitus ventral (Pronation) est couché face vers le bas.', 'الانبطاح هو الاستلقاء على الوجه.', '/proʊn/'),
(122, 'Supine', 'Décubitus dorsal (Supination)', 'الاستلقاء', 'Lying face up', 'Couché face vers le haut', 'الاستلقاء على الظهر', '', '', '', 'Anatomie', 'Termes généraux', 'The Supine pumps blood through the circulatory system.', 'Le Décubitus dorsal (Supination) fait le sang dans le système circulatoire.', 'يُساعد الاستلقاء على الدم عبر الجهاز الوعائي الدوراني.', '/suːˈpaɪn/'),
(123, 'Ipsilateral', 'Ipsilatéral (Homolatéral)', 'من نفس الجهة', 'On the same side of the body', 'Du même côté du corps', 'على نفس الجانب من الجسم', '', '', '', 'Anatomie', 'Termes généraux', 'The Ipsilateral pumps blood through the circulatory system.', 'Le Ipsilatéral (Homolatéral) fait le sang dans le système circulatoire.', 'يُساعد من نفس الجهة على الدم عبر الجهاز الوعائي الدوراني.', '/ˌɪpsɪˈlætərəl/'),
(124, 'Contralateral', 'Controlatéral', 'من الجهة المقابلة', 'On the opposite side of the body', 'Du côté opposé du corps', 'على الجانب المقابل من الجسم', '', '', '', 'Anatomie', 'Termes généraux', 'The Contralateral pumps blood through the circulatory system.', 'Le Controlatéral fait le sang dans le système circulatoire.', 'يُساعد من الجهة المقابلة على الدم عبر الجهاز الوعائي الدوراني.', '/ˌkɒntrəˈlætərəl/'),
(125, 'Bilateral', 'Bilatéral', 'ثنائي الجانب', 'On both sides of the body', 'Des deux côtés du corps', 'على كلا جانبي الجسم', '', '', '', 'Anatomie', 'Termes généraux', 'The Bilateral pumps blood through the circulatory system.', 'Le Bilatéral fait le sang dans le système circulatoire.', 'يُساعد ثنائي الجانب على الدم عبر الجهاز الوعائي الدوراني.', '/baɪˈlætərəl/'),
(126, 'Cephalic', 'Céphalique', 'رأسي', 'Pertaining to the head', 'Relatif à la tête', 'متعلق بالرأس', 'Greek: κεφαλή (kephalḗ) — ''Head''', '', '', 'Anatomie', 'Termes généraux', 'Cephalic refers to pertaining to the head.', 'La céphalique est relatif à la tête.', 'يُساعد رأسي على الدم عبر الجهاز الوعائي الدوراني.', '/sɪˈfælɪk/'),
(127, 'Cervical', 'Cervical', 'عنقي (رقبي)', 'Pertaining to the neck', 'Relatif au cou', 'متعلق بالعنق', '', '', '', 'Anatomie', 'Termes généraux', 'Cervical refers to pertaining to the neck.', 'Le Cervical fait le sang dans le système circulatoire.', 'يُساعد عنقي (رقبي) على الدم عبر الجهاز الوعائي الدوراني.', '/ˈsɜːrvɪkəl/'),
(128, 'Thoracic', 'Thoracique', 'صدري', 'Pertaining to the chest', 'Relatif au thorax', 'متعلق بالصدر', 'Greek: θώραξ (thōrax) — ''Chest / Thorax''', '', '', 'Anatomie', 'Termes généraux', 'Thoracic refers to pertaining to the chest.', 'La thoracique est relatif au thorax.', 'يُساعد صدري على الدم عبر الجهاز الوعائي الدوراني.', '/θɔːˈræsɪk/'),
(129, 'Abdominal', 'Abdominal', 'بطني', 'Pertaining to the abdomen', 'Relatif à l''abdomen', 'متعلق بالبطن', 'Latin: abdomen — ''Abdomen / Belly''', '', '', 'Anatomie', 'Termes généraux', 'Abdominal refers to pertaining to the abdomen.', 'L''abdominal est relatif à l''abdomen.', 'يُساعد بطني على الدم عبر الجهاز الوعائي الدوراني.', '/æbˈdɒmɪnəl/'),
(130, 'Pelvic', 'Pelvien', 'حوضي', 'Pertaining to the pelvis', 'Relatif au bassin', 'متعلق بالحوض', '', '', '', 'Anatomie', 'Termes généraux', 'Pelvic refers to pertaining to the pelvis.', 'La pelvien est relatif au bassin.', 'يُساعد حوضي على الدم عبر الجهاز الوعائي الدوراني.', '/ˈpɛlvɪk/'),
(131, 'Lumbar', 'Lombaire', 'قَطَني', 'Pertaining to the lower back', 'Relatif au bas du dos', 'متعلق بأسفل الظهر', '', '', '', 'Anatomie', 'Termes généraux', 'Lumbar refers to pertaining to the lower back.', 'La lombaire est relatif au bas du dos.', 'قَطَني هو متعلق بأسفل الظهر.', '/ˈlʌmbɑːr/'),
(132, 'Inguinal', 'Inguinal', 'أربي (مغبني)', 'Pertaining to the groin', 'Relatif à l''aine', 'متعلق بمنطقة المغبن', '', '', '', 'Anatomie', 'Termes généraux', 'Inguinal refers to pertaining to the groin.', 'L''inguinal est relatif à l''aine.', 'أربي (مغبني) هو متعلق بمنطقة المغبن.', '/ˈɪŋɡwɪnəl/'),
(133, 'Muscle', 'Muscle', 'العضلة', 'Contractile tissue responsible for movement.', 'Tissu contractile responsable du mouvement.', 'نسيج انقباضي مسؤول عن الحركة.', 'Latin: musculus — ''little mouse'' (resembling a mouse moving under the skin)', 'Classified into three types: skeletal (striated, voluntary), cardiac (striated, involuntary), and smooth (non-striated, involuntary).', '', 'Anatomie', 'Myologie', 'The human body has over 600 skeletal muscles.', 'Le corps humain possède plus de 600 muscles squelettiques.', 'يحتوي جسم الإنسان على أكثر من 600 عضلة هيكلية.', '/ˈmʌs.əl/'),
(134, 'Skeletal muscle', 'Muscle squelettique', 'العضلة الهيكلية', 'Voluntary striated muscle attached to bones.', 'Muscle strié volontaire attaché aux os.', 'عضلة مخططة إرادية متصلة بالعظام.', '', 'Innervated by somatic motor neurons; acetylcholine (ACh) release at neuromuscular junctions initiates depolarization.', '', 'Anatomie', 'Myologie', 'Skeletal muscles are under voluntary control.', 'Les muscles squelettiques sont sous contrôle volontaire.', 'العضلات الهيكلية تحت السيطرة الإرادية.', '/ˈskel.ɪ.təl ˈmʌs.əl/'),
(135, 'Smooth muscle', 'Muscle lisse', 'العضلة الملساء', 'Involuntary non-striated muscle found in organs and blood vessels.', 'Muscle lisse involontaire des organes et vaisseaux sanguins.', 'عضلة غير إرادية غير مخططة توجد في الأعضاء والأوعية الدموية.', '', 'Regulated by the autonomic nervous system and hormones; utilizes calmodulin instead of troponin for calcium-dependent contraction.', '', 'Anatomie', 'Myologie', 'Smooth muscle controls digestive movements.', 'Le muscle lisse contrôle les mouvements digestifs.', 'تتحكم العضلة الملساء في حركات الجهاز الهضمي.', '/smuːð ˈmʌs.əl/'),
(136, 'Cardiac muscle', 'Muscle cardiaque', 'عضلة القلب', 'Involuntary striated muscle found only in the heart.', 'Muscle strié involontaire présent uniquement dans le cœur.', 'عضلة مخططة غير إرادية توجد فقط في القلب.', 'Greek: καρδία (kardía) — ''Heart''', 'Cardiomyocytes are interconnected by intercalated discs containing gap junctions for rapid electrical syncytial transmission.', '', 'Anatomie', 'Myologie', 'Cardiac muscle contracts continuously throughout life.', 'Le muscle cardiaque se contracte en permanence tout au long de la vie.', 'تنقبض عضلة القلب باستمرار طوال الحياة.', '/ˈkɑː.di.æk ˈmʌs.əl/'),
(137, 'Myosin', 'Myosine', 'الميوسين', 'Thick contractile protein filament in muscle cells.', 'Filament protéique contractile épais dans les cellules musculaires.', 'خيط بروتيني سميك انقباضي في الخلايا العضلية.', 'Greek: mys (''muscle'') + protein suffix -in', 'Myosin head possesses ATPase activity; hydrolyzes ATP to execute the mechanical ''power stroke'' along actin.', '', 'Anatomie', 'Myologie', 'Myosin and actin interact to produce muscle contraction.', 'La myosine et l''actine interagissent pour produire la contraction musculaire.', 'يتفاعل الميوسين والأكتين لإنتاج انقباض العضلة.', '/ˈmaɪ.ə.sɪn/'),
(138, 'Actin', 'Actine', 'الأكتين', 'Thin contractile protein filament in muscle cells.', 'Filament protéique contractile fin dans les cellules musculaires.', 'خيط بروتيني رفيع انقباضي في الخلايا العضلية.', '', 'Polymerizes from G-actin into double-helical F-actin; associated with tropomyosin and troponin regulatory complex.', '', 'Anatomie', 'Myologie', 'Actin filaments are found in all eukaryotic cells.', 'Les filaments d''actine se trouvent dans toutes les cellules eucaryotes.', 'توجد خيوط الأكتين في جميع الخلايا حقيقية النواة.', '/ˈæk.tɪn/'),
(139, 'Sarcomere', 'Sarcomère', 'القسيم العضلي', 'The fundamental structural and contractile repeating unit of striated muscle fibrils, delineated between two consecutive Z discs.', 'Unité contractile élémentaire répétitive de la myofibrille musculaire striée, délimitée entre deux stries Z consécutives.', 'الوحدة البنائية والانقباضية الوظيفية الأساسية المتكررة في اللييف العضلي المخطط، المحصورة بين خطين متتاليين من أقراص Z.', 'Greek: sarx (''flesh'') + meros (''part'')', 'Spans between two adjacent Z-discs; during contraction, the I-band and H-zone shorten while the A-band remains constant.', '', 'Anatomie', 'Myologie', 'The sarcomere is bounded by two Z-lines.', 'Le sarcomère est délimité par deux lignes Z.', 'يحدّ القسيمَ العضليَ خطان من النوع Z.', '/ˈsɑː.kə.mɪər/'),
(140, 'Myofibril', 'Myofibrille', 'اللييف العضلي', 'Long cylindrical organelle that makes up muscle fibers.', 'Organite cylindrique long composant les fibres musculaires.', 'عضية أسطوانية طويلة تشكل الألياف العضلية.', '', 'Arranged in parallel chains within the sarcoplasm, surrounded by sarcoplasmic reticulum that stores calcium ions.', '', 'Anatomie', 'Myologie', 'Each myofibril is made up of sarcomeres.', 'Chaque myofibrille est composée de sarcomères.', 'يتكون كل لييف عضلي من قسيمات عضلية.', '/ˌmaɪ.oʊˈfaɪ.brɪl/'),
(141, 'Muscle contraction', 'Contraction musculaire', 'الانقباض العضلي', 'Shortening of muscle fibers due to actin-myosin interaction.', 'Raccourcissement des fibres musculaires dû à l''interaction actine-myosine.', 'تقصير ألياف العضلة بسبب تفاعل الأكتين والميوسين.', '', 'Described by the Sliding Filament Model; rigor mortis occurs after death when ATP depletion prevents myosin head detachment.', '', 'Anatomie', 'Myologie', 'Muscle contraction requires ATP.', 'La contraction musculaire nécessite de l''ATP.', 'يتطلب الانقباض العضلي وجود ATP.', '/ˈmʌs.əl kənˈtræk.ʃən/'),
(142, 'Fascia', 'Fascia', 'اللفافة', 'Sheet of connective tissue that surrounds and separates muscles.', 'Feuillet de tissu conjonctif entourant et séparant les muscles.', 'صفيحة من النسيج الضام تحيط بالعضلات وتفصلها.', 'Latin: fascia — ''band'' / ''bundle''', 'Increased pressure within a non-distensible fascial compartment leads to compartment syndrome, a surgical emergency requiring fasciotomy.', '', 'Anatomie', 'Myologie', 'Fascia provides structural support to muscles.', 'Le fascia fournit un soutien structurel aux muscles.', 'توفر اللفافة دعماً هيكلياً للعضلات.', '/ˈfæʃ.i.ə/'),
(143, 'Orbicularis oculi', 'Orbiculaire de l''œil', 'عضلة الدائرية للعين', 'Muscle that closes the eyelid.', 'Muscle qui ferme la paupière.', 'العضلة التي تغلق الجفن.', '', 'Innervated by the facial nerve (CN VII); paralysis (Bell''s palsy) leads to lagophthalmos and risk of corneal ulceration.', '', 'Anatomie', 'Myologie', 'The orbicularis oculi closes the eye when blinking.', 'L''orbiculaire de l''œil ferme l''œil lors du clignement.', 'تغلق عضلة الدائرية للعين العين عند الرمش.', '/ɔːˌbɪk.jəˈlɑː.rɪs ˈɒk.jʊ.laɪ/'),
(144, 'Masseter', 'Masséter', 'عضلة الماضغة', 'Powerful jaw muscle used for chewing (mastication).', 'Puissant muscle de la mâchoire utilisé pour la mastication.', 'عضلة فك قوية تستخدم للمضغ.', 'Greek: maseter — ''chewer''', 'Elevates and protrudes the mandible; innervated by the mandibular division of trigeminal nerve (CN V3).', '', 'Anatomie', 'Myologie', 'The masseter is one of the strongest muscles per unit area.', 'Le masséter est l''un des muscles les plus puissants par unité de surface.', 'عضلة الماضغة من أقوى العضلات لكل وحدة مساحة.', '/mæˈsiː.tər/'),
(145, 'Sternocleidomastoid', 'Sterno-cléido-mastoïdien', 'العضلة القصية الترقوية الخشائية', 'Major neck muscle that rotates and flexes the head.', 'Muscle principal du cou qui tourne et fléchit la tête.', 'عضلة الرقبة الرئيسية التي تدور الرأس وتثنيه.', '', 'Innervated by the spinal accessory nerve (CN XI); unilateral contracture produces torticollis (wryneck).', '', 'Anatomie', 'Myologie', 'The sternocleidomastoid turns the head to the opposite side.', 'Le SCM tourne la tête du côté opposé.', 'تدير العضلة القصية الترقوية الخشائية الرأس إلى الجانب المعاكس.', '/ˌstɜː.noʊˌklaɪ.doʊˈmæs.tɔɪd/'),
(146, 'Trapezius', 'Trapèze', 'العضلة الشبه منحرفة', 'Large triangular muscle of the back and neck.', 'Grand muscle triangulaire du dos et du cou.', 'عضلة مثلثة كبيرة في الظهر والرقبة.', 'Greek: trapezion — ''irregular four-sided figure''', 'Divided into descending (elevates), transverse (retracts), and ascending (depresses) fibers; innervated by CN XI.', '', 'Anatomie', 'Myologie', 'The trapezius elevates and retracts the scapula.', 'Le trapèze élève et rétracte l''omoplate.', 'ترفع العضلة الشبه منحرفة لوح الكتف وتسحبه للخلف.', '/trəˈpiː.zi.əs/'),
(147, 'Pectoralis major', 'Grand pectoral', 'العضلة الصدرية الكبرى', 'Large chest muscle that adducts and rotates the arm.', 'Grand muscle pectoral qui adduit et tourne le bras.', 'عضلة الصدر الكبيرة التي تقرّب وتدير الذراع.', 'Latin: pectus — ''breast'' / ''chest''', 'Has clavicular and sternocostal heads; innervated by medial and lateral pectoral nerves.', '', 'Anatomie', 'Myologie', 'The pectoralis major is used in push-ups.', 'Le grand pectoral est utilisé lors des pompes.', 'تستخدم العضلة الصدرية الكبرى عند أداء تمارين الضغط.', '/ˌpek.tərˈeɪ.lɪs ˈmeɪ.dʒər/'),
(148, 'Diaphragm', 'Diaphragme', 'الحجاب الحاجز', 'The main muscle of respiration separating thorax from abdomen.', 'Le principal muscle respiratoire séparant le thorax de l''abdomen.', 'العضلة التنفسية الرئيسية التي تفصل الصدر عن البطن.', 'Greek: diaphragma — ''partition'' / ''barrier''', 'Innervated entirely by the paired phrenic nerves (''C3, C4, C5 keep the diaphragm alive'').', 'Openings: T8 (IVC), T10 (Esophagus), T12 (Aorta) — ''I 8 10 Eggs At 12''.', 'Anatomie', 'Myologie', 'The diaphragm contracts during inhalation.', 'Le diaphragme se contracte lors de l''inspiration.', 'ينقبض الحجاب الحاجز أثناء الشهيق.', '/ˈdaɪ.ə.fræm/'),
(149, 'Rectus abdominis', 'Droit de l''abdomen', 'العضلة المستقيمة للبطن', 'Vertical muscle forming the anterior abdominal wall.', 'Muscle vertical formant la paroi abdominale antérieure.', 'عضلة عمودية تشكل الجدار الأمامي للبطن.', 'Latin: abdomen — ''Abdomen / Belly''', 'Enclosed within the rectus sheath; intersected by tendinous intersections giving the segmented appearance.', '', 'Anatomie', 'Myologie', 'The rectus abdominis forms the ''six-pack'' muscles.', 'Le droit de l''abdomen forme les muscles ''abdominaux''.', 'تشكل العضلة المستقيمة للبطن عضلات ''البطن السداسية''.', '/ˈrek.təs æbˈdɒm.ɪ.nɪs/'),
(150, 'External oblique', 'Oblique externe', 'العضلة المائلة الخارجية', 'Muscle of the lateral abdominal wall, largest of the flat abdominal muscles.', 'Muscle de la paroi abdominale latérale, le plus grand des muscles abdominaux plats.', 'عضلة الجدار الجانبي للبطن، أكبر عضلات البطن المسطحة.', '', 'Fibers run inferomedially (''hands in pockets'' direction); its inferior aponeurosis forms the inguinal ligament.', '', 'Anatomie', 'Myologie', 'The external oblique compresses the abdominal contents.', 'L''oblique externe comprime le contenu abdominal.', 'تضغط العضلة المائلة الخارجية على محتويات البطن.', '/ɪkˈstɜː.nəl oʊˈbliːk/'),
(151, 'Latissimus dorsi', 'Grand dorsal', 'العضلة العريضة للظهر', 'The broadest muscle of the back, responsible for arm extension.', 'Le plus large muscle du dos, responsable de l''extension du bras.', 'أعرض عضلات الظهر، مسؤولة عن مد الذراع.', 'Latin: latissimus (''broadest'') + dorsum (''back'')', 'Extends, adducts, and medially rotates the humerus; innervated by the thoracodorsal nerve (C6-C8).', '', 'Anatomie', 'Myologie', 'The latissimus dorsi is used in pulling movements.', 'Le grand dorsal est utilisé dans les mouvements de traction.', 'تستخدم العضلة العريضة للظهر في حركات السحب.', '/ləˈtɪs.ɪ.məs ˈdɔː.saɪ/'),
(152, 'Erector spinae', 'Érecteurs du rachis', 'عضلات القامة الشوكية', 'Group of muscles that extend and maintain the spine upright.', 'Groupe de muscles qui étendent et maintiennent la colonne droite.', 'مجموعة عضلات تمد وتحافظ على استقامة العمود الفقري.', '', 'Primary extensor of the vertebral column; strain is a leading cause of mechanical lower back pain.', 'Columns lateral to medial: ''I Love Spaghetti'' (Iliocostalis, Longissimus, Spinalis).', 'Anatomie', 'Myologie', 'The erector spinae keeps the back upright.', 'Les érecteurs du rachis maintiennent le dos droit.', 'تحافظ عضلات القامة الشوكية على استقامة الظهر.', '/ɪˈrek.tər ˈspaɪ.niː/'),
(153, 'Deltoid', 'Deltoïde', 'العضلة الدالية', 'Triangular shoulder muscle responsible for arm abduction.', 'Muscle triangulaire de l''épaule responsable de l''abduction du bras.', 'عضلة الكتف المثلثة المسؤولة عن ابتعاد الذراع.', 'Greek: delta (Δ) + -oeides (''shaped like the capital Greek letter delta'')', 'Responsible for arm abduction from 15° to 90° (first 15° initiated by supraspinatus); common intramuscular injection site.', '', 'Anatomie', 'Myologie', 'The deltoid is the primary shoulder abductor.', 'Le deltoïde est le principal abducteur de l''épaule.', 'العضلة الدالية هي المُبعِّدة الرئيسية للكتف.', '/ˈdel.tɔɪd/'),
(154, 'Rotator cuff', 'Coiffe des rotateurs', 'الكفة المدورة', 'Group of 4 muscles stabilizing the shoulder joint.', 'Groupe de 4 muscles stabilisant l''articulation de l''épaule.', 'مجموعة من 4 عضلات تستقر مفصل الكتف.', '', 'The supraspinatus tendon is the most commonly torn component of the rotator cuff, causing painful arc syndrome (60°-120°).', '''SITS'' (Supraspinatus, Infraspinatus, Teres minor, Subscapularis).', 'Anatomie', 'Myologie', 'The rotator cuff consists of supraspinatus, infraspinatus, teres minor, and subscapularis.', 'La coiffe comprend le sus-épineux, sous-épineux, petit rond et sous-scapulaire.', 'تتكون الكفة المدورة من العضلة فوق الشوكية وتحت الشوكية والعضلة المدورة الصغيرة وتحت الكتف.', '/ˈroʊ.teɪ.tər kʌf/'),
(155, 'Biceps brachii', 'Biceps brachial', 'العضلة ذات الرأسين العضدية', 'Two-headed muscle on the front of the upper arm; flexes the elbow.', 'Muscle à deux chefs à l''avant du bras ; fléchit le coude.', 'عضلة ذات رأسين في مقدمة العضد؛ تثني المرفق.', '', 'Powerful supinator of the flexed forearm and elbow flexor; innervated by the musculocutaneous nerve (C5-C6).', '', 'Anatomie', 'Myologie', 'The biceps brachii flexes the forearm.', 'Le biceps brachial fléchit l''avant-bras.', 'تثني العضلة ذات الرأسين العضدية الساعد.', '/ˈbaɪ.seps ˈbreɪ.ki.aɪ/'),
(156, 'Triceps brachii', 'Triceps brachial', 'العضلة ذات الرؤوس الثلاثة العضدية', 'Three-headed muscle on the back of the upper arm; extends the elbow.', 'Muscle à trois chefs à l''arrière du bras ; étend le coude.', 'عضلة ذات ثلاثة رؤوس في خلف العضد؛ تمد المرفق.', '', 'Sole major extensor of the elbow joint; long head also adducts humerus; innervated by the radial nerve (C6-C8).', '', 'Anatomie', 'Myologie', 'The triceps brachii extends the forearm.', 'Le triceps brachial étend l''avant-bras.', 'تمد العضلة ذات الرؤوس الثلاثة العضدية الساعد.', '/ˈtraɪ.seps ˈbreɪ.ki.aɪ/'),
(157, 'Quadriceps femoris', 'Quadriceps fémoral', 'العضلة الرباعية الرؤوس الفخذية', 'Group of 4 muscles on the front of the thigh that extend the knee.', 'Groupe de 4 muscles à l''avant de la cuisse qui étendent le genou.', 'مجموعة من 4 عضلات في مقدمة الفخذ تمد الركبة.', 'Latin: femur — ''Femur / Thigh''', 'Composed of rectus femoris, vastus lateralis, vastus medialis, and vastus intermedius; innervated by femoral nerve (L2-L4).', '', 'Anatomie', 'Myologie', 'The quadriceps are the main extensors of the knee.', 'Les quadriceps sont les principaux extenseurs du genou.', 'العضلة الرباعية الرؤوس هي الباسطات الرئيسية للركبة.', '/ˈkwɒd.rɪ.seps ˈfem.ər.ɪs/'),
(158, 'Hamstrings', 'Ischio-jambiers', 'عضلات الوتر المأبضي', 'Group of 3 muscles on the back of the thigh that flex the knee.', 'Groupe de 3 muscles à l''arrière de la cuisse qui fléchissent le genou.', 'مجموعة من 3 عضلات في خلف الفخذ تثني الركبة.', '', 'Consists of biceps femoris, semitendinosus, and semimembranosus; extend the hip and flex the knee; innervated by the sciatic nerve.', '', 'Anatomie', 'Myologie', 'Hamstring injuries are common in sprinters.', 'Les blessures des ischio-jambiers sont fréquentes chez les sprinters.', 'إصابات عضلات الوتر المأبضي شائعة لدى العدائين.', '/ˈhæm.strɪŋz/'),
(159, 'Gluteus maximus', 'Grand fessier', 'العضلة الألوية الكبرى', 'The largest muscle in the body, forming the buttock.', 'Le plus grand muscle du corps, formant la fesse.', 'أكبر عضلة في الجسم، تشكل الأرداف.', '', 'Essential for standing up from a chair and climbing stairs; innervated by the inferior gluteal nerve (L5-S2).', '', 'Anatomie', 'Myologie', 'The gluteus maximus extends the hip joint.', 'Le grand fessier étend l''articulation de la hanche.', 'تمد العضلة الألوية الكبرى مفصل الورك.', '/ˌɡluː.ti.əs ˈmæk.sɪ.məs/'),
(160, 'Gastrocnemius', 'Gastrocnémien', 'عضلة الساق التوأمية', 'The main calf muscle, visible at the back of the lower leg.', 'Le muscle principal du mollet, visible à l''arrière de la jambe.', 'عضلة الساق الرئيسية، مرئية في خلف الساق.', 'Greek: gaster (''belly'') + kneme (''leg'')', 'Two heads originate on femoral condyles and insert into calcaneus via Achilles tendon; plantarflexes ankle and flexes knee.', '', 'Anatomie', 'Myologie', 'The gastrocnemius is used in walking and running.', 'Le gastrocnémien est utilisé lors de la marche et de la course.', 'تستخدم عضلة الساق التوأمية في المشي والجري.', '/ˌɡæs.trɒkˈniː.mi.əs/'),
(161, 'Soleus', 'Soléaire', 'العضلة النعلية', 'Deep calf muscle beneath the gastrocnemius.', 'Muscle profond du mollet sous le gastrocnémien.', 'عضلة الساق العميقة تحت العضلة التوأمية.', 'Latin: solea — ''flat sandal'' / ''sole fish''', 'Contains dense slow-twitch type I oxidative fibers; functions as the ''peripheral heart'' by pumping venous blood toward the inferior vena cava.', '', 'Anatomie', 'Myologie', 'The soleus is important for maintaining posture.', 'Le soléaire est important pour le maintien de la posture.', 'تعد العضلة النعلية مهمة للحفاظ على الوضعية.', '/ˈsoʊ.li.əs/'),
(162, 'Iliopsoas', 'Ilio-psoas', 'العضلة الحرقفية القطنية', 'Powerful hip flexor muscle connecting the spine to the femur.', 'Puissant muscle fléchisseur de la hanche reliant la colonne au fémur.', 'عضلة قوية لثني الورك تربط العمود الفقري بعظمة الفخذ.', '', 'Formed by psoas major and iliacus; inserts on the lesser trochanter of femur; positive psoas sign indicates retrocecal appendicitis.', '', 'Anatomie', 'Myologie', 'The iliopsoas flexes the hip and trunk.', 'L''ilio-psoas fléchit la hanche et le tronc.', 'تثني العضلة الحرقفية القطنية الورك والجذع.', '/ˌɪl.i.oʊˈsoʊ.əs/'),
(163, 'Adductor magnus', 'Grand adducteur', 'العضلة المقربة الكبرى', 'Largest of the adductor muscles, bringing the thigh toward midline.', 'Le plus grand des muscles adducteurs, rapprochant la cuisse de la ligne médiane.', 'أكبر العضلات المقربة، تقرب الفخذ نحو خط الوسط.', '', 'Contains the adductor hiatus through which femoral vessels pass into the popliteal fossa to become popliteal vessels.', '', 'Anatomie', 'Myologie', 'The adductor magnus adducts and extends the thigh.', 'Le grand adducteur adduit et étend la cuisse.', 'تقرب وتمد العضلة المقربة الكبرى الفخذ.', '/əˈdʌk.tər ˈmæɡ.nəs/'),
(164, 'Tibialis anterior', 'Tibial antérieur', 'العضلة الظنبوبية الأمامية', 'Muscle on the front of the shin that dorsiflexes the foot.', 'Muscle à l''avant du tibia qui effectue la dorsiflexion du pied.', 'عضلة في مقدمة القصبة تثني القدم ظهرياً.', '', 'Performs dorsiflexion and inversion of the foot; weakness causes high-steppage gait (foot drop).', '', 'Anatomie', 'Myologie', 'The tibialis anterior lifts the front of the foot.', 'Le tibial antérieur lève l''avant du pied.', 'ترفع العضلة الظنبوبية الأمامية مقدمة القدم.', '/ˌtɪb.iˈeɪ.lɪs ænˈtɪə.ri.ər/'),
(165, 'Sartorius', 'Couturier', 'عضلة الخياط', 'The longest muscle in the human body.', 'Le plus long muscle du corps humain.', 'أطول عضلة في جسم الإنسان.', 'Latin: sartor — ''tailor'' (crosses the legs into the tailor posture)', 'Crosses both hip and knee joints; inserts as part of pes anserinus (''goose foot'') alongside gracilis and semitendinosus.', '', 'Anatomie', 'Myologie', 'The sartorius crosses the front of the thigh.', 'Le couturier traverse l''avant de la cuisse.', 'تعبر عضلة الخياط مقدمة الفخذ.', '/sɑːˈtɔː.ri.əs/'),
(166, 'Intercostal muscles', 'Muscles intercostaux', 'العضلات بين الضلعية', 'Muscles between the ribs that assist in breathing.', 'Muscles entre les côtes qui participent à la respiration.', 'العضلات بين الأضلاع التي تساعد في التنفس.', '', 'External intercostals elevate ribs in inspiration; internal intercostals depress ribs in active expiration.', '', 'Anatomie', 'Myologie', 'Intercostal muscles expand the chest during inhalation.', 'Les muscles intercostaux élargissent la poitrine à l''inspiration.', 'تمدد العضلات بين الضلعية الصدر أثناء الشهيق.', '/ˌɪn.təˈkɒs.təl ˈmʌs.əlz/'),
(167, 'Brachioradialis', 'Brachio-radial', 'العضلة العضدية الكعبرية', 'Forearm muscle that flexes the elbow.', 'Muscle de l''avant-bras qui fléchit le coude.', 'عضلة الساعد التي تثني المرفق.', '', 'Flexes elbow especially when forearm is semi-pronated (''thumbs-up'' position); tests C5-C6 radial nerve reflex arc.', '', 'Anatomie', 'Myologie', 'The brachioradialis flexes the forearm at the elbow.', 'Le brachio-radial fléchit l''avant-bras au niveau du coude.', 'تثني العضلة العضدية الكعبرية الساعد عند المرفق.', '/ˌbreɪ.ki.oʊˌreɪ.diˈeɪ.lɪs/'),
(168, 'Flexor carpi radialis', 'Fléchisseur radial du carpe', 'العضلة المثنية الكعبرية للرسغ', 'Forearm muscle that flexes and abducts the wrist.', 'Muscle de l''avant-bras qui fléchit et abducte le poignet.', 'عضلة الساعد التي تثني الرسغ وتبعده.', '', 'Tendon lies medial to the radial artery at the wrist; serves as an anatomical landmark for palpating the radial pulse.', '', 'Anatomie', 'Myologie', 'The flexor carpi radialis flexes the wrist toward the radial side.', 'Le fléchisseur radial du carpe fléchit le poignet du côté radial.', 'تثني هذه العضلة الرسغ نحو جانب الكعبرة.', '/ˈflek.sər ˈkɑː.paɪ ˌreɪ.diˈeɪ.lɪs/'),
(169, 'Muscle origin', 'Origine musculaire', 'أصل العضلة', 'The fixed attachment point of a muscle, usually proximal.', 'Le point d''attache fixe d''un muscle, généralement proximal.', 'نقطة ارتباط العضلة الثابتة، عادةً القريبة.', '', 'Anchor point that remains relatively stable during muscle shortening while the insertion moves.', '', 'Anatomie', 'Myologie', 'The origin is the less movable attachment of a muscle.', 'L''origine est l''attache la moins mobile d''un muscle.', 'الأصل هو نقطة الارتباط الأقل حركة للعضلة.', '/ˈmʌs.əl ˈɒr.ɪ.dʒɪn/'),
(170, 'Muscle insertion', 'Insertion musculaire', 'انتهاء العضلة', 'The movable attachment point of a muscle, usually distal.', 'Le point d''attache mobile d''un muscle, généralement distal.', 'نقطة ارتباط العضلة المتحركة، عادةً البعيدة.', '', 'Attached to the bone that undergoes displacement when tension develops across the muscle.', '', 'Anatomie', 'Myologie', 'The insertion moves toward the origin during contraction.', 'L''insertion se déplace vers l''origine lors de la contraction.', 'يتحرك انتهاء العضلة نحو أصلها أثناء الانقباض.', '/ˈmʌs.əl ɪnˈsɜː.ʃən/'),
(171, 'Agonist muscle', 'Muscle agoniste', 'العضلة الموافقة', 'The prime mover, the main muscle producing a specific movement.', 'Le moteur principal, le muscle produisant un mouvement spécifique.', 'المحرك الرئيسي، العضلة الأساسية التي تنتج حركة معينة.', 'Greek: agonistes — ''combatant'' / ''champion'' / ''prime actor''', 'Provides primary mechanical vector force for a designated joint movement (e.g., quadriceps for knee extension).', '', 'Anatomie', 'Myologie', 'The biceps is the agonist in elbow flexion.', 'Le biceps est l''agoniste lors de la flexion du coude.', 'العضلة ذات الرأسين هي الموافقة في ثني المرفق.', '/ˈæɡ.ə.nɪst ˈmʌs.əl/'),
(172, 'Antagonist muscle', 'Muscle antagoniste', 'العضلة المضادة', 'Muscle that opposes the action of the agonist.', 'Muscle qui s''oppose à l''action de l''agoniste.', 'العضلة التي تعارض عمل العضلة الموافقة.', '', 'Relaxes progressively via reciprocal inhibition (Ia inhibitory interneurons) to allow smooth coordinated agonist movement.', '', 'Anatomie', 'Myologie', 'The triceps is the antagonist of the biceps.', 'Le triceps est l''antagoniste du biceps.', 'العضلة ذات الرؤوس الثلاثة هي المضادة لعضلة ذات الرأسين.', '/ænˈtæɡ.ə.nɪst ˈmʌs.əl/'),
(173, 'Muscle fiber', 'Fibre musculaire', 'الليف العضلي', 'A single muscle cell', 'Une cellule musculaire unique', 'خلية عضلية واحدة', '', '', '', 'Anatomie', 'Myologie', 'The muscle fiber is the single muscle cell.', 'La fibre musculaire est une cellule musculaire unique.', 'الليف العضلي هو خلية عضلية واحدة.', '/ˈmʌsəl ˈfaɪbər/'),
(174, 'Relaxation', 'Relâchement', 'الاسترخاء', 'The lengthening of a muscle after contraction', 'Allongement d''un muscle après la contraction', 'استطالة العضلة بعد التقلص', '', '', '', 'Anatomie', 'Myologie', 'The relaxation is the lengthening of a muscle after contraction.', 'Le relâchement est allongement d''un muscle après la contraction.', 'الاسترخاء هو استطالة العضلة بعد التقلص.', '/ˌriːlækˈseɪʃən/'),
(175, 'Synergist', 'Synergiste', 'العضلة المساعدة', 'A muscle that assists the agonist in performing a movement', 'Muscle qui assiste l''agoniste dans l''exécution d''un mouvement', 'عضلة تساعد العضلة المحركة في أداء حركة ما', '', '', '', 'Anatomie', 'Myologie', 'The synergist is the muscle that assists the agonist in performing a movement.', 'La synergiste est muscle qui assiste l''agoniste dans l''exécution d''un mouvement.', 'العضلة المساعدة هو عضلة تساعد العضلة المحركة في أداء حركة ما.', '/ˈsɪnərdʒɪst/'),
(176, 'Temporalis', 'Temporal', 'العضلة الصدغية', 'A fan-shaped muscle of mastication on the lateral skull', 'Muscle de mastication en forme d''éventail sur le crâne latéral', 'عضلة مضغ مروحية الشكل على جانب الجمجمة', '', '', '', 'Anatomie', 'Myologie', 'The temporalis is the fan-shaped muscle of mastication on the lateral skull.', 'Le temporal est muscle de mastication en forme d''éventail sur le crâne latéral.', 'العضلة الصدغية هو عضلة مضغ مروحية الشكل على جانب الجمجمة.', '/ˌtɛmpəˈreɪlɪs/'),
(177, 'Orbicularis oris', 'Orbiculaire de la bouche', 'العضلة الدويرية الفموية', 'The muscle surrounding the mouth responsible for lip movements', 'Muscle entourant la bouche responsable des mouvements des lèvres', 'العضلة المحيطة بالفم المسؤولة عن حركات الشفاه', '', '', '', 'Anatomie', 'Myologie', 'The orbicularis oris is the muscle surrounding the mouth responsible for lip movements.', 'L''orbiculaire de la bouche est muscle entourant la bouche responsable des mouvements des lèvres.', 'العضلة الدويرية الفموية هو العضلة المحيطة بالفم المسؤولة عن حركات الشفاه.', '/ɔːrˌbɪkjʊˈlɛrɪs ˈɔːrɪs/'),
(178, 'Internal oblique', 'Oblique interne', 'العضلة المائلة الباطنة', 'The lateral abdominal muscle deep to the external oblique', 'Muscle abdominal latéral profond par rapport à l''oblique externe', 'العضلة البطنية الجانبية العميقة تحت المائلة الظاهرة', '', '', '', 'Anatomie', 'Myologie', 'The internal oblique is the lateral abdominal muscle deep to the external oblique.', 'L''oblique interne est muscle abdominal latéral profond par rapport à l''oblique externe.', 'العضلة المائلة الباطنة هو العضلة البطنية الجانبية العميقة تحت المائلة الظاهرة.', '/ɪnˈtɜːrnəl əˈbliːk/'),
(179, 'Transversus abdominis', 'Transverse de l''abdomen', 'العضلة البطنية المستعرضة', 'The deepest layer of abdominal muscles', 'La couche la plus profonde des muscles abdominaux', 'الطبقة الأعمق من عضلات البطن', 'Latin: abdomen — ''Abdomen / Belly''', '', '', 'Anatomie', 'Myologie', 'The transversus abdominis is the deepest layer of abdominal muscles.', 'La transverse de l''abdomen est la couche la plus profonde des muscles abdominaux.', 'العضلة البطنية المستعرضة هو الطبقة الأعمق من عضلات البطن.', '/trænsˈvɜːrsəs æbˈdɒmɪnɪs/'),
(180, 'Brachialis', 'Brachial antérieur', 'العضلة العضدية', 'A muscle of the anterior arm deep to the biceps, powerful flexor of the elbow', 'Muscle de la face antérieure du bras profond au biceps, puissant fléchisseur du coude', 'عضلة في الوجه الأمامي للذراع تحت العضلة ذات الرأسين، ثانية قوية للمرفق', '', '', '', 'Anatomie', 'Myologie', 'The brachialis is the muscle of the anterior arm deep to the biceps, powerful flexor of the elbow.', 'Le brachial antérieur est muscle de la face antérieure du bras profond au biceps, puissant fléchisseur du coude.', 'العضلة العضدية هو عضلة في الوجه الأمامي للذراع تحت العضلة ذات الرأسين، ثانية قوية للمرفق.', '/ˌbreɪkiˈælɪs/'),
(181, 'Gluteus medius', 'Moyen fessier', 'العضلة الألوية الوسطى', 'The muscle of the hip responsible for abduction of the thigh', 'Muscle de la hanche responsable de l''abduction de la cuisse', 'عضلة الورك المسؤولة عن تبعيد الفخذ', '', '', '', 'Anatomie', 'Myologie', 'The gluteus medius is the muscle of the hip responsible for abduction of the thigh.', 'La moyen fessier est muscle de la hanche responsable de l''abduction de la cuisse.', 'العضلة الألوية الوسطى هو عضلة الورك المسؤولة عن تبعيد الفخذ.', '/ˈɡluːtiəs ˈmiːdiəs/'),
(182, 'Adductor muscles', 'Muscles adducteurs', 'العضلات المقربة', 'A group of muscles on the medial thigh that adduct the leg', 'Groupe de muscles de la face interne de la cuisse qui rapprochent la jambe', 'مجموعة عضلات في الوجه الداخلي للفخذ تقرب الساق', '', '', '', 'Anatomie', 'Myologie', 'The adductor muscles is the group of muscles on the medial thigh that adduct the leg.', 'La muscles adducteurs est groupe de muscles de la face interne de la cuisse qui rapprochent la jambe.', 'العضلات المقربة هو مجموعة عضلات في الوجه الداخلي للفخذ تقرب الساق.', '/əˈdʌktər ˈmʌsəlz/'),
(183, 'Achilles tendon', 'Tendon d''Achille (Tendon calcanéen)', 'وتر أخيل (الوتر العقبي)', 'The thick tendon connecting the calf muscles to the calcaneus', 'Tendon épais reliant les muscles du mollet au calcanéum', 'الوتر السميك الذي يربط عضلات الساق بعظم العقب', '', '', '', 'Anatomie', 'Myologie', 'The achilles tendon is the thick tendon connecting the calf muscles to the calcaneus.', 'Le tendon d''Achille (Tendon calcanéen) est tendon épais reliant les muscles du mollet au calcanéum.', 'وتر أخيل (الوتر العقبي) هو الوتر السميك الذي يربط عضلات الساق بعظم العقب.', '/əˈkɪliːz ˈtɛndən/'),
(184, 'Neuron', 'Neurone', 'الخلية العصبية', 'The basic functional unit of the nervous system.', 'L''unité fonctionnelle de base du système nerveux.', 'الوحدة الوظيفية الأساسية للجهاز العصبي.', 'Greek: neuron — ''nerve'' / ''sinew'' / ''cord''', 'Excitable cell composed of soma (cell body), dendrites, and an axon; amitotic in adulthood with rare neurogenesis in hippocampus.', '', 'Anatomie', 'Neurologie', 'The brain contains approximately 86 billion neurons.', 'Le cerveau contient environ 86 milliards de neurones.', 'يحتوي الدماغ على ما يقارب 86 مليار خلية عصبية.', '/ˈnjʊə.rɒn/'),
(185, 'Dendrite', 'Dendrite', 'التغصن العصبي', 'Branching extensions of a neuron that receive signals.', 'Extensions ramifiées d''un neurone qui reçoivent les signaux.', 'امتدادات متفرعة للخلية العصبية تستقبل الإشارات.', 'Greek: dendron — ''tree''', 'Covered in dendritic spines that undergo dynamic synaptic plasticity during learning and long-term potentiation (LTP).', '', 'Anatomie', 'Neurologie', 'Dendrites receive signals from other neurons.', 'Les dendrites reçoivent les signaux des autres neurones.', 'تستقبل التغصنات الإشارات من الخلايا العصبية الأخرى.', '/ˈden.draɪt/'),
(186, 'Axon', 'Axone', 'المحور العصبي', 'Long projection of a neuron that transmits signals away from the cell body.', 'Long prolongement d''un neurone qui transmet les signaux loin du corps cellulaire.', 'امتداد طويل للخلية العصبية ينقل الإشارات بعيداً عن جسم الخلية.', 'Greek: axon — ''axis'' / ''axle''', 'Originates from the axon hillock where action potentials are initiated; communicates with target cells via terminal boutons.', '', 'Anatomie', 'Neurologie', 'The axon transmits nerve impulses to other cells.', 'L''axone transmet les influx nerveux aux autres cellules.', 'ينقل المحور العصبي النبضات العصبية إلى الخلايا الأخرى.', '/ˈæk.sɒn/'),
(187, 'Myelin sheath', 'Gaine de myéline', 'غمد المايلين', 'Insulating layer around axons that speeds up nerve impulse transmission.', 'Couche isolante autour des axones accélérant la transmission nerveuse.', 'طبقة عازلة حول المحاور العصبية تسرّع نقل النبضات العصبية.', '', 'Produced by oligodendrocytes in the CNS and Schwann cells in the PNS; enables rapid saltatory conduction across nodes of Ranvier.', '', 'Anatomie', 'Neurologie', 'Multiple sclerosis destroys the myelin sheath.', 'La sclérose en plaques détruit la gaine de myéline.', 'يدمر التصلب المتعدد غمد المايلين.', '/ˈmaɪ.ə.lɪn ʃiːθ/'),
(188, 'Synapse', 'Synapse', 'المشبك العصبي', 'Junction between two neurons where signals are transmitted.', 'Jonction entre deux neurones où les signaux sont transmis.', 'نقطة التقاء بين خليتين عصبيتين حيث تنتقل الإشارات.', 'Greek: synapsis — ''clasping'' / ''connection''', 'Consists of presynaptic terminal, 20-40 nm synaptic cleft, and postsynaptic membrane with ligand-gated receptors.', '', 'Anatomie', 'Neurologie', 'Neurotransmitters cross the synapse to transmit signals.', 'Les neurotransmetteurs traversent la synapse pour transmettre les signaux.', 'تعبر الناقلات العصبية المشبك لنقل الإشارات.', '/ˈsaɪ.næps/'),
(189, 'Neurotransmitter', 'Neurotransmetteur', 'الناقل العصبي', 'Chemical messenger that transmits signals across a synapse.', 'Messager chimique qui transmet les signaux à travers une synapse.', 'رسول كيميائي ينقل الإشارات عبر المشبك العصبي.', 'Greek: νεῦρον (neûron) — ''Nerve / Nervous system''', 'GABA is the chief inhibitory neurotransmitter of the brain; Glutamate is the primary excitatory neurotransmitter.', '', 'Anatomie', 'Neurologie', 'Dopamine and serotonin are important neurotransmitters.', 'La dopamine et la sérotonine sont des neurotransmetteurs importants.', 'الدوبامين والسيروتونين ناقلات عصبية مهمة.', '/ˌnjʊə.roʊ.trænzˈmɪt.ər/'),
(190, 'Brain', 'Cerveau', 'الدماغ', 'The central organ of the nervous system, enclosed in the skull.', 'L''organe central du système nerveux, enfermé dans le crâne.', 'العضو المركزي للجهاز العصبي، محاط بالجمجمة.', '', 'Consumes ~20% of the body''s resting cardiac output and oxygen despite representing only ~2% of total body mass.', '', 'Anatomie', 'Neurologie', 'The adult brain weighs approximately 1.4 kg.', 'Le cerveau adulte pèse environ 1,4 kg.', 'يزن دماغ البالغ حوالي 1.4 كيلوغرام.', '/breɪn/'),
(191, 'Cerebrum', 'Cerveau (hémisphères cérébraux)', 'المخ', 'The largest part of the brain, responsible for higher functions.', 'La plus grande partie du cerveau, responsable des fonctions supérieures.', 'الجزء الأكبر من الدماغ، المسؤول عن الوظائف العليا.', 'Latin: cerebrum — ''brain''', 'Hemispheres are separated by the longitudinal cerebral fissure and connected by the corpus callosum.', '', 'Anatomie', 'Neurologie', 'The cerebrum is divided into right and left hemispheres.', 'Le cerveau est divisé en hémisphères droit et gauche.', 'ينقسم المخ إلى نصفي كرة أيمن وأيسر.', '/səˈriː.brəm/'),
(192, 'Cerebellum', 'Cervelet', 'المخيخ', 'Part of brain responsible for coordination and balance.', 'Partie du cerveau responsable de la coordination et de l''équilibre.', 'جزء من الدماغ مسؤول عن التنسيق والتوازن.', 'Latin: cerebellum — diminutive of cerebrum (''little brain'')', 'Cerebellar lesions produce ipsilateral ataxia, dysmetria, dysdiadochokinesia, and intention tremor (mnemonic: ''VANISHED'').', '', 'Anatomie', 'Neurologie', 'The cerebellum coordinates voluntary movements.', 'Le cervelet coordonne les mouvements volontaires.', 'ينسق المخيخ الحركات الإرادية.', '/ˌser.əˈbel.əm/'),
(193, 'Brain stem', 'Tronc cérébral', 'جذع الدماغ', 'Lower part of brain connecting the cerebrum to the spinal cord.', 'Partie inférieure du cerveau reliant les hémisphères à la moelle épinière.', 'الجزء السفلي من الدماغ يربط المخ بالحبل الشوكي.', '', 'Composed of midbrain, pons, and medulla oblongata; houses cranial nerve nuclei III through XII and the reticular activating system (RAS).', '', 'Anatomie', 'Neurologie', 'The brain stem controls basic life functions like breathing.', 'Le tronc cérébral contrôle les fonctions vitales comme la respiration.', 'يتحكم جذع الدماغ في وظائف الحياة الأساسية كالتنفس.', '/ˈbreɪn ˌstem/'),
(194, 'Medulla oblongata', 'Moelle allongée (bulbe rachidien)', 'النخاع المستطيل', 'Lowest part of the brain stem controlling heart rate and breathing.', 'Partie la plus basse du tronc cérébral contrôlant la fréquence cardiaque.', 'أدنى جزء من جذع الدماغ يتحكم في معدل القلب والتنفس.', '', 'Houses autonomic centers for cardiovascular, vasomotor, and respiratory rhythmicity; site of pyramidal decussation of corticospinal tracts.', '', 'Anatomie', 'Neurologie', 'The medulla oblongata contains vital centers for breathing and heart rate.', 'Le bulbe rachidien contient les centres vitaux pour la respiration et la FC.', 'يحتوي النخاع المستطيل على مراكز حيوية للتنفس ومعدل القلب.', '/mɪˈdʌl.ə ˌɒb.lɒŋˈɡɑː.tə/'),
(195, 'Pons', 'Pont (Protubérance)', 'الجسر', 'Part of the brain stem between the medulla and midbrain.', 'Partie du tronc cérébral entre la moelle et le mésencéphale.', 'جزء من جذع الدماغ بين النخاع المستطيل والدماغ المتوسط.', 'Latin: pons — ''bridge''', 'Gives exit to cranial nerves V (trigeminal), VI (abducens), VII (facial), and VIII (vestibulocochlear); locked-in syndrome occurs in basilar artery thrombosis.', '', 'Anatomie', 'Neurologie', 'The pons relays signals between the brain and cerebellum.', 'Le pont relaie les signaux entre le cerveau et le cervelet.', 'ينقل الجسر الإشارات بين الدماغ والمخيخ.', '/pɒnz/'),
(196, 'Midbrain', 'Mésencéphale', 'الدماغ المتوسط', 'Part of the brain stem involved in vision, hearing, and motor control.', 'Partie du tronc cérébral impliquée dans la vision, l''audition et le contrôle moteur.', 'جزء من جذع الدماغ يشارك في الرؤية والسمع والتحكم الحركي.', '', 'Contains substantia nigra (dopaminergic degeneration causes Parkinson''s disease), red nucleus, and superior/inferior colliculi.', '', 'Anatomie', 'Neurologie', 'The midbrain contains the substantia nigra.', 'Le mésencéphale contient la substance noire.', 'يحتوي الدماغ المتوسط على المادة السوداء.', '/ˈmɪd.breɪn/'),
(197, 'Thalamus', 'Thalamus', 'المهاد', 'Relay station for sensory and motor signals between the body and cerebrum.', 'Station de relais pour les signaux sensoriels et moteurs.', 'محطة ترحيل للإشارات الحسية والحركية بين الجسم والمخ.', 'Greek: thalamos — ''inner room'' / ''bridal bed''', 'Relays all sensory information to the cerebral cortex with the sole exception of olfaction (smell).', '', 'Anatomie', 'Neurologie', 'The thalamus processes and relays sensory information.', 'Le thalamus traite et relaie les informations sensorielles.', 'يعالج المهاد المعلومات الحسية ويرحلها.', '/ˈθæl.ə.məs/'),
(198, 'Hypothalamus', 'Hypothalamus', 'تحت المهاد', 'Controls the autonomic nervous system, hormones, and homeostasis.', 'Contrôle le système nerveux autonome, les hormones et l''homéostasie.', 'يتحكم في الجهاز العصبي اللاإرادي والهرمونات والاتزان الداخلي.', '', 'Master controller of the endocrine system via hypophyseal portal circulation; governs circadian rhythm (suprachiasmatic nucleus) and thirst/osmolality.', '', 'Anatomie', 'Neurologie', 'The hypothalamus regulates body temperature and hunger.', 'L''hypothalamus régule la température corporelle et la faim.', 'ينظم تحت المهاد درجة حرارة الجسم والجوع.', '/ˌhaɪ.poʊˈθæl.ə.məs/'),
(199, 'Spinal cord', 'Moelle épinière', 'الحبل الشوكي', 'Column of nervous tissue extending from the brain stem through the spine.', 'Colonne de tissu nerveux s''étendant du tronc cérébral à travers la colonne.', 'عمود من الأنسجة العصبية يمتد من جذع الدماغ عبر العمود الفقري.', '', 'Terminates at the conus medullaris around L1-L2 in adults; lumbar punctures are safely performed at L3-L4 or L4-L5 level.', '', 'Anatomie', 'Neurologie', 'The spinal cord transmits messages between brain and body.', 'La moelle épinière transmet des messages entre le cerveau et le corps.', 'ينقل الحبل الشوكي الرسائل بين الدماغ والجسم.', '/ˈspaɪ.nəl kɔːd/'),
(200, 'Meninges', 'Méninges', 'السحايا', 'Three protective membranes covering the brain and spinal cord.', 'Trois membranes protectrices couvrant le cerveau et la moelle épinière.', 'ثلاثة أغشية واقية تغطي الدماغ والحبل الشوكي.', 'Greek: meninx — ''membrane''', 'Meningitis presents with fever, nuchal rigidity, headache, and positive Kernig and Brudzinski signs.', 'From outside in: ''PAD'' (Pia, Arachnoid, Dura reversed: Dura, Arachnoid, Pia).', 'Anatomie', 'Neurologie', 'The three meninges are dura mater, arachnoid, and pia mater.', 'Les trois méninges sont la dure-mère, l''arachnoïde et la pie-mère.', 'السحايا الثلاثة هي: الأم الجافية والأم العنكبوتية والأم الحنون.', '/mɪˈnɪn.dʒiːz/')
insert into medical_terms (id, term_en, term_fr, term_ar, definition_en, definition_fr, definition_ar, etymology, clinical_pearl, mnemonic, module, chapter, example_en, example_fr, example_ar, ipa_phonetic) values
(201, 'Dura mater', 'Dure-mère', 'الأم الجافية', 'Tough outermost layer of the meninges.', 'Couche externe résistante des méninges.', 'الطبقة الخارجية الصلبة للسحايا.', 'Latin: dura mater — ''hard mother''', 'Forms dural reflections (falx cerebri, tentorium cerebelli) and contains dural venous sinuses.', '', 'Anatomie', 'Neurologie', 'The dura mater is the thickest of the three meninges.', 'La dure-mère est la plus épaisse des trois méninges.', 'الأم الجافية هي أسمك الأغشية السحائية الثلاثة.', '/ˌdjʊə.rə ˈmeɪ.tər/'),
(202, 'Arachnoid mater', 'Arachnoïde', 'الأم العنكبوتية', 'Middle meningeal layer with a web-like structure.', 'Couche méningée intermédiaire avec une structure en toile d''araignée.', 'الطبقة السحائية الوسطى ذات البنية الشبيهة بشبكة العنكبوت.', 'Greek: arachne (''spider'') + eidos (''resemblance'')', 'Subarachnoid hemorrhage (ruptured berry aneurysm) causes sudden ''worst headache of life'' (thunderclap headache).', '', 'Anatomie', 'Neurologie', 'The subarachnoid space contains cerebrospinal fluid.', 'L''espace sous-arachnoïdien contient le liquide cérébrospinal.', 'يحتوي الفضاء تحت العنكبوتية على السائل الدماغي الشوكي.', '/əˈræk.nɔɪd ˈmeɪ.tər/'),
(203, 'Pia mater', 'Pie-mère', 'الأم الحنون', 'Delicate innermost layer of the meninges, directly covering the brain.', 'Couche interne délicate des méninges, directement sur le cerveau.', 'الطبقة الداخلية الرقيقة للسحايا، تغطي الدماغ مباشرةً.', 'Latin: pia mater — ''tender / pious mother''', 'Highly vascularized membrane dipping directly into all cerebral sulci and fissures; extends laterally as denticulate ligaments in the spine.', '', 'Anatomie', 'Neurologie', 'The pia mater closely follows the brain''s surface contours.', 'La pie-mère suit étroitement les contours de la surface du cerveau.', 'تتبع الأم الحنون عن كثب ملامح سطح الدماغ.', '/ˌpaɪ.ə ˈmeɪ.tər/'),
(204, 'Cerebrospinal fluid (CSF)', 'Liquide céphalorachidien (LCR)', 'السائل الدماغي الشوكي', 'Clear fluid surrounding the brain and spinal cord for protection.', 'Liquide clair entourant le cerveau et la moelle pour les protéger.', 'سائل شفاف يحيط بالدماغ والحبل الشوكي لحمايتهما.', '', 'Produced by ependymal cells in the choroid plexus (~500 mL/day); reabsorbed through arachnoid granulations into the superior sagittal sinus.', '', 'Anatomie', 'Neurologie', 'CSF acts as a cushion protecting the brain.', 'Le LCR agit comme un coussin protégeant le cerveau.', 'يعمل السائل الدماغي الشوكي كوسادة لحماية الدماغ.', '/ˌser.ɪ.broʊˈspaɪ.nəl ˈfluː.ɪd/'),
(205, 'Frontal lobe', 'Lobe frontal', 'الفص الجبهي', 'Anterior lobe of the cerebrum controlling movement and higher thinking.', 'Lobe antérieur du cerveau contrôlant la motricité et la réflexion supérieure.', 'الفص الأمامي من المخ يتحكم في الحركة والتفكير العالي.', '', 'Houses the primary motor cortex (precentral gyrus, Brodmann area 4) and Broca''s motor speech area (Brodmann 44/45, damage = non-fluent aphasia).', '', 'Anatomie', 'Neurologie', 'The frontal lobe is responsible for decision-making.', 'Le lobe frontal est responsable de la prise de décision.', 'الفص الجبهي مسؤول عن اتخاذ القرار.', '/ˈfrʌn.təl loʊb/'),
(206, 'Parietal lobe', 'Lobe pariétal', 'الفص الجداري', 'Lobe processing sensory information from the body.', 'Lobe traitant les informations sensorielles du corps.', 'الفص الذي يعالج المعلومات الحسية من الجسم.', '', 'Houses the primary somatosensory cortex (postcentral gyrus, Brodmann 3, 1, 2) mapped to sensory homunculus; nondominant lesion produces hemispatial neglect.', '', 'Anatomie', 'Neurologie', 'The parietal lobe processes touch and spatial awareness.', 'Le lobe pariétal traite le toucher et la conscience spatiale.', 'يعالج الفص الجداري اللمس والوعي المكاني.', '/pəˈraɪ.ə.təl loʊb/'),
(207, 'Temporal lobe', 'Lobe temporal', 'الفص الصدغي', 'Lobe responsible for hearing, language, and memory.', 'Lobe responsable de l''audition, du langage et de la mémoire.', 'الفص المسؤول عن السمع واللغة والذاكرة.', '', 'Contains primary auditory cortex (Heschl''s gyri) and Wernicke''s receptive language area (damage = fluent sensory aphasia).', '', 'Anatomie', 'Neurologie', 'The temporal lobe processes auditory information.', 'Le lobe temporal traite les informations auditives.', 'يعالج الفص الصدغي المعلومات السمعية.', '/ˈtem.pər.əl loʊb/'),
(208, 'Occipital lobe', 'Lobe occipital', 'الفص القذالي', 'Posterior lobe of the cerebrum responsible for vision.', 'Lobe postérieur du cerveau responsable de la vision.', 'الفص الخلفي من المخ المسؤول عن الرؤية.', '', 'Houses primary visual cortex (Brodmann area 17, V1) surrounding the calcarine sulcus; vascular supply is from posterior cerebral artery (PCA).', '', 'Anatomie', 'Neurologie', 'The occipital lobe contains the primary visual cortex.', 'Le lobe occipital contient le cortex visuel primaire.', 'يحتوي الفص القذالي على القشرة البصرية الأولية.', '/ɒkˈsɪp.ɪ.təl loʊb/'),
(209, 'Corpus callosum', 'Corps calleux', 'الجسم الثفني', 'Band of nerve fibers connecting the two cerebral hemispheres.', 'Bande de fibres nerveuses reliant les deux hémisphères cérébraux.', 'حزمة من الألياف العصبية تربط نصفي الكرة المخية.', 'Latin: corpus (''body'') + callosum (''tough'' / ''hardened'')', 'Largest commissural white matter tract (>200 million axons); surgical callosotomy is used in refractory drop-attack epilepsy (''split-brain'').', '', 'Anatomie', 'Neurologie', 'The corpus callosum allows communication between brain hemispheres.', 'Le corps calleux permet la communication entre les hémisphères cérébraux.', 'يسمح الجسم الثفني بالتواصل بين نصفي الكرة المخية.', '/ˌkɔː.pəs kəˈloʊ.səm/'),
(210, 'Hippocampus', 'Hippocampe', 'قرن آمون (الحصين)', 'Brain structure essential for memory formation and spatial navigation.', 'Structure cérébrale essentielle pour la formation de la mémoire.', 'بنية دماغية أساسية لتكوين الذاكرة والملاحة المكانية.', 'Greek: hippokampos — ''seahorse'' (hippos ''horse'' + kampos ''sea monster'')', 'Crucial for consolidating declarative (episodic/semantic) memories; severely atrophied early in Alzheimer''s disease.', '', 'Anatomie', 'Neurologie', 'The hippocampus converts short-term to long-term memory.', 'L''hippocampe convertit la mémoire à court terme en mémoire à long terme.', 'يحوّل الحصين الذاكرة قصيرة المدى إلى ذاكرة طويلة المدى.', '/ˌhɪp.əˈkæm.pəs/'),
(211, 'Amygdala', 'Amygdale (cérébrale)', 'اللوزة الدماغية', 'Almond-shaped brain structure involved in emotions and fear response.', 'Structure cérébrale en amande impliquée dans les émotions et la réponse à la peur.', 'بنية دماغية على شكل لوزة تشارك في العواطف واستجابة الخوف.', 'Greek: amygdale — ''almond''', 'Core limbic component for emotional memory and fear conditioning; bilateral destruction produces Klüver-Bucy syndrome (docility, hyperorality).', '', 'Anatomie', 'Neurologie', 'The amygdala processes fear and emotional responses.', 'L''amygdale traite la peur et les réponses émotionnelles.', 'تعالج اللوزة الدماغية الخوف والاستجابات العاطفية.', '/əˈmɪɡ.də.lə/'),
(212, 'Cerebral cortex', 'Cortex cérébral', 'القشرة الدماغية', 'Outer layer of the cerebrum involved in higher cognitive functions.', 'Couche externe du cerveau impliquée dans les fonctions cognitives supérieures.', 'الطبقة الخارجية للمخ المشاركة في الوظائف المعرفية العليا.', 'Latin: cortex — ''bark'' / ''rind''', 'Contains 6 distinct histological layers (neocortex) with pyramidal neurons; folded into gyri and sulci to triple its surface area.', '', 'Anatomie', 'Neurologie', 'The cerebral cortex is responsible for consciousness and thought.', 'Le cortex cérébral est responsable de la conscience et de la pensée.', 'القشرة الدماغية مسؤولة عن الوعي والتفكير.', '/səˈriː.brəl ˈkɔː.teks/'),
(213, 'Gray matter', 'Substance grise', 'المادة الرمادية', 'Neural tissue containing cell bodies, found in the outer brain and inner cord.', 'Tissu neural contenant les corps cellulaires, dans la partie externe du cerveau.', 'النسيج العصبي الذي يحتوي على أجسام الخلايا.', '', 'Contains neuronal somas, dendrites, and unmyelinated synapses; forms the cerebral cortex and deep nuclei (basal ganglia, thalamus).', '', 'Anatomie', 'Neurologie', 'Gray matter processes information in the brain.', 'La substance grise traite les informations dans le cerveau.', 'تعالج المادة الرمادية المعلومات في الدماغ.', '/ɡreɪ ˈmæt.ər/'),
(214, 'White matter', 'Substance blanche', 'المادة البيضاء', 'Neural tissue consisting of myelinated axons transmitting signals.', 'Tissu neural composé d''axones myélinisés transmettant les signaux.', 'نسيج عصبي يتكون من محاور مغطاة بالمايلين تنقل الإشارات.', '', 'Classified into projection fibers (internal capsule), association fibers (arcuate fasciculus), and commissural fibers (corpus callosum).', '', 'Anatomie', 'Neurologie', 'White matter connects different areas of gray matter.', 'La substance blanche connecte différentes zones de substance grise.', 'تربط المادة البيضاء مناطق مختلفة من المادة الرمادية.', '/waɪt ˈmæt.ər/'),
(215, 'Cranial nerve', 'Nerf crânien', 'العصب القحفي', 'One of 12 pairs of nerves originating directly from the brain.', 'Une des 12 paires de nerfs issus directement du cerveau.', 'أحد 12 زوجاً من الأعصاب تنشأ مباشرةً من الدماغ.', 'Greek: κρανίον (kraníon) — ''Skull / Cranium''', 'CN I & II arise from forebrain; CN III & IV from midbrain; CN V to VIII from pons; CN IX to XII from medulla.', '''On Old Olympus Towering Tops A Fin And German Viewed Some Hops'' (CN I to XII).', 'Anatomie', 'Neurologie', 'There are 12 pairs of cranial nerves numbered I to XII.', 'Il y a 12 paires de nerfs crâniens numérotés de I à XII.', 'يوجد 12 زوجاً من الأعصاب القحفية مرقمة من I إلى XII.', '/ˈkreɪ.ni.əl nɜːv/'),
(216, 'Vagus nerve (CN X)', 'Nerf vague (NC X)', 'العصب المبهم (العاشر)', 'The longest cranial nerve, innervating many organs of the thorax and abdomen.', 'Le plus long nerf crânien, innervant les organes du thorax et de l''abdomen.', 'أطول الأعصاب القحفية، يعصّب أعضاء الصدر والبطن.', 'Latin: vagus — ''wandering'' / ''roaming''', 'Provides 75% of all parasympathetic outflow to the body; carries carotid baroreceptor sensory afferents via aortic arch branches.', '', 'Anatomie', 'Neurologie', 'The vagus nerve controls heart rate and digestion.', 'Le nerf vague contrôle la fréquence cardiaque et la digestion.', 'يتحكم العصب المبهم في معدل ضربات القلب والهضم.', '/ˈveɪ.ɡəs nɜːv/'),
(217, 'Sciatic nerve', 'Nerf sciatique', 'العصب الوركي', 'The longest and thickest nerve in the body, running from the lower back to the foot.', 'Le nerf le plus long et le plus épais du corps, allant du bas du dos au pied.', 'أطول وأسمك عصب في الجسم، يمتد من أسفل الظهر إلى القدم.', 'Greek: ischiadikos — ''of the hip''', 'Formed by L4-S3 roots of lumbosacral plexus; exits greater sciatic foramen beneath piriformis; splits into tibial and common fibular nerves.', '', 'Anatomie', 'Neurologie', 'Sciatica is pain along the sciatic nerve.', 'La sciatique est une douleur le long du nerf sciatique.', 'عرق النسا هو ألم على طول العصب الوركي.', '/saɪˈæt.ɪk nɜːv/'),
(218, 'Reflex arc', 'Arc réflexe', 'القوس الانعكاسي', 'Neural pathway for an automatic reflex response without brain involvement.', 'Voie neuronale pour une réponse réflexe automatique sans implication du cerveau.', 'مسار عصبي للاستجابة الانعكاسية التلقائية دون تدخل الدماغ.', '', 'Consists of 5 essential elements: receptor, afferent sensory neuron, integration center, efferent motor neuron, and effector organ.', '', 'Anatomie', 'Neurologie', 'The knee-jerk reflex is a simple reflex arc.', 'Le réflexe rotulien est un arc réflexe simple.', 'منعكس الركبة هو قوس انعكاسي بسيط.', '/ˈriː.fleks ɑːk/'),
(219, 'Nerve', 'Nerf', 'عصب', 'A bundle of fibers transmitting impulses between the brain/spinal cord and body', 'Faisceau de fibres transmettant des impulsions entre le cerveau/moelle et le corps', 'حزمة من الألياف تنقل النبضات بين الدماغ/الحبل الشوكي والجسم', '', '', '', 'Anatomie', 'Neurologie', 'The nerve is the bundle of fibers transmitting impulses between the brain/spinal cord and body.', 'La nerf est faisceau de fibres transmettant des impulsions entre le cerveau/moelle et le corps.', 'عصب هو حزمة من الألياف تنقل النبضات بين الدماغ/الحبل الشوكي والجسم.', '/nɜːrv/'),
(220, 'Brachial plexus', 'Plexus brachial', 'الضفيرة العضدية', 'A network of nerves supplying the upper limb', 'Réseau de nerfs alimentant le membre supérieur', 'شبكة من الأعصاب تزود الطرف العلوي', '', '', '', 'Anatomie', 'Neurologie', 'The brachial plexus is the network of nerves supplying the upper limb.', 'La plexus brachial est réseau de nerfs alimentant le membre supérieur.', 'الضفيرة العضدية هو شبكة من الأعصاب تزود الطرف العلوي.', '/ˈbreɪkiəl ˈplɛksəs/'),
(221, 'Lumbar plexus', 'Plexus lombaire', 'الضفيرة القطنية', 'A network of nerves in the lower back supplying the lower limb', 'Réseau de nerfs dans le bas du dos alimentant le membre inférieur', 'شبكة أعصاب في أسفل الظهر تزود الطرف السفلي', '', '', '', 'Anatomie', 'Neurologie', 'The lumbar plexus is the network of nerves in the lower back supplying the lower limb.', 'La plexus lombaire est réseau de nerfs dans le bas du dos alimentant le membre inférieur.', 'الضفيرة القطنية هو شبكة أعصاب في أسفل الظهر تزود الطرف السفلي.', '/ˈlʌmbɑːr ˈplɛksəs/'),
(222, 'Organ', 'Organe', 'عضو', 'A structure made of two or more tissues performing a specific function.', 'Structure formée d''au moins deux tissus assurant une fonction déterminée.', 'بنية مكونة من نسيجين أو أكثر تؤدي وظيفة محددة.', 'Greek: organon — ''instrument / tool''', 'Organs with endocrine and exocrine functions (pancreas, liver) are termed mixed glands.', '', 'Anatomie', 'Organes', 'The heart and liver are organs.', 'Le cœur et le foie sont des organes.', 'القلب والكبد عضوان.', '/ˈɔːr.ɡən/'),
(223, 'Body cavity', 'Cavité corporelle', 'تجويف الجسم', 'A space within the body that houses and protects internal organs.', 'Espace intérieur du corps abritant et protégeant les organes internes.', 'فضاء داخل الجسم يحتوي الأعضاء الداخلية ويحميها.', '', 'Cavities lined by serous membranes reduce friction during organ movement.', '', 'Anatomie', 'Organes', 'The main body cavities are the cranial, thoracic and abdominopelvic cavities.', 'Les principales cavités sont les cavités crânienne, thoracique et abdominopelvienne.', 'التجاويف الرئيسية هي التجويف القحفي والصدري والبطني الحوضي.', '/ˈbɒd.i ˈkæv.ə.ti/'),
(224, 'Cranial cavity', 'Cavité crânienne', 'التجويف القحفي', 'The bony space enclosing the brain, formed by the cranial bones.', 'Espace osseux renfermant le cerveau, formé par les os du crâne.', 'فضاء عظمي يحوي الدماغ، تتشكل من عظام الجمجمة.', 'Greek: κρανίον (kraníon) — ''Skull / Cranium''', 'Rise in intracranial pressure within this fixed space causes Cushing''s triad (bradycardia, hypertension, irregular breathing).', '', 'Anatomie', 'Organes', 'The cranial cavity is lined by the meninges.', 'La cavité crânienne est tapissée par les méninges.', 'يبطن التجويف القحفي السحايا.', '/ˈkreɪ.ni.əl ˈkæv.ə.ti/'),
(225, 'Vertebral canal', 'Canal vertébral', 'القناة الفقرية', 'The bony canal formed by the stacked vertebral foramina, housing the spinal cord.', 'Canal osseux formé par les trous vertébraux empilés, contenant la moelle épinière.', 'قناة عظمية تتكون من ثقوب الفقرات المتراصة، تحتوي الحبل الشوكي.', '', 'Spinal stenosis of this canal compresses the cord or nerve roots, causing neurogenic claudication.', '', 'Anatomie', 'Organes', 'The vertebral canal extends from the foramen magnum to the sacrum.', 'Le canal vertébral s''étend du foramen magnum au sacrum.', 'تمتد القناة الفقرية من الثقبة العظمى إلى العجز.', '/ˈvɜːr.tə.brəl kəˈnæl/'),
(226, 'Thoracic cavity', 'Cavité thoracique', 'التجويف الصدري', 'The chamber of the body between the neck and the diaphragm, containing the heart and lungs.', 'Cavité du corps entre le cou et le diaphragme, contenant le cœur et les poumons.', 'تجويف في الجسم بين الرقبة والحجاب الحاجز، يحتوي القلب والرئتين.', 'Greek: θώραξ (thōrax) — ''Chest / Thorax''', 'Divided into two pleural cavities and the central mediastinum by the pleural membranes.', '', 'Anatomie', 'Organes', 'The thoracic cavity is protected by the rib cage.', 'La cavité thoracique est protégée par la cage thoracique.', 'يحمي التجويف الصدري القفص الصدري.', '/θɔːˈræs.ɪk ˈkæv.ə.ti/'),
(227, 'Abdominal cavity', 'Cavité abdominale', 'التجويف البطني', 'The large cavity below the diaphragm containing the digestive organs.', 'Grande cavité sous le diaphragme contenant les organes digestifs.', 'تجويف كبير أسفل الحجاب الحاجز يحتوي الأعضاء الهضمية.', 'Latin: abdomen — ''Abdomen / Belly''', 'Together with the pelvic cavity it forms the abdominopelvic cavity; its quadrants guide clinical examination.', '', 'Anatomie', 'Organes', 'The abdominal cavity is lined by the peritoneum.', 'La cavité abdominale est tapissée par le péritoine.', 'يبطن التجويف البطني البريتوان.', '/æbˈdɒm.ɪ.nəl ˈkæv.ə.ti/'),
(228, 'Pelvic cavity', 'Cavité pelvienne', 'التجويف الحوضي', 'The lower part of the abdominopelvic cavity, containing the bladder and reproductive organs.', 'Partie inférieure de la cavité abdominopelvienne, contenant la vessie et les organes reproducteurs.', 'الجزء السفلي من التجويف البطني الحوضي، يحتوي المثانة والأعضاء التناسلية.', '', 'The true (lesser) pelvis is the narrow segment below the pelvic brim; its dimensions are critical in obstetrics.', '', 'Anatomie', 'Organes', 'The pelvic cavity is bounded by the pelvic bones.', 'La cavité pelvienne est limitée par les os du bassin.', 'يحد التجويف الحوضي عظام الحوض.', '/ˈpel.vɪk ˈkæv.ə.ti/'),
(229, 'Serous membrane', 'Membrane séreuse', 'الغشاء المصلي', 'Smooth membrane that lines closed body cavities and covers their organs.', 'Membrane lisse tapissant les cavités closes du corps et recouvrant leurs organes.', 'غشاء أملس يبطن تجاويف الجسم المغلقة ويغطي أعضاءها.', '', 'Composed of a parietal layer lining the cavity wall and a visceral layer covering the organ.', '', 'Anatomie', 'Organes', 'Serous membranes secrete a lubricating fluid.', 'Les membranes séreuses sécrètent un liquide lubrifiant.', 'تفرز الأغشية المصلية سائلاً مزلقاً.', '/ˈsɪr.əs ˈmem.breɪn/'),
(230, 'Pleura', 'Plèvre', 'الجنب', 'The serous membrane surrounding the lungs and lining the thoracic cavity.', 'La membrane séreuse entourant les poumons et tapissant la cavité thoracique.', 'الغشاء المصلي الذي يحيط بالرئتين ويبطن التجويف الصدري.', 'Greek: pleura — ''side / rib''', 'Air in the pleural space (pneumothorax) abolishes breath sounds and causes lung collapse.', '', 'Anatomie', 'Organes', 'Each lung is covered by its own pleura.', 'Chaque poumon est recouvert de sa propre plèvre.', 'تغطى كل رئة بغشاء الجنب الخاص بها.', '/ˈplʊr.ə/'),
(231, 'Peritoneum', 'Péritoine', 'البريتوان', 'The serous membrane lining the abdominal cavity and covering its organs.', 'La membrane séreuse tapissant la cavité abdominale et recouvrant ses organes.', 'الغشاء المصلي الذي يبطن التجويف البطني ويغطي أعضاءه.', 'Greek: peritonaion — ''stretched around''', 'Peritonitis causes guarding and rebound tenderness; dialysis uses the peritoneum as a dialyzing membrane.', '', 'Anatomie', 'Organes', 'The peritoneum forms the mesentery and omentum.', 'Le péritoine forme le mésentère et l''épiploon.', 'يكون البريتوان المساريقا والثرب.', '/ˌper.ɪ.təˈniː.əm/'),
(232, 'Mesentery', 'Mésentère', 'المساريقا', 'Double fold of peritoneum attaching the intestine to the posterior abdominal wall.', 'Double repli du péritoine attachant l''intestin à la paroi abdominale postérieure.', 'ثنية مزدوجة من البريتوان تربط الأمعاء بالجدار البطني الخلفي.', 'Greek: mesos (''middle'') + enteron (''intestine'')', 'Now regarded as a single continuous organ; mesenteric lymphadenitis can mimic appendicitis.', '', 'Anatomie', 'Organes', 'The mesentery carries the blood vessels of the intestine.', 'Le mésentère porte les vaisseaux sanguins de l''intestin.', 'تحمل المساريقا الأوعية الدموية للأمعاء.', '/ˈmes.ən.ter.i/'),
(233, 'Omentum', 'Épiploon', 'الثرب', 'Folds of peritoneum draping over the abdominal organs, rich in fat.', 'Replis du péritoine recouvrant les organes abdominaux, riches en graisse.', 'ثنيات من البريتوان تغطي الأعضاء البطنية، غنية بالدهون.', 'Latin: omentum — ''covering / membrane''', 'The greater omentum migrates to wall off sources of infection, earning the name ''policeman of the abdomen''.', '', 'Anatomie', 'Organes', 'The greater omentum covers most of the intestines.', 'Le grand épiploon recouvre la majeure partie de l''intestin.', 'يغطي الثرب الكبير معظم الأمعاء.', '/oʊˈmen.təm/'),
(234, 'Gland', 'Glande', 'غدة', 'An organ that synthesizes and releases substances such as hormones or secretions.', 'Organe qui synthétise et libère des substances comme les hormones ou les sécrétions.', 'عضو يصنع ويفرز مواد مثل الهرمونات أو الإفرازات.', 'Latin: glans — ''acorn''', 'Mixed glands such as the pancreas and liver possess both endocrine and exocrine functions.', '', 'Anatomie', 'Organes', 'Glands are classified as endocrine or exocrine.', 'Les glandes sont classées en endocrines et exocrines.', 'تُصنّف الغدد إلى صماء وقنوية.', '/ɡlænd/'),
(235, 'Endocrine gland', 'Glande endocrine', 'الغدة الصماء', 'A ductless gland that releases hormones directly into the bloodstream.', 'Glande sans canal qui libère ses hormones directement dans le sang.', 'غدة عديمة القناة تفرز هرموناتها مباشرة في مجرى الدم.', 'Greek: endon (''within'') + krinein (''to separate / release'')', 'Hypothalamus and pituitary form the master control axis of the endocrine system.', '', 'Anatomie', 'Organes', 'The thyroid is an endocrine gland.', 'La thyroïde est une glande endocrine.', 'الغدة الدرقية غدة صماء.', '/ˈen.də.krɪn ɡlænd/'),
(236, 'Exocrine gland', 'Glande exocrine', 'الغدة القنوية (الإفرازية)', 'A gland that releases its secretions through a duct to an epithelial surface.', 'Glande qui libère ses sécrétions par un canal vers une surface épithéliale.', 'غدة تفرز إفرازاتها عبر قناة إلى سطح طلائي.', 'Greek: exo (''outside'') + krinein (''to release'')', 'Cystic fibrosis affects exocrine glands, producing thick secretions that obstruct ducts.', '', 'Anatomie', 'Organes', 'Salivary and sweat glands are exocrine glands.', 'Les glandes salivaires et sudorales sont des glandes exocrines.', 'الغدد اللعابية والعرقية غدد قنوية.', '/ˈek.sə.krɪn ɡlænd/'),
(237, 'Tissue', 'Tissu', 'نسيج', 'A group of similar cells performing a common function.', 'Un ensemble de cellules semblables assurant une fonction commune.', 'مجموعة من الخلايا المتشابهة تؤدي وظيفة مشتركة.', 'Latin: texere — ''to weave''', 'The four types: epithelial, connective, muscular and nervous tissue.', '', 'Anatomie', 'Organes', 'There are four basic tissue types in the body.', 'Il existe quatre types de tissus de base dans le corps.', 'يوجد أربعة أنواع أساسية من الأنسجة في الجسم.', '/ˈtɪʃ.uː/'),
(238, 'Membrane', 'Membrane', 'غشاء', 'A thin sheet of tissue that covers, lines or separates structures.', 'Une fine feuille de tissu qui recouvre, tapisse ou sépare des structures.', 'صفيحة رقيقة من النسيج تغطي أو تبطن أو تفصل بين البنى.', 'Latin: membrana — ''skin / parchment''', 'Mucous, serous, synovial and cutaneous membranes are the main membrane categories.', '', 'Anatomie', 'Organes', 'Mucous and serous membranes line the body cavities.', 'Les muqueuses et les membranes séreuses tapissent les cavités du corps.', 'تبطن الأغشية المخاطية والمصلية تجاويف الجسم.', '/ˈmem.breɪn/'),
(239, 'Mucous membrane', 'Muqueuse', 'الغشاء المخاطي', 'A membrane lining body tracts that open to the exterior, secreting mucus.', 'Membrane tapissant les conduits ouverts vers l''extérieur, sécrétant du mucus.', 'غشاء يبطن القنوات المفتوحة على الخارج، يفرز المخاط.', 'Latin: mucus — ''slime / nasal discharge''', 'The most common sites of squamous cell carcinoma of the head and neck, often linked to tobacco and alcohol.', '', 'Anatomie', 'Organes', 'The mucous membrane lines the digestive tract.', 'La muqueuse tapisse le tube digestif.', 'يبطن الغشاء المخاطي القناة الهضمية.', '/ˈmjuː.kəs ˈmem.breɪn/'),
(240, 'Organ system', 'Système d''organes', 'جهاز عضوي', 'A group of organs working together to perform a complex function.', 'Un ensemble d''organes travaillant ensemble à une fonction complexe.', 'مجموعة أعضاء تعمل معاً لأداء وظيفة معقدة.', '', 'The eleven classical organ systems include integumentary, skeletal, muscular, nervous, endocrine, cardiovascular, lymphatic, respiratory, digestive, urinary and reproductive.', '', 'Anatomie', 'Organes', 'The digestive system is an organ system.', 'Le système digestif est un système d''organes.', 'الجهاز الهضمي جهاز عضوي.', '/ˈɔːr.ɡən ˈsɪs.təm/'),
(241, 'Reticuloendothelial system', 'Système réticulo-endothélial', 'الجهاز الشبكي البطاني', 'A diffuse network of phagocytic cells spread throughout the body''s organs.', 'Réseau diffus de cellules phagocytaires réparties dans les organes du corps.', 'شبكة منتشرة من الخلايا البلعمية موزعة في أعضاء الجسم.', '', 'Kupffer cells of the liver and splenic macrophages clear aged erythrocytes and particulate matter.', '', 'Anatomie', 'Organes', 'The spleen and liver belong to the reticuloendothelial system.', 'La rate et le foie appartiennent au système réticulo-endothélial.', 'ينتمي الطحال والكبد إلى الجهاز الشبكي البطاني.', '/rɪˌtɪk.jə.loʊˌen.doʊˈθiː.li.əl ˈsɪs.təm/'),
(242, 'Spleen', 'Rate', 'الطحال', 'An organ filtering blood and recycling old red blood cells', 'Organe filtrant le sang et recyclant les vieux globules rouges', 'عضو يرشح الدم ويعيد تدوير كريات الدم الحمراء القديمة', '', '', '', 'Anatomie', 'Organes', 'The spleen is the organ filtering blood and recycling old red blood cells.', 'La rate est organe filtrant le sang et recyclant les vieux globules rouges.', 'الطحال هو عضو يرشح الدم ويعيد تدوير كريات الدم الحمراء القديمة.', '/spliːn/'),
(243, 'Thyroid gland', 'Glande thyroïde', 'الغدة الدرقية', 'A butterfly-shaped endocrine gland in the neck regulating metabolism', 'Glande endocrine en forme de papillon dans le cou régulant le métabolisme', 'غدة صماء على شكل فراشة في العنق تنظم الأيض', 'Greek: θυρεοειδής (thyreoeides) — ''Thyroid''', '', '', 'Anatomie', 'Organes', 'The thyroid gland is the butterfly-shaped endocrine gland in the neck regulating metabolism.', 'La glande thyroïde est glande endocrine en forme de papillon dans le cou régulant le métabolisme.', 'الغدة الدرقية هو غدة صماء على شكل فراشة في العنق تنظم الأيض.', '/ˈθaɪrɔɪd ɡlænd/'),
(244, 'Adrenal gland', 'Glande surrénale', 'الغدة الكظرية', 'An endocrine gland located on top of each kidney', 'Glande endocrine située au-dessus de chaque rein', 'غدة صماء تقع فوق كل كلية', 'Latin: ad (sur) + renes (reins) — ''Adrenal glands''', '', '', 'Anatomie', 'Organes', 'The adrenal gland is the endocrine gland located on top of each kidney.', 'La glande surrénale est glande endocrine située au-dessus de chaque rein.', 'الغدة الكظرية هو غدة صماء تقع فوق كل كلية.', '/əˈdriːnəl ɡlænd/'),
(245, 'Skull', 'Crâne', 'الجمجمة', 'The bony structure that forms the head and protects the brain.', 'Structure osseuse formant la tête et protégeant le cerveau.', 'الهيكل العظمي الذي يشكل الرأس ويحمي الدماغ.', 'Ancient Greek: κρανίον (kranion) — ''helmet'' / ''head-case''', 'Composed of neurocranium (8 bones) protecting the encephalon and viscerocranium (14 bones) forming the facial skeleton.', 'Cranial vault bones: ''STEP OF 8'' (Sphenoid, Temporal, Ethmoid, Parietal, Occipital, Frontal).', 'Anatomie', 'Ostéologie', 'The skull consists of 22 bones.', 'Le crâne est composé de 22 os.', 'تتكون الجمجمة من 22 عظمة.', '/skʌl/'),
(246, 'Frontal bone', 'Os frontal', 'العظم الجبهي', 'Bone forming the forehead and the roof of the eye sockets.', 'Os formant le front et le toit des orbites.', 'عظمة تشكل الجبهة وسقف محجري العينين.', 'Latin: frons — ''forehead''', 'Contains the paired paranasal frontal sinuses and supraorbital notch transmiting the supraorbital nerve (CN V1).', '', 'Anatomie', 'Ostéologie', 'The frontal bone contains the frontal sinuses.', 'L''os frontal contient les sinus frontaux.', 'يحتوي العظم الجبهي على الجيوب الجبهية.', '/ˈfrʌn.təl boʊn/'),
(247, 'Parietal bone', 'Os pariétal', 'العظم الجداري', 'Paired bones forming the sides and roof of the cranium.', 'Os pairs formant les côtés et le toit du crâne.', 'عظام مزدوجة تشكل جانبي الجمجمة وسقفها.', 'Latin: parietalis — from paries (''wall'')', 'The internal surface carries deep grooves for the middle meningeal artery branches; rupture leads to epidural hematoma.', '', 'Anatomie', 'Ostéologie', 'The parietal bones meet at the sagittal suture.', 'Les os pariétaux se rejoignent à la suture sagittale.', 'تلتقي العظام الجدارية عند الدرز السهمي.', '/pəˈraɪ.ə.təl boʊn/'),
(248, 'Temporal bone', 'Os temporal', 'العظم الصدغي', 'Bone forming the lateral skull and housing the ear structures.', 'Os formant le côté du crâne et contenant les structures de l''oreille.', 'عظمة تشكل جانب الجمجمة وتحتوي على هياكل الأذن.', 'Latin: tempus — ''time'' (where gray hair first appears with aging)', 'Houses the middle and inner ear (petrous part) and the facial nerve (CN VII) canal.', '', 'Anatomie', 'Ostéologie', 'The temporal bone contains the internal auditory canal.', 'L''os temporal contient le canal auditif interne.', 'يحتوي العظم الصدغي على القناة السمعية الداخلية.', '/ˈtem.pər.əl boʊn/'),
(249, 'Occipital bone', 'Os occipital', 'العظم القذالي', 'Bone forming the back and base of the skull.', 'Os formant l''arrière et la base du crâne.', 'عظمة تشكل خلف الجمجمة وقاعدتها.', 'Latin: ob (''behind'') + caput (''head'')', 'Features the foramen magnum through which the medulla oblongata continues into the spinal cord.', '', 'Anatomie', 'Ostéologie', 'The foramen magnum is located in the occipital bone.', 'Le foramen magnum est situé dans l''os occipital.', 'يقع الثقب الأعظم في العظم القذالي.', '/ɒkˈsɪp.ɪ.təl boʊn/'),
(250, 'Sphenoid bone', 'Os sphénoïde', 'العظم الوتدي', 'Butterfly-shaped bone at the base of the skull.', 'Os en forme de papillon à la base du crâne.', 'عظمة على شكل فراشة في قاعدة الجمجمة.', 'Greek: sphenoeides — ''wedge-like''', 'The sella turcica (''Turkish saddle'') in the central body houses the pituitary gland (hypophysis).', '', 'Anatomie', 'Ostéologie', 'The sphenoid bone contains the sella turcica.', 'L''os sphénoïde contient la selle turcique.', 'يحتوي العظم الوتدي على السرج التركي.', '/ˈsfiː.nɔɪd boʊn/'),
(251, 'Ethmoid bone', 'Os ethmoïde', 'العظم الغربالي', 'Delicate bone forming part of the nasal cavity and eye socket.', 'Os délicat formant une partie de la cavité nasale et de l''orbite.', 'عظمة رقيقة تشكل جزءاً من التجويف الأنفي ومحجر العين.', 'Greek: ethmos (''sieve'') + eidos (''form'')', 'Fracture of the cribriform plate can tear meninges leading to cerebrospinal fluid rhinorrhea and anosmia.', '', 'Anatomie', 'Ostéologie', 'The cribriform plate is part of the ethmoid bone.', 'La lame criblée fait partie de l''os ethmoïde.', 'الصفيحة المصفوية جزء من العظم الغربالي.', '/ˈeθ.mɔɪd boʊn/'),
(252, 'Mandible', 'Mandibule', 'الفك السفلي', 'The lower jaw bone, the only movable bone of the skull.', 'L''os de la mâchoire inférieure, le seul os mobile du crâne.', 'عظمة الفك السفلي، العظمة المتحركة الوحيدة في الجمجمة.', 'Latin: mandere — ''to chew''', 'Forms the temporomandibular joint (TMJ); the mandibular canal carries the inferior alveolar nerve (targeted in dental blocks).', '', 'Anatomie', 'Ostéologie', 'The mandible articulates with the temporal bone.', 'La mandibule s''articule avec l''os temporal.', 'يتمفصل الفك السفلي مع العظم الصدغي.', '/ˈmæn.dɪ.bəl/'),
(253, 'Maxilla', 'Maxillaire', 'الفك العلوي', 'The upper jaw bone, forming the hard palate and part of the face.', 'L''os de la mâchoire supérieure, formant le palais dur.', 'عظمة الفك العلوي، تشكل الحنك الصلب وجزءاً من الوجه.', 'Latin: maxilla — ''jawbone''', 'Contains the maxillary sinus (Highmore antrum), the largest paranasal air sinus prone to odontogenic sinusitis.', '', 'Anatomie', 'Ostéologie', 'The maxilla bears the upper teeth.', 'Le maxillaire porte les dents supérieures.', 'يحمل الفك العلوي الأسنان العلوية.', '/mækˈsɪl.ə/'),
(254, 'Zygomatic bone', 'Os zygomatique', 'العظم الوجني', 'The cheekbone, forming the prominence of the cheek.', 'L''os de la pommette, formant la saillie de la joue.', 'عظمة الخد، تشكل بروز الخد.', 'Greek: ζύγωμα (zygoma) — ''yoke'' or ''bar''', 'Forms the zygomatic arch with the temporal process; tripod fractures occur in facial trauma requiring reduction.', '', 'Anatomie', 'Ostéologie', 'The zygomatic bone forms the cheekbone prominence.', 'L''os zygomatique forme la proéminence de la pommette.', 'يشكل العظم الوجني بروز عظمة الخد.', '/ˌzaɪ.ɡəˈmæt.ɪk boʊn/'),
(255, 'Vertebral column', 'Colonne vertébrale', 'العمود الفقري', 'The series of 33 vertebrae forming the backbone of the body.', 'La série de 33 vertèbres formant le rachis.', 'سلسلة من 33 فقرة تشكل العمود الفقري للجسم.', 'Latin: vertere — ''to turn''', 'Has physiological sagittal curves: cervical lordosis, thoracic kyphosis, lumbar lordosis, and sacral kyphosis.', '', 'Anatomie', 'Ostéologie', 'The vertebral column protects the spinal cord.', 'La colonne vertébrale protège la moelle épinière.', 'يحمي العمود الفقري الحبل الشوكي.', '/ˌvɜː.tɪ.brəl ˈkɒl.əm/'),
(256, 'Cervical vertebra', 'Vertèbre cervicale', 'الفقرة العنقية', 'One of the 7 vertebrae of the neck region (C1-C7).', 'Une des 7 vertèbres de la région cervicale (C1-C7).', 'إحدى فقرات الرقبة السبع (C1-C7).', 'Latin: cervix — ''neck''', 'Distinguished by transverse foramina transmitting vertebral arteries and bifid spinous processes (C2-C6).', '', 'Anatomie', 'Ostéologie', 'There are 7 cervical vertebrae in the human neck.', 'Il y a 7 vertèbres cervicales dans le cou humain.', 'يوجد 7 فقرات عنقية في رقبة الإنسان.', '/ˈsɜː.vɪ.kəl ˈvɜː.tɪ.brə/'),
(257, 'Atlas (C1)', 'Atlas (C1)', 'الأطلس (C1)', 'The first cervical vertebra that supports the skull.', 'La première vertèbre cervicale qui supporte le crâne.', 'الفقرة العنقية الأولى التي تدعم الجمجمة.', 'Greek Mythology: Atlas, Titan holding up the celestial spheres', 'Has no vertebral body or spinous process; consists of anterior and posterior arches with lateral masses.', '', 'Anatomie', 'Ostéologie', 'The atlas supports the skull and allows nodding.', 'L''atlas supporte le crâne et permet le hochement de tête.', 'يدعم الأطلس الجمجمة ويسمح بحركة الإيماء.', '/ˈæt.ləs/'),
(258, 'Axis (C2)', 'Axis (C2)', 'المحور (C2)', 'The second cervical vertebra with the odontoid process (dens).', 'La deuxième vertèbre cervicale avec le processus odontoïde.', 'الفقرة العنقية الثانية ذات النتوء السني.', 'Latin: axis — ''pivot'' or ''axle''', 'The dens (odontoid process) acts as a pivot around which the atlas turns (responsible for ~50% of cervical rotation).', '', 'Anatomie', 'Ostéologie', 'The axis allows rotation of the head.', 'L''axis permet la rotation de la tête.', 'يسمح المحور بدوران الرأس.', '/ˈæk.sɪs/'),
(259, 'Thoracic vertebra', 'Vertèbre thoracique', 'الفقرة الصدرية', 'One of the 12 vertebrae of the chest region (T1-T12).', 'Une des 12 vertèbres de la région thoracique (T1-T12).', 'إحدى الفقرات الصدرية الاثنتا عشرة (T1-T12).', 'Greek: thorax — ''breastplate'' / ''chest''', 'Characterized by costal facets on the vertebral bodies and transverse processes for rib articulation.', '', 'Anatomie', 'Ostéologie', 'Each thoracic vertebra articulates with a pair of ribs.', 'Chaque vertèbre thoracique s''articule avec une paire de côtes.', 'تتمفصل كل فقرة صدرية مع زوج من الأضلاع.', '/θɔːˈræs.ɪk ˈvɜː.tɪ.brə/'),
(260, 'Lumbar vertebra', 'Vertèbre lombaire', 'الفقرة القطنية', 'One of the 5 large vertebrae of the lower back (L1-L5).', 'Une des 5 grandes vertèbres de la région lombaire (L1-L5).', 'إحدى الفقرات القطنية الخمس الكبيرة (L1-L5).', 'Latin: lumbus — ''loin''', 'Have massive kidney-shaped bodies and sturdy quadrangular spinous processes; L4-L5 and L5-S1 are most vulnerable to disc herniation.', '', 'Anatomie', 'Ostéologie', 'Lumbar vertebrae bear most of the body''s weight.', 'Les vertèbres lombaires supportent la majeure partie du poids du corps.', 'تتحمل الفقرات القطنية معظم وزن الجسم.', '/ˈlʌm.bər ˈvɜː.tɪ.brə/'),
(261, 'Sacrum', 'Sacrum', 'العجز', 'A triangular bone formed by 5 fused vertebrae at the base of the spine.', 'Os triangulaire formé de 5 vertèbres fusionnées à la base de la colonne.', 'عظمة مثلثة تتكون من 5 فقرات ملتحمة في قاعدة العمود الفقري.', 'Latin: os sacrum — ''sacred bone'' (believed indestructible in antiquity)', 'Articulates with iliac bones at sacroiliac joints; transmits axial skeletal load directly to the lower extremity.', '', 'Anatomie', 'Ostéologie', 'The sacrum forms the posterior wall of the pelvis.', 'Le sacrum forme la paroi postérieure du bassin.', 'يشكل العجز الجدار الخلفي للحوض.', '/ˈseɪ.krəm/'),
(262, 'Coccyx', 'Coccyx', 'العصعص', 'The tailbone, formed by 3-5 fused vertebrae at the end of the spine.', 'L''os coccygien, formé de 3 à 5 vertèbres fusionnées.', 'عظمة الذيل، تتكون من 3-5 فقرات ملتحمة في نهاية العمود الفقري.', 'Greek: kokkyx — ''cuckoo'' (resembling a cuckoo beak)', 'Serves as an insertion site for the levator ani and gluteus maximus; trauma causes acute coccydynia.', '', 'Anatomie', 'Ostéologie', 'The coccyx serves as an attachment point for muscles.', 'Le coccyx sert de point d''attache pour les muscles.', 'يعمل العصعص كنقطة ارتكاز للعضلات.', '/ˈkɒk.sɪks/'),
(263, 'Intervertebral disc', 'Disque intervertébral', 'القرص الفقري', 'Fibrocartilaginous cushion between adjacent vertebrae.', 'Coussin fibrocartilagineux entre les vertèbres adjacentes.', 'وسادة غضروفية ليفية بين الفقرات المتجاورة.', 'Latin: inter (''between'') + vertebra (''joint'') + discus', 'Composed of outer anulus fibrosus and central jelly-like nucleus pulposus; posterolateral herniation compresses spinal nerve roots.', '', 'Anatomie', 'Ostéologie', 'Intervertebral discs act as shock absorbers.', 'Les disques intervertébraux agissent comme amortisseurs.', 'تعمل الأقراص الفقرية كممتصات للصدمات.', '/ˌɪn.təˈvɜː.tɪ.brəl dɪsk/'),
(264, 'Sternum', 'Sternum', 'عظمة القص', 'Flat bone in the center of the chest connecting the ribs.', 'Os plat au centre de la poitrine reliant les côtes.', 'عظمة مسطحة في مركز الصدر تربط الأضلاع.', 'Greek: στέρνον (sternon) — ''chest'' / ''breast''', 'Sternal angle (Angle of Louis) marks the level of 2nd rib, T4/T5 intervertebral disc, bifurcation of trachea (carina), and aortic arch.', '', 'Anatomie', 'Ostéologie', 'The sternum has three parts: manubrium, body, and xiphoid process.', 'Le sternum a trois parties : manubrium, corps et appendice xiphoïde.', 'لعظمة القص ثلاثة أجزاء: المقبض والجسم والزائدة الخنجرية.', '/ˈstɜː.nəm/'),
(265, 'Rib', 'Côte', 'الضلع', 'Curved bones forming the thoracic cage, 12 pairs in total.', 'Os courbés formant la cage thoracique, 12 paires au total.', 'عظام منحنية تشكل القفص الصدري، 12 زوجاً في المجموع.', 'Old English: ribb / Germanic: ribbja', 'Ribs 1-7 are true (vertebrocostal), 8-10 are false (vertebrochondral), and 11-12 are floating (vertebral). The neurovascular bundle runs in the subcostal groove.', '', 'Anatomie', 'Ostéologie', 'There are 12 pairs of ribs in the human thorax.', 'Il y a 12 paires de côtes dans le thorax humain.', 'يوجد 12 زوجاً من الأضلاع في صدر الإنسان.', '/rɪb/'),
(266, 'Floating rib', 'Côte flottante', 'الضلع العائم', 'The last two pairs of ribs (11-12) not attached to the sternum.', 'Les deux dernières paires de côtes (11-12) non attachées au sternum.', 'آخر زوجين من الأضلاع (11-12) غير المتصلة بعظمة القص.', '', 'Lack anterior cartilage attachment; protect the posterior kidneys and spleen/liver from dorsal blunt trauma.', '', 'Anatomie', 'Ostéologie', 'Floating ribs are not connected to the sternum anteriorly.', 'Les côtes flottantes ne sont pas connectées au sternum en avant.', 'الأضلاع العائمة غير متصلة بعظمة القص من الأمام.', '/ˈfləʊ.tɪŋ rɪb/'),
(267, 'Clavicle', 'Clavicule', 'عظمة الترقوة', 'S-shaped bone connecting the sternum to the shoulder blade.', 'Os en forme de S reliant le sternum à l''omoplate.', 'عظمة على شكل S تربط عظمة القص بلوح الكتف.', 'Latin: clavicula — ''little key''', 'First bone in the human body to begin ossification (in utero) and one of the last to finish (~21-25 years).', '', 'Anatomie', 'Ostéologie', 'The clavicle is the most frequently fractured bone.', 'La clavicule est l''os le plus souvent fracturé.', 'عظمة الترقوة هي الأكثر عرضة للكسر.', '/ˈklæv.ɪ.kəl/'),
(268, 'Scapula', 'Omoplate (Scapula)', 'لوح الكتف', 'Flat triangular bone at the back of the shoulder.', 'Os plat triangulaire situé à l''arrière de l''épaule.', 'عظمة مسطحة مثلثة في خلف الكتف.', 'Latin: scapula — ''shoulder blade'' (from Greek skaptein, to dig)', 'Winged scapula results from injury to the long thoracic nerve (Bell''s nerve), paralyzing serratus anterior.', '', 'Anatomie', 'Ostéologie', 'The scapula connects with the humerus at the glenoid cavity.', 'L''omoplate s''articule avec l''humérus au niveau de la cavité glénoïde.', 'يتمفصل لوح الكتف مع عظمة العضد عند التجويف الحقاني.', '/ˈskæp.jə.lə/'),
(269, 'Humerus', 'Humérus', 'عظمة العضد', 'The long bone of the upper arm.', 'L''os long du bras.', 'العظمة الطويلة في الجزء العلوي من الذراع.', 'Latin: humerus — ''upper arm''', 'Surgical neck fracture injures the axillary nerve; midshaft fracture injures the radial nerve; supracondylar fracture injures the median nerve.', '', 'Anatomie', 'Ostéologie', 'The humerus articulates with the scapula at the shoulder joint.', 'L''humérus s''articule avec l''omoplate au niveau de l''articulation de l''épaule.', 'تتمفصل عظمة العضد مع لوح الكتف عند مفصل الكتف.', '/ˈhjuː.mər.əs/'),
(270, 'Radius', 'Radius', 'عظمة الكعبرة', 'The lateral bone of the forearm, on the thumb side.', 'L''os latéral de l''avant-bras, du côté du pouce.', 'العظمة الجانبية في الساعد، على جانب الإبهام.', 'Latin: radius — ''ray'' / ''spoke of a wheel''', 'Colles'' fracture is a common distal radius fracture with dorsal displacement producing a ''dinner-fork'' deformity.', '', 'Anatomie', 'Ostéologie', 'The radius is the larger of the two forearm bones.', 'Le radius est le plus grand des deux os de l''avant-bras.', 'عظمة الكعبرة هي أكبر عظمتي الساعد.', '/ˈreɪ.di.əs/'),
(271, 'Ulna', 'Ulna (Cubitus)', 'عظمة الزند', 'The medial bone of the forearm, on the little finger side.', 'L''os médial de l''avant-bras, du côté du petit doigt.', 'العظمة الوسطية في الساعد، على جانب الخنصر.', 'Latin: ulna — ''elbow'' / ''forearm''', 'The prominent olecranon process forms the ''point'' of the elbow and receives the triceps brachii tendon.', '', 'Anatomie', 'Ostéologie', 'The olecranon is the bony prominence of the ulna.', 'L''olécrâne est la proéminence osseuse de l''ulna.', 'النتوء الزجي هو البروز العظمي لعظمة الزند.', '/ˈʌl.nə/'),
(272, 'Carpals', 'Os carpiens', 'عظام الرسغ', 'The 8 small bones of the wrist arranged in two rows.', 'Les 8 petits os du poignet disposés en deux rangées.', 'العظام الثماني الصغيرة في الرسغ مرتبة في صفين.', 'Greek: karpos — ''wrist''', 'The scaphoid is most commonly fractured (anatomical snuffbox tenderness); prone to avascular necrosis.', '''Some Lovers Try Positions That They Cannot Handle'' (Scaphoid, Lunate, Triquetrum, Pisiform, Trapezium, Trapezoid, Capitate, Hamate).', 'Anatomie', 'Ostéologie', 'There are 8 carpal bones forming the wrist.', 'Il y a 8 os carpiens formant le poignet.', 'يوجد 8 عظام رسغية تشكل الرسغ.', '/ˈkɑː.pəlz/'),
(273, 'Metacarpals', 'Os métacarpiens', 'عظام المشط', 'The 5 bones forming the palm of the hand.', 'Les 5 os formant la paume de la main.', 'العظام الخمس التي تشكل راحة اليد.', 'Greek: meta (''after'') + karpos (''wrist'')', 'Boxer''s fracture is a fracture of the neck of the 5th (or 4th) metacarpal, typically from a punch.', '', 'Anatomie', 'Ostéologie', 'The metacarpals connect the wrist to the fingers.', 'Les métacarpiens relient le poignet aux doigts.', 'تربط عظام المشط الرسغ بالأصابع.', '/ˌmet.əˈkɑː.pəlz/'),
(274, 'Phalanges (hand)', 'Phalanges (main)', 'السلاميات (اليد)', 'The 14 bones of the fingers, 3 in each finger except the thumb (2).', 'Les 14 os des doigts, 3 par doigt sauf le pouce (2).', 'العظام الأربع عشرة للأصابع، 3 في كل إصبع ما عدا الإبهام (2).', 'Greek: phalanx — ''battle array of soldiers in close formation''', 'Arranged as proximal, middle, and distal phalanges; pollex (thumb) only has proximal and distal.', '', 'Anatomie', 'Ostéologie', 'Each finger has three phalanges except the thumb.', 'Chaque doigt a trois phalanges sauf le pouce.', 'كل إصبع لديه ثلاث سلاميات ما عدا الإبهام.', '/fəˈlæn.dʒiːz/'),
(275, 'Pelvis', 'Bassin (Pelvis)', 'الحوض', 'Bony structure at the base of the spine connecting the spine to the legs.', 'Structure osseuse à la base de la colonne reliant la colonne aux jambes.', 'البنية العظمية في قاعدة العمود الفقري تربط العمود بالساقين.', 'Latin: pelvis — ''basin''', 'Formed by two hip (coxal) bones, the sacrum, and coccyx; the female pelvis is broader with a wider pubic angle (>90°) for childbirth.', '', 'Anatomie', 'Ostéologie', 'The pelvis protects the pelvic organs.', 'Le bassin protège les organes pelviens.', 'يحمي الحوض الأعضاء الحوضية.', '/ˈpel.vɪs/'),
(276, 'Ilium', 'Ilion', 'عظمة الحرقفة', 'The largest and uppermost of the three bones forming the hip bone.', 'Le plus grand et le plus supérieur des trois os formant l''os coxal.', 'أكبر وأعلى العظام الثلاث المكونة لعظمة الورك.', 'Latin: ilia — ''flanks'' / ''groin''', 'The anterior superior iliac spine (ASIS) is a landmark for measuring limb length and for the inguinal ligament.', '', 'Anatomie', 'Ostéologie', 'The iliac crest is the upper border of the ilium.', 'La crête iliaque est le bord supérieur de l''ilion.', 'القمة الحرقفية هي الحد العلوي لعظمة الحرقفة.', '/ˈɪl.i.əm/'),
(277, 'Ischium', 'Ischion', 'عظمة الإسك', 'The lower and posterior part of the hip bone.', 'La partie inférieure et postérieure de l''os coxal.', 'الجزء السفلي والخلفي من عظمة الورك.', 'Greek: ischion — ''hip joint''', 'The ischial spine serves as a reference point in obstetrics during vaginal delivery to gauge fetal head descent (stations -5 to +5).', '', 'Anatomie', 'Ostéologie', 'We sit on the ischial tuberosities.', 'Nous nous asseyons sur les tubérosités ischiatiques.', 'نجلس على الحدبات الإسكية.', '/ˈɪs.ki.əm/'),
(278, 'Pubis', 'Pubis', 'عظمة العانة', 'The anterior and inferior part of the hip bone.', 'La partie antérieure et inférieure de l''os coxal.', 'الجزء الأمامي والسفلي من عظمة الورك.', 'Latin: os pubis — ''bone of puberty''', 'The symphysis pubis widens slightly in late pregnancy under the influence of the hormone relaxin.', '', 'Anatomie', 'Ostéologie', 'The two pubic bones meet at the pubic symphysis.', 'Les deux pubis se rejoignent à la symphyse pubienne.', 'تلتقي عظمتا العانة عند ارتفاق العانة.', '/ˈpjuː.bɪs/'),
(279, 'Femur', 'Fémur', 'عظمة الفخذ', 'The longest and strongest bone in the human body, located in the thigh.', 'L''os le plus long et le plus fort du corps humain, dans la cuisse.', 'أطول وأقوى عظمة في جسم الإنسان، تقع في الفخذ.', 'Latin: femur — ''thigh''', 'Femoral neck fractures in elderly osteoporotic patients carry high risk of avascular necrosis due to medial circumflex artery damage.', '', 'Anatomie', 'Ostéologie', 'The femur connects the hip to the knee joint.', 'Le fémur relie la hanche au genou.', 'تربط عظمة الفخذ الورك بمفصل الركبة.', '/ˈfiː.mər/'),
(280, 'Patella', 'Rotule (Patella)', 'الرضفة', 'The kneecap, a sesamoid bone embedded in the quadriceps tendon.', 'La rotule, os sésamoïde dans le tendon du quadriceps.', 'عظمة الركبة، عظمة سمسمية مدمجة في وتر العضلة الرباعية.', 'Latin: patella — ''small plate'' or ''shallow dish''', 'Increases quadriceps mechanical lever arm by up to 30%; patellar reflex tests L3-L4 spinal nerve roots.', '', 'Anatomie', 'Ostéologie', 'The patella protects the knee joint.', 'La rotule protège l''articulation du genou.', 'تحمي الرضفة مفصل الركبة.', '/pəˈtel.ə/'),
(281, 'Tibia', 'Tibia', 'عظمة الظنبوب (القصبة)', 'The larger of the two lower leg bones, bearing most of the body weight.', 'Le plus grand des deux os de la jambe, supportant l''essentiel du poids.', 'أكبر عظمتي الساق، تتحمل معظم وزن الجسم.', 'Latin: tibia — ''shinbone'' / ''pipe'' / ''flute''', 'Tibial tuberosity receives the patellar ligament; traction apophysitis here causes Osgood-Schlatter disease in adolescents.', '', 'Anatomie', 'Ostéologie', 'The tibia is the main weight-bearing bone of the lower leg.', 'Le tibia est le principal os porteur de la jambe.', 'عظمة الظنبوب هي العظمة الرئيسية لحمل الوزن في الساق.', '/ˈtɪb.i.ə/'),
(282, 'Fibula', 'Fibula (Péroné)', 'عظمة الشظية', 'The slender lateral bone of the lower leg.', 'L''os fin et latéral de la jambe.', 'العظمة الجانبية الرفيعة في الساق.', 'Latin: fibula — ''clasp'' or ''buckle''', 'The neck of the fibula is in direct contact with the common peroneal (fibular) nerve; injury produces foot drop.', '', 'Anatomie', 'Ostéologie', 'The fibula does not bear significant body weight.', 'La fibula ne supporte pas de poids corporel significatif.', 'لا تتحمل عظمة الشظية وزناً كبيراً للجسم.', '/ˈfɪb.jə.lə/'),
(283, 'Tarsals', 'Os tarsiens', 'عظام الكاحل', 'The 7 bones of the ankle and proximal foot.', 'Les 7 os de la cheville et de la partie proximale du pied.', 'العظام السبع للكاحل والجزء القريب من القدم.', 'Greek: tarsos — ''flat surface'' / ''wicker basket''', '', '7 Tarsals: ''Tiger Cubs Need MILC'' (Talus, Calcaneus, Navicular, Medial, Intermediate, Lateral cuneiforms, Cuboid).', 'Anatomie', 'Ostéologie', 'The calcaneus is the largest tarsal bone.', 'Le calcanéum est le plus grand des os tarsiens.', 'عظمة الكعب هي أكبر عظام الكاحل.', '/ˈtɑː.səlz/'),
(284, 'Calcaneus', 'Calcanéum', 'عظمة الكعب', 'The heel bone, the largest bone in the foot.', 'L''os du talon, le plus grand os du pied.', 'عظمة الكعب، أكبر عظمة في القدم.', 'Latin: calx — ''heel''', 'Sustains vertical compressive load; Lover''s fracture (calcaneal fracture from jumping from heights) often coexists with lumbar burst fractures.', '', 'Anatomie', 'Ostéologie', 'The Achilles tendon attaches to the calcaneus.', 'Le tendon d''Achille s''attache au calcanéum.', 'يرتبط وتر أخيل بعظمة الكعب.', '/kælˈkeɪ.ni.əs/'),
(285, 'Metatarsals', 'Os métatarsiens', 'عظام مشط القدم', 'The 5 bones forming the middle part of the foot.', 'Les 5 os formant la partie médiane du pied.', 'العظام الخمس التي تشكل الجزء الأوسط من القدم.', 'Greek: meta (''beyond'') + tarsos (''ankle'')', 'March fracture (stress fracture of 2nd or 3rd metatarsal shaft) occurs commonly in military recruits and runners.', '', 'Anatomie', 'Ostéologie', 'Metatarsal fractures are common in athletes.', 'Les fractures des métatarses sont fréquentes chez les sportifs.', 'كسور عظام مشط القدم شائعة بين الرياضيين.', '/ˌmet.əˈtɑː.səlz/'),
(286, 'Phalanges (foot)', 'Phalanges (pied)', 'سلاميات القدم', 'The 14 bones of the toes, same arrangement as the fingers.', 'Les 14 os des orteils, même disposition que les doigts.', 'عظام أصابع القدم الأربع عشرة، بنفس ترتيب أصابع اليد.', 'Greek: phalanx — ''battle line formation''', 'Hallux (big toe) has only proximal and distal phalanges; toes 2-5 have proximal, middle, and distal phalanges.', '', 'Anatomie', 'Ostéologie', 'The big toe has only two phalanges.', 'Le gros orteil n''a que deux phalanges.', 'إصبع القدم الكبير لديه سلاميتان فقط.', '/fəˈlæn.dʒiːz/'),
(287, 'Diaphysis', 'Diaphyse', 'جسم العظم (الدايافيز)', 'The shaft or central portion of a long bone.', 'La tige ou partie centrale d''un os long.', 'جسم أو الجزء المركزي من العظمة الطويلة.', 'Greek: dia (''between'') + phyein (''to grow'')', 'Composed predominantly of dense cortical (compact) bone surrounding the central medullary cavity filled with yellow bone marrow.', '', 'Anatomie', 'Ostéologie', 'The diaphysis contains the medullary cavity.', 'La diaphyse contient la cavité médullaire.', 'يحتوي جسم العظم على التجويف النخاعي.', '/daɪˈæf.ə.sɪs/'),
(288, 'Epiphysis', 'Épiphyse', 'مشاش العظم (إبيفيز)', 'The rounded ends of a long bone.', 'Les extrémités arrondies d''un os long.', 'الأطراف المستديرة للعظمة الطويلة.', 'Greek: epi (''upon'') + physis (''growth'')', 'Contains spongy (cancellous) trabecular bone containing active hematopoiesis (red bone marrow); covered by articular hyaline cartilage.', '', 'Anatomie', 'Ostéologie', 'The epiphysis contains red bone marrow.', 'L''épiphyse contient de la moelle osseuse rouge.', 'يحتوي مشاش العظم على نخاع عظم أحمر.', '/ɪˈpɪf.ə.sɪs/'),
(289, 'Periosteum', 'Périoste', 'السمحاق', 'The fibrous membrane covering the outer surface of bones.', 'La membrane fibreuse recouvrant la surface externe des os.', 'الغشاء الليفي الذي يغطي السطح الخارجي للعظام.', 'Greek: peri (''around'') + osteon (''bone'')', 'Richly supplied with sensory nociceptive nerve fibers (responsible for extreme pain in fractures) and osteoprogenitor cells for bone repair.', '', 'Anatomie', 'Ostéologie', 'The periosteum contains cells for bone repair.', 'Le périoste contient des cellules pour la réparation osseuse.', 'يحتوي السمحاق على خلايا لإصلاح العظام.', '/ˌper.iˈɒs.ti.əm/'),
(290, 'Skeleton', 'Squelette', 'الهيكل العظمي', 'The internal framework of bones supporting the body', 'Charpente interne d''os soutenant le corps', 'الإطار الداخلي من العظام الذي يدعم الجسم', '', '', '', 'Anatomie', 'Ostéologie', 'The skeleton is the internal framework of bones supporting the body.', 'La squelette est charpente interne d''os soutenant le corps.', 'الهيكل العظمي هو الإطار الداخلي من العظام الذي يدعم الجسم.', '/ˈskɛlɪtən/'),
(291, 'Bone', 'Os', 'عظم', 'A rigid organ that constitutes part of the skeleton', 'Organe rigide constituant le squelette', 'عضو صلب يشكل جزءاً من الهيكل العظمي', '', '', '', 'Anatomie', 'Ostéologie', 'The bone is the rigid organ that constitutes part of the skeleton.', 'L''os est organe rigide constituant le squelette.', 'عظم هو عضو صلب يشكل جزءاً من الهيكل العظمي.', '/boʊn/'),
(292, 'Endosteum', 'Endoste', 'بطانة العظم', 'A thin membrane lining the inner surface of bone', 'Fine membrane tapissant la surface interne de l''os', 'غشاء رقيق يبطن السطح الداخلي للعظم', '', '', '', 'Anatomie', 'Ostéologie', 'The endosteum is the thin membrane lining the inner surface of bone.', 'L''endoste est fine membrane tapissant la surface interne de l''os.', 'بطانة العظم هو غشاء رقيق يبطن السطح الداخلي للعظم.', '/ɛnˈdɒstiəm/'),
(293, 'Bone marrow', 'Moelle osseuse', 'نخاع العظم', 'Soft tissue found inside bones that produces blood cells', 'Tissu mou à l''intérieur des os produisant les cellules sanguines', 'نسيج رخو داخل العظام ينتج خلايا الدم', '', '', '', 'Anatomie', 'Ostéologie', 'The Bone marrow pumps blood through the circulatory system.', 'Le Moelle osseuse fait le sang dans le système circulatoire.', 'يُساعد نخاع العظم على الدم عبر الجهاز الوعائي الدوراني.', '/boʊn ˈmæroʊ/'),
(294, 'Compact bone', 'Os compact (cortical)', 'العظم الكثيف', 'Dense outer layer of bone', 'Couche externe dense de l''os', 'الطبقة الخارجية الكثيفة من العظم', '', '', '', 'Anatomie', 'Ostéologie', 'The Compact bone pumps blood through the circulatory system.', 'Le Os compact (cortical) fait le sang dans le système circulatoire.', 'يُساعد العظم الكثيف على الدم عبر الجهاز الوعائي الدوراني.', '/ˈkɒmpækt boʊn/'),
(295, 'Spongy bone', 'Os spongieux (trabéculaire)', 'العظم الإسفنجي', 'Porous inner bone tissue containing bone marrow', 'Tissu osseux poreux interne contenant la moelle osseuse', 'نسيج عظمي مسامي داخلي يحتوي على نخاع العظم', '', '', '', 'Anatomie', 'Ostéologie', 'The Spongy bone pumps blood through the circulatory system.', 'Le Os spongieux (trabéculaire) fait le sang dans le système circulatoire.', 'يُساعد العظم الإسفنجي على الدم عبر الجهاز الوعائي الدوراني.', '/ˈspʌndʒi boʊn/'),
(296, 'Metaphysis', 'Métaphyse', 'الكردوس', 'The region between the diaphysis and epiphysis', 'Région entre la diaphyse et l''épiphyse', 'المنطقة الواقعة بين جسم العظم والمشاشة', '', '', '', 'Anatomie', 'Ostéologie', 'The metaphysis is the region between the diaphysis and epiphysis.', 'La métaphyse est région entre la diaphyse et l''épiphyse.', 'الكردوس هو المنطقة الواقعة بين جسم العظم والمشاشة.', '/mɛˈtæfɪsɪs/'),
(297, 'Cartilage', 'Cartilage', 'الغضروف', 'Flexible connective tissue found in joints and other structures', 'Tissu conjonctif flexible trouvé dans les articulations', 'نسيج ضام مرن يوجد في المفاصل وهياكل أخرى', '', '', '', 'Anatomie', 'Ostéologie', 'The Cartilage pumps blood through the circulatory system.', 'Le Cartilage fait le sang dans le système circulatoire.', 'يُساعد الغضروف على الدم عبر الجهاز الوعائي الدوراني.', '/ˈkɑːrtɪlɪdʒ/'),
(298, 'Ossification', 'Ossification', 'التعظم', 'The process of bone formation', 'Processus de formation osseuse', 'عملية تكوين العظم', '', '', '', 'Anatomie', 'Ostéologie', 'The ossification is the process of bone formation.', 'L''ossification est processus de formation osseuse.', 'التعظم هو عملية تكوين العظم.', '/ˌɒsɪfɪˈkeɪʃən/'),
(299, 'Foramen', 'Foramen (Trou)', 'الثقبة', 'An opening or hole in a bone', 'Ouverture ou trou dans un os', 'فتحة أو ثقب في العظم', '', '', '', 'Anatomie', 'Ostéologie', 'The foramen is the opening or hole in a bone.', 'La foramen (Trou) est ouverture ou trou dans un os.', 'الثقبة هو فتحة أو ثقب في العظم.', '/fəˈreɪmən/'),
(300, 'Process', 'Processus (Apophyse)', 'النتوء', 'A projection or outgrowth of bone', 'Saillie ou excroissance osseuse', 'بروز أو نتوء عظمي', '', '', '', 'Anatomie', 'Ostéologie', 'The process is the projection or outgrowth of bone.', 'La processus (Apophyse) est saillie ou excroissance osseuse.', 'النتوء هو بروز أو نتوء عظمي.', '/ˈprɒsɛs/'),
(301, 'Fossa', 'Fosse', 'الحفرة', 'A shallow depression in a bone', 'Dépression peu profonde dans un os', 'انخفاض ضحل في العظم', '', '', '', 'Anatomie', 'Ostéologie', 'The fossa is the shallow depression in a bone.', 'La fosse est dépression peu profonde dans un os.', 'الحفرة هو انخفاض ضحل في العظم.', '/ˈfɒsə/'),
(302, 'Condyle', 'Condyle', 'اللقمة', 'A rounded projection at the end of a bone for articulation', 'Saillie arrondie à l''extrémité d''un os pour l''articulation', 'بروز مستدير في نهاية العظم للتمفصل', '', '', '', 'Anatomie', 'Ostéologie', 'The condyle is the rounded projection at the end of a bone for articulation.', 'La condyle est saillie arrondie à l''extrémité d''un os pour l''articulation.', 'اللقمة هو بروز مستدير في نهاية العظم للتمفصل.', '/ˈkɒndaɪl/'),
(303, 'Tubercle', 'Tubercule', 'الحديبة', 'A small rounded projection on a bone', 'Petite saillie arrondie sur un os', 'بروز صغير مستدير على العظم', '', '', '', 'Anatomie', 'Ostéologie', 'The tubercle is the small rounded projection on a bone.', 'La tubercule est petite saillie arrondie sur un os.', 'الحديبة هو بروز صغير مستدير على العظم.', '/ˈtjuːbərkəl/'),
(304, 'Tuberosity', 'Tubérosité', 'الحدبة', 'A large rounded elevation on a bone', 'Grande élévation arrondie sur un os', 'ارتفاع كبير مستدير على العظم', '', '', '', 'Anatomie', 'Ostéologie', 'The tuberosity is the large rounded elevation on a bone.', 'La tubérosité est grande élévation arrondie sur un os.', 'الحدبة هو ارتفاع كبير مستدير على العظم.', '/ˌtjuːbəˈrɒsɪti/'),
(305, 'Trochanter', 'Trochanter', 'المدور', 'A large projection on the femur for muscle attachment', 'Grande saillie sur le fémur pour l''insertion musculaire', 'بروز كبير على عظم الفخذ لارتباط العضلات', '', '', '', 'Anatomie', 'Ostéologie', 'The trochanter is the large projection on the femur for muscle attachment.', 'La trochanter est grande saillie sur le fémur pour l''insertion musculaire.', 'المدور هو بروز كبير على عظم الفخذ لارتباط العضلات.', '/troʊˈkæntər/'),
(306, 'Nasal bone', 'Os nasal (propre du nez)', 'العظم الأنفي', 'One of two small bones forming the bridge of the nose', 'Un des deux petits os formant l''arête du nez', 'أحد عظمين صغيرين يشكلان جسر الأنف', '', '', '', 'Anatomie', 'Ostéologie', 'The Nasal bone pumps blood through the circulatory system.', 'Le Os nasal (propre du nez) fait le sang dans le système circulatoire.', 'يُساعد العظم الأنفي على الدم عبر الجهاز الوعائي الدوراني.', '/ˈneɪzəl boʊn/'),
